const productImagePreparedCache=new WeakMap();
function productImageExt(file){const n=String(file?.name||'').toLowerCase(),m=n.match(/\.([a-z0-9]+)$/);return m?m[1]:''}
function productImageAllowed(file){const ext=productImageExt(file),mime=String(file?.type||'').toLowerCase();return ['jpg','jpeg','png','webp','avif','heic','heif'].includes(ext)||['image/jpeg','image/png','image/webp','image/avif','image/heic','image/heif','image/heic-sequence','image/heif-sequence'].includes(mime)}
