async function decodeProductImage(file){
  if('createImageBitmap' in window){try{return await createImageBitmap(file,{imageOrientation:'from-image'})}catch(e){try{return await createImageBitmap(file)}catch(_e){}}}
  return await new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{URL.revokeObjectURL(url);resolve(img)};img.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Bild konnte im Browser nicht dekodiert werden'))};img.src=url})
}
async function prepareProductImage(file){
  if(productImagePreparedCache.has(file))return productImagePreparedCache.get(file);
  const job=(async()=>{
    if(!productImageAllowed(file))throw new Error('Erlaubt sind JPG, JPEG, PNG, WebP, AVIF, HEIC und HEIF.');
    if(Number(file.size||0)>20*1024*1024)throw new Error('Das Ausgangsbild darf maximal 20 MB groß sein.');
    try{
      const img=await decodeProductImage(file),w=Number(img.width||img.naturalWidth||0),h=Number(img.height||img.naturalHeight||0);
      if(!w||!h)throw new Error('Bildabmessungen konnten nicht gelesen werden');
      const max=2000,scale=Math.min(1,max/Math.max(w,h)),cw=Math.max(1,Math.round(w*scale)),ch=Math.max(1,Math.round(h*scale));
      const canvas=document.createElement('canvas');canvas.width=cw;canvas.height=ch;const ctx=canvas.getContext('2d',{alpha:true});if(!ctx)throw new Error('Bildoptimierung wird von diesem Browser nicht unterstützt');
      ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(img,0,0,cw,ch);if(typeof img.close==='function')img.close();
      const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.86));
      if(blob&&blob.size>0&&blob.type==='image/webp'){const base=String(file.name||'produkt').replace(/\.[^.]+$/,'').replace(/[^A-Za-z0-9._-]+/g,'-')||'produkt';return {blob,name:base+'.webp',converted:true,width:cw,height:ch,sourceType:file.type||productImageExt(file)}}
    }catch(e){
      // HEIC/HEIF may not be browser-decodable. In that case the original is sent to the server,
      // where Imagick/libheif can convert it when available.
    }
    return {blob:file,name:file.name||('produkt.'+(productImageExt(file)||'jpg')),converted:false,width:0,height:0,sourceType:file.type||productImageExt(file)}
  })();productImagePreparedCache.set(file,job);return job
}
