function employeePerformanceHtml(st){st=st||{};const daily=Array.isArray(st.daily)?st.daily:[],max=Math.max(1,...daily.map(x=>Number(x.net||0))),net=Number(st.net_revenue||0),comm=Number(st.commission||0),eff=Number(st.effective_rate||0),next=st.next_threshold,gap=Number(st.gap_to_next||0);const bars=daily.map((x,i)=>{const h=Math.max(2,Math.round(Number(x.net||0)/max*100));const label=(i===0||((i+1)%5===0)||i===daily.length-1)?String(i+1):'';return `<div class="perfBarWrap" title="${i+1}. · ${money(x.net||0)}"><i style="height:${h}%"></i><small>${label}</small></div>`}).join('');return `<section class="panel performancePanel"><div class="panelTitle"><div><h3>Meine Monatsleistung</h3><span>bezahlter Nettowarenumsatz · täglich</span></div><b>${money(net)}</b></div><div class="performanceGrid"><div class="performanceChart">${bars||'<div class="empty">Noch keine Tagesumsätze.</div>'}</div><div class="performanceFacts"><div><small>Provision aktuell</small><strong>${money(comm)}</strong><span>effektiv ${eff.toLocaleString('de-DE',{maximumFractionDigits:2})} %</span></div><div><small>Aktueller Grenzsatz</small><strong>${Number(st.commission_rate||5).toLocaleString('de-DE')} %</strong><span>nur für den aktuellen Umsatzbereich</span></div><div><small>Nächste Stufe</small><strong>${next?money(next):'Top-Stufe'}</strong><span>${next?'noch '+money(gap):'20 % auf Mehrumsatz ab 75.000 €'}</span></div></div></div></section>`}
function renderProductionDashboard(){const orders=(state.orders||[]).filter(o=>!['complete','cancelled','shipped'].includes(o.status)),uid=state.current_user?.id||'',mine=orders.filter(o=>o.production_assignee_user_id===uid),started=orders.filter(o=>productionPhaseOf(o)==='started'),waiting=orders.filter(o=>productionPhaseOf(o)==='waiting'),quality=orders.filter(o=>productionPhaseOf(o)==='quality'),due=orders.filter(o=>prodDueMeta(o).days<=1).sort((a,b)=>prodDueMeta(a).days-prodDueMeta(b).days),low=(state.inventory||[]).filter(x=>+x.stock<=+x.minimum).length;ws.innerHTML=`<div class="roleBanner fieldRole productionRole"><div><b>Produktion · Fertigungszugang</b><span>Aufträge bearbeiten, Fortschritt dokumentieren und jeden ausgeführten Arbeitsschritt automatisch deinem Benutzerkonto zuordnen.</span></div><strong>${esc(state.current_user?.display_name||'')}</strong></div><div class="quickCreateBar"><div><b>Fertigung</b><span>Keine Vertriebs-, Umsatz- oder Provisionsdaten in diesem Zugang.</span></div><div class="quickCreateActions"><button class="btn primary" id="prodDashOpen">Produktion öffnen</button>${can('view_inventory')?'<button class="btn" id="prodDashStock">Lager ansehen</button>':''}${can('view_messages')?'<button class="btn" id="prodDashMessages">Nachrichten</button>':''}</div></div><div class="metricGrid">${metric('Meine Aufträge',mine.length,'mir zugewiesen')}${metric('Arbeit begonnen',started.length,'aktive Fertigung')}${metric('Wartet auf Start',waiting.length,'bezahlt · noch nicht begonnen',waiting.length?'attn':'')}${metric('Qualitätsprüfung',quality.length,'in QS')}${metric('Heute / morgen fällig',due.length,'Priorität prüfen',due.length?'attn':'')}${metric('Lagerwarnungen',low,'unter Mindestbestand',low?'attn':'')}</div><div class="dashGrid"><section class="panel"><div class="panelTitle"><h3>Meine Fertigungsaufträge</h3><span>${mine.length} aktiv</span></div>${mine.length?mine.slice(0,10).map(o=>`<button class="orderMini" style="width:100%;border:0;background:#fff;text-align:left" data-production-edit="${esc(o.order_no||o.id)}"><b>${esc(o.order_no||o.id)}</b><span class="customer"><strong>${esc(orderCustomer(o))}</strong><small>${esc(prodStepMeta(o.production_step)[1])} · ${prodProgress(o)} % · ${esc(o.production_station||'kein Arbeitsplatz')}</small></span>${prodPriorityBadge(o.production_priority||'normal')}</button>`).join(''):'<div class="empty"><b>Keine Aufträge zugewiesen</b>Neue Aufträge erscheinen nach der Zuweisung durch die Administration oder wenn du einen freien Auftrag übernimmst.</div>'}</section><section class="panel"><div class="panelTitle"><h3>Als Nächstes</h3><span>Fälligkeit</span></div><div class="quickList">${due.slice(0,8).map(o=>quick(o.order_no||o.id,prodDueMeta(o).label,`${orderCustomer(o)} · ${prodStepMeta(o.production_step)[1]}`)).join('')||'<div class="empty">Keine kurzfristig fälligen Aufträge.</div>'}</div></section></div>`;$('#prodDashOpen').onclick=()=>setView('production');if($('#prodDashStock'))$('#prodDashStock').onclick=()=>setView('inventory');if($('#prodDashMessages'))$('#prodDashMessages').onclick=()=>setView('messages');$$('[data-production-edit]').forEach(b=>b.onclick=()=>productionEditModal(b.dataset.productionEdit))}

function executiveOrderMonthStats(){
 const orders=(state.orders||[]).filter(o=>o.status!=='cancelled'),now=new Date(),ym=(d)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
 const cur=ym(now),prevDate=new Date(now.getFullYear(),now.getMonth()-1,1),prev=ym(prevDate);
 const curRows=orders.filter(o=>String(o.created_at||'').slice(0,7)===cur),prevRows=orders.filter(o=>String(o.created_at||'').slice(0,7)===prev);
 const gross=a=>a.reduce((s,o)=>s+Number(orderTotal(o)||0),0),paid=a=>a.filter(o=>o.payment_status==='paid').reduce((s,o)=>s+Number(orderTotal(o)||0),0);
 const currentGross=gross(curRows),previousGross=gross(prevRows),delta=previousGross?((currentGross-previousGross)/previousGross*100):(currentGross?100:0);
 return {curRows,prevRows,currentGross,previousGross,currentPaid:paid(curRows),previousPaid:paid(prevRows),delta,aov:curRows.length?currentGross/curRows.length:0};
}
function executiveDonut(value,label,sub,cls='green'){value=Math.max(0,Math.min(100,Math.round(Number(value)||0)));return `<div class="execDonut ${cls}" style="--p:${value}%"><div><b>${value}%</b><span>${esc(label)}</span><small>${esc(sub)}</small></div></div>`}
function executiveMiniBars(items,maxValue=0){const max=Math.max(maxValue,...items.map(x=>Number(x.value||0)),1);return `<div class="execBars">${items.map(x=>`<div class="execBarRow"><span>${esc(x.label)}</span><div><i style="width:${Math.max(2,Math.round(Number(x.value||0)/max*100))}%"></i></div><b>${typeof x.display==='string'?x.display:Number(x.value||0).toLocaleString('de-DE')}</b></div>`).join('')}</div>`}
function executivePriorityItems(){const orders=state.orders||[],wh=ensureWarehouse(),low=warehouseLowInventory(),lowPack=warehouseLowPackaging(),items=[];const payment=orders.filter(o=>o.payment_status!=='paid'&&!['cancelled','complete'].includes(o.status));if(payment.length)items.push({level:'red',title:`${payment.length} Zahlungen offen`,text:'Offene Zahlungen prüfen, bevor Produktion oder Versand blockiert wird.',view:'orders'});const ready=orders.filter(o=>o.status==='ready');if(ready.length)items.push({level:'orange',title:`${ready.length} Aufträge versandbereit`,text:'Pakete, Label und Tracking abarbeiten.',view:'shipping'});if(low.length+lowPack.length)items.push({level:'red',title:`${low.length+lowPack.length} Lagerwarnungen`,text:'Bestände bzw. Packmittel liegen am oder unter Meldebestand.',view:'inventory'});const territories=(state.sales_territories||[]).filter(t=>!t.owner_sales_rep_id);if(territories.length)items.push({level:'gold',title:`${territories.length} Weißgebiete`,text:'Festgebiete ohne verantwortlichen Kundenberater.',view:'territories'});const nat=state.territory_directory_national_summary||{};if(Number(nat.candidate||0)>0)items.push({level:'blue',title:`${Number(nat.candidate||0).toLocaleString('de-DE')} Rechercheadressen`,text:'Gefundene Branchenkontakte warten auf Prüfung/Freigabe.',view:'territorybook'});if(!items.length)items.push({level:'green',title:'Keine kritischen Engpässe',text:'Der operative Leitstand zeigt aktuell keine dringenden Blocker.',view:'dashboard'});return items.slice(0,6)}
