 <div class="executiveKpiGrid"><article><small>Umsatz heute</small><strong>${money(todayRevenue)}</strong><span>${today.length} Auftrag/Aufträge heute</span></article><article><small>Umsatz Monat</small><strong>${money(stats.currentGross)}</strong><span class="${deltaClass}">${deltaText}</span></article><article><small>Ø Warenkorb Monat</small><strong>${money(stats.aov)}</strong><span>${stats.curRows.length} Aufträge im Monat</span></article><article><small>Operativ offen</small><strong>${open}</strong><span>${prod} Fertigung · ${ready} versandbereit</span></article><article><small>Lagerwarnungen</small><strong>${low.length+lowPack.length}</strong><span>${po.length} offene Beschaffung</span></article><article><small>Festgebiete besetzt</small><strong>${fixed}/16</strong><span>${activeReps.length} aktive Vertriebskonten</span></article></div>
