 <div class="executiveGrid"><section class="panel"><div class="panelTitle"><h3>Vertrieb · Top Leistung</h3><span>aktueller Stand</span></div>${topReps.length?executiveMiniBars(topReps.map(r=>({label:r.name,value:Number(r.stats_current?.gross_goods||r.revenue||0),display:money(r.stats_current?.gross_goods||r.revenue||0)}))):'<div class="empty">Noch keine Vertriebsumsätze.</div>'}<div class="formActions"><button class="btn" data-exec-view="salesreps">Vertriebsorganisation öffnen</button></div></section><section class="panel"><div class="panelTitle"><h3>Gebiete · Umsatzschwerpunkte</h3><span>Festgebiete</span></div>${topTerritories.length?executiveMiniBars(topTerritories.map(t=>({label:t.state_name,value:Number(t.revenue||0),display:money(t.revenue||0)}))):'<div class="empty">Noch keine Gebietsumsätze.</div>'}<div class="formActions"><button class="btn" data-exec-view="territories">Deutschlandkarte öffnen</button></div></section></div>
