function metric(l,v,s,c=''){return `<div class="metric ${c}"><small>${l}</small><strong>${v}</strong><span>${s}</span></div>`}
function quick(l,v,s){return `<div class="quickItem"><div><b>${l}</b><small>${s}</small></div><strong>${v}</strong></div>`}
function priorityLines(payOpen,ship,low,protos){const a=[];if(payOpen)a.push(`<li>${payOpen} Zahlung(en) noch offen.</li>`);if(ship)a.push(`<li>${ship} Bestellung(en) sind versandbereit.</li>`);if(low)a.push(`<li>${low} Lagerposition(en) unter Mindestbestand.</li>`);const p=protos.filter(x=>['new','paid','review'].includes(x.status)).length;if(p)a.push(`<li>${p} Prototyp-Projekt(e) benötigen Bearbeitung.</li>`);if(!a.length)a.push('<li>Aktuell keine kritischen Aufgaben.</li>');return a.join('')}
function orderMini(o){return `<button class="orderMini" style="width:100%;border:0;background:#fff;text-align:left" data-open-order="${esc(o.order_no||o.id)}"><b>${esc(o.order_no||o.id)}</b><span class="customer"><strong>${esc(orderCustomer(o))}</strong><small>${dt(o.created_at)} · ${esc(o.sales_channel_label||salesChannelLabel(o.sales_channel||o.source))} · ${itemCount(o)} Position(en)</small></span><span class="amount">${money(orderTotal(o))}</span>${status(o.status)}</button>`}

function filteredOrders(){const q=(searchTerm||$('#orderFilter')?.value||'').toLowerCase().trim(),sf=$('#orderStatusFilter')?.value||'',cf=$('#orderChannelFilter')?.value||'';return (state.orders||[]).filter(o=>(!q||`${o.order_no} ${orderCustomer(o)} ${orderEmail(o)} ${o.customer?.city||''} ${o.sales_channel_label||''} ${commissionRepName(o)} ${o.commission_note||''}`.toLowerCase().includes(q))&&(!sf||o.status===sf)&&(!cf||o.sales_channel===cf))}
function renderOrders(){const opts=Object.entries(state.order_statuses||{}).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join(''),channels=['online','advisor','telephone','email','walk_in','marketplace','other'];ws.innerHTML=`<div class="sectionHead"><div><h2>Bestellungen</h2><p>Verkaufsherkunft, Kundenberater, Provision, Zahlung, Fertigung und Versand nachvollziehbar an einem Ort.</p></div><div class="sectionActions"><button class="btn" id="exportOrders">CSV exportieren</button><button class="btn primary" id="reloadOrders">Aktualisieren</button></div></div><div class="salesAttributionNotice"><div><b>Klare Zuordnung statt Schätzung</b><span>Die Herkunft bleibt unverändert. Die Provisionsgutschrift wird separat nach Kundenbeziehung ermittelt.</span></div><strong>V69 · automatische Prüfung</strong></div>
<div class="toolbar"><input class="filterInput" id="orderFilter" placeholder="Bestellnummer, Kunde, Herkunft, Berater …" value="${esc(searchTerm)}"><select class="filterSelect" id="orderStatusFilter"><option value="">Alle Status</option>${opts}</select><select class="filterSelect" id="orderChannelFilter"><option value="">Alle Herkünfte</option>${channels.map(x=>`<option value="${x}">${salesChannelLabel(x)}</option>`).join('')}</select></div><div class="panel tableWrap" id="ordersTable"></div>`;renderOrdersTable();$('#orderFilter').oninput=renderOrdersTable;$('#orderStatusFilter').onchange=renderOrdersTable;$('#orderChannelFilter').onchange=renderOrdersTable;$('#reloadOrders').onclick=()=>load();$('#exportOrders').onclick=exportOrders}
function renderOrdersTable(){const rows=filteredOrders(),host=$('#ordersTable');if(!rows.length){host.innerHTML='<div class="empty"><b>Keine Treffer</b>Für diesen Filter gibt es keine Bestellungen.</div>';return}host.innerHTML=`<table class="dataTable orderAttributionTable"><thead><tr><th>Bestellung</th><th>Kunde</th><th>Datum</th><th>Herkunft</th><th>Status</th><th>Zahlung</th><th>Provision an</th><th>Gesamt</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><button class="rowLink" data-open-order="${esc(o.order_no||o.id)}">${esc(o.order_no||o.id)}</button></td><td class="customerCell"><b>${esc(orderCustomer(o))}</b><small>${esc(orderEmail(o))}</small></td><td>${dt(o.created_at)}</td><td>${salesOriginTag(o)}</td><td>${status(o.status)}</td><td>${pay(o.payment_status||'pending')}</td><td>${commissionCreditTag(o)}</td><td class="money">${money(orderTotal(o))}</td><td><button class="miniBtn" data-open-order="${esc(o.order_no||o.id)}">Öffnen</button></td></tr>`).join('')}</tbody></table>`}
function openOrder(id){const o=(state.orders||[]).find(x=>(x.order_no||x.id)===id);if(!o)return;const c=o.customer||{},tot=o.totals||{},edit=can('edit_orders'),admin=isAdmin(),channels=['online','advisor','telephone','email','walk_in','marketplace','other'];openModal(`<div class="modalHead"><small>BESTELLUNG · VERKAUFSZUORDNUNG</small><h2>${esc(o.order_no||o.id)}</h2><p>${dt(o.created_at)} · ${esc(orderCustomer(o))}</p></div><div class="modalBody"><div class="orderAttributionHero"><div><small>VERKAUFSHERKUNFT</small>${salesOriginTag(o)}</div><div><small>PROVISIONSGUTSCHRIFT</small><strong>${esc(commissionRepName(o))}</strong><span>${esc(attributionLabel(o))}</span></div><div class="attributionReason"><small>BEGRÜNDUNG</small><b>${esc(o.commission_note||'Zuordnung noch nicht dokumentiert')}</b></div></div><div class="detailGrid">
<div class="detailBox"><h4>Kunde</h4><p><b>${esc(c.name||orderCustomer(o))}</b><br>${esc(c.street||'')}<br>${esc(c.zip||'')} ${esc(c.city||'')}<br>${esc(c.email||'')}<br>${esc(c.phone||'')}</p>${o.sales_rep_name?`<div class="customerOwnerBadge"><small>FESTER KUNDENBERATER</small><b>${esc(o.sales_rep_name)}</b></div>`:''}${o.customer_id?`<button class="miniBtn" id="orderEditCustomer">Kundenakte öffnen</button>`:''}</div>
<div class="detailBox"><h4>Auftragsstatus</h4>${edit?`<div class="formGrid"><label>Status<select id="moStatus">${statusOptions(state.order_statuses,o.status)}</select></label><label>Zahlung<select id="moPayment"><option value="pending" ${sel(o.payment_status,'pending')}>offen</option><option value="paid" ${sel(o.payment_status,'paid')}>bezahlt</option><option value="refunded" ${sel(o.payment_status,'refunded')}>erstattet</option><option value="cancelled" ${sel(o.payment_status,'cancelled')}>storniert</option></select></label><label>Versanddienst<input id="moCarrier" value="${esc(o.carrier||'DPD')}"></label><label>Tracking<input id="moTracking" value="${esc(o.tracking||'')}"></label>${admin?`<label>Verkaufsherkunft<select id="moSalesChannel">${channels.map(x=>`<option value="${x}" ${sel(o.sales_channel,x)}>${salesChannelLabel(x)}</option>`).join('')}</select></label><label>Provisionsempfänger<select id="moCommissionRep"><option value="">Nicht zugeordnet</option>${(state.sales_reps||[]).filter(r=>r.status==='active'||r.id===o.commission_sales_rep_id).map(r=>`<option value="${esc(r.id)}" ${sel(o.commission_sales_rep_id||o.sales_rep_id,r.id)}>${esc(r.employee_no||'')} · ${esc(r.name)}</option>`).join('')}</select></label>`:''}</div>`:`<p>Status: <b>${esc(state.order_statuses?.[o.status]||o.status)}</b><br>Zahlung: <b>${o.payment_status==='paid'?'Bezahlt':'Offen'}</b><br>Versanddienst: <b>${esc(o.carrier||'DPD')}</b><br>Tracking: <b>${esc(o.tracking||'–')}</b></p>`}</div>
<div class="detailBox full"><h4>Artikel</h4><table class="detailItems">${(o.items||[]).map(x=>`<tr><td>${Number(x.qty||1)} × ${esc(x.name||x.id)}${x.article_no?`<br><small>Art.-Nr. ${esc(x.article_no)}</small>`:''}${itemMeta(x)?`<br><small>${esc(itemMeta(x))}</small>`:''}</td><td>${money(x.unit_price||x.price||0)}</td><td>${money((x.unit_price||x.price||0)*(x.qty||1))}</td></tr>`).join('')}</table><div class="detailTotals"><div><span>Warenwert</span><b>${money(tot.subtotal||0)}</b></div><div><span>Versand</span><b>${money(tot.shipping||0)}</b></div><div><span>inkl. MwSt.</span><b>${money(tot.vat||0)}</b></div>${Number(tot.shipping_weight_g||0)>0?`<div><span>Versandgewicht</span><b>${weightLabel(tot.shipping_weight_g)}</b></div>`:''}<div class="grand"><span>Gesamt</span><b>${money(tot.gross||orderTotal(o))}</b></div></div></div>
<div class="detailBox full"><h4>Interne Notiz</h4>${edit?`<textarea id="moNote" style="width:100%;min-height:80px;border:1px solid #ded5cb;border-radius:8px;padding:9px">${esc(o.internal_note||'')}</textarea>`:`<p>${esc(o.internal_note||'Keine Notiz').replace(/\n/g,'<br>')}</p>`}</div>
${(o.history||[]).length?`<div class="detailBox full"><h4>Verlauf</h4><div class="history">${[...(o.history||[])].reverse().slice(0,14).map(h=>`<div><time>${dt(h.at)}</time><b>${esc(h.type||'')}</b><span>${esc(h.value||'')}</span></div>`).join('')}</div></div>`:''}
</div><div class="formActions"><button class="btn" id="invoiceDocBtn">Rechnung</button><button class="btn" id="deliveryDocBtn">Lieferschein</button>${edit?'<button class="btn primary" id="saveOrderBtn">Änderungen speichern</button>':''}</div></div>`);
 if($('#orderEditCustomer'))$('#orderEditCustomer').onclick=()=>{closeModal();if(o.customer_id)openCustomer(o.customer_id)};
 $('#invoiceDocBtn').onclick=()=>openDocumentForOrder(o.order_no||o.id,'invoice');$('#deliveryDocBtn').onclick=()=>openDocumentForOrder(o.order_no||o.id,'delivery_note');
 if(edit&&$('#saveOrderBtn'))$('#saveOrderBtn').onclick=async()=>{try{const payload={action:'order_update',id:o.order_no||o.id,status:$('#moStatus').value,payment_status:$('#moPayment').value,carrier:$('#moCarrier').value,tracking:$('#moTracking').value,internal_note:$('#moNote').value};if(admin){payload.sales_channel=$('#moSalesChannel').value;payload.commission_sales_rep_id=$('#moCommissionRep').value}await api(payload);toast('Bestellung und Verkaufszuordnung aktualisiert');closeModal();await load(true)}catch(e){toast(e.message,true)}}
}
function statusOptions(labels,current){return Object.entries(labels||{}).map(([k,v])=>`<option value="${k}" ${sel(current,k)}>${esc(v)}</option>`).join('')}
function sel(a,b){return a===b?'selected':''}

function productionItemSummary(o){const items=o.items||[];if(!items.length)return'–';const first=items.slice(0,2).map(x=>`${Number(x.qty||1)} × ${esc(x.name||x.id)}`).join('<br>');return first+(items.length>2?`<small class="tableSub">+ ${items.length-2} weitere Position(en)</small>`:'')}
function productionStageSelect(o){if(!can('edit_orders'))return status(o.status);return `<select class="productionStatusSelect" data-production-status="${esc(o.order_no||o.id)}">${statusOptions(state.order_statuses,o.status)}</select>`}
function renderProductionLegacyV57(){const stages=[['new','Neu'],['paid','Bezahlt'],['production','Fertigung'],['quality','Qualitätskontrolle'],['packing','Verpacken'],['ready','Versandbereit'],['shipped','Versendet']];const orders=(state.orders||[]).filter(o=>!['complete','cancelled','payment_pending'].includes(o.status));const kpis=[['Offen',orders.filter(o=>['new','paid'].includes(o.status)).length],['In Fertigung',orders.filter(o=>o.status==='production').length],['Qualitätsprüfung',orders.filter(o=>o.status==='quality').length],['Versandbereit',orders.filter(o=>o.status==='ready').length]];ws.innerHTML=`<div class="sectionHead"><div><h2>Produktion</h2><p>Aufträge im Querformat bearbeiten – Status, Artikel, Kunde und Bearbeitung auf einen Blick.</p></div><div class="sectionActions"><button class="btn ${productionViewMode==='table'?'primary':''}" id="productionTableView">▤ Tabelle</button><button class="btn ${productionViewMode==='board'?'primary':''}" id="productionBoardView">▦ Board</button></div></div><div class="productionKpis">${kpis.map(x=>`<div><small>${x[0]}</small><strong>${x[1]}</strong></div>`).join('')}</div>${productionViewMode==='table'?`<div class="panel tableWrap productionLandscape"><table class="dataTable productionTable"><thead><tr><th>Auftrag</th><th>Kunde</th><th>Artikel / Menge</th><th>Zahlung</th><th>Produktionsstatus</th><th>Berater</th><th>Auftrag vom</th><th>Gesamt</th><th>Bearbeiten</th></tr></thead><tbody>${orders.length?orders.map(o=>`<tr><td><button class="rowLink" data-open-order="${esc(o.order_no||o.id)}">${esc(o.order_no||o.id)}</button></td><td class="customerCell"><b>${esc(orderCustomer(o))}</b><small>${esc(o.customer?.company||orderEmail(o)||'')}</small></td><td class="productionItems">${productionItemSummary(o)}</td><td>${pay(o.payment_status||'pending')}</td><td>${productionStageSelect(o)}</td><td>${esc(repName(o.sales_rep_id))}</td><td>${dt(o.created_at)}</td><td class="money">${money(orderTotal(o))}</td><td><button class="miniBtn productionEditBtn" data-open-order="${esc(o.order_no||o.id)}">Bearbeiten</button></td></tr>`).join(''):`<tr><td colspan="9"><div class="empty"><b>Keine Produktionsaufträge</b>Aktuell sind keine offenen Fertigungsaufträge vorhanden.</div></td></tr>`}</tbody></table></div>`:`<div class="kanban">${stages.map(([st,l])=>`<section class="kanCol" data-drop-status="${st}"><div class="kanHead"><b>${l}</b><span>${orders.filter(o=>o.status===st).length}</span></div><div class="kanBody">${orders.filter(o=>o.status===st).map(kanCard).join('')}</div></section>`).join('')}</div>`}`;$('#productionTableView').onclick=()=>{productionViewMode='table';renderProduction()};$('#productionBoardView').onclick=()=>{productionViewMode='board';renderProduction()};if(productionViewMode==='table'&&can('edit_orders'))$$('[data-production-status]').forEach(el=>el.onchange=async()=>{el.disabled=true;try{await api({action:'order_update',id:el.dataset.productionStatus,status:el.value});toast('Produktionsstatus gespeichert');await load(true);if(current==='production')renderProduction()}catch(e){toast(e.message,true);el.disabled=false}});if(productionViewMode==='board'){if(can('edit_orders'))initKanban();else $$('.kanCard').forEach(c=>{c.draggable=false;c.ondblclick=()=>openOrder(c.dataset.orderId)})}}
function kanCard(o){return `<article class="kanCard" draggable="true" data-order-id="${esc(o.order_no||o.id)}"><b>${esc(o.order_no||o.id)}</b><strong>${esc(orderCustomer(o))}</strong><small>${itemCount(o)} Position(en) · ${money(orderTotal(o))}</small><footer><span>${donly(o.created_at)}</span>${pay(o.payment_status||'pending')}</footer></article>`}
function initKanban(){let dragged='';$$('.kanCard').forEach(c=>{c.ondragstart=()=>{dragged=c.dataset.orderId;c.classList.add('dragging')};c.ondragend=()=>{c.classList.remove('dragging');$$('.kanCol').forEach(x=>x.classList.remove('dragOver'))};c.ondblclick=()=>openOrder(c.dataset.orderId)});$$('.kanCol').forEach(col=>{col.ondragover=e=>{e.preventDefault();col.classList.add('dragOver')};col.ondragleave=()=>col.classList.remove('dragOver');col.ondrop=async e=>{e.preventDefault();col.classList.remove('dragOver');if(!dragged)return;try{await api({action:'order_update',id:dragged,status:col.dataset.dropStatus});toast('Produktionsstatus aktualisiert');await load(true)}catch(err){toast(err.message,true)}}})}

function renderPrototypes(){const q=(searchTerm||'').toLowerCase();const rows=(state.prototypes||[]).filter(p=>!q||`${p.reference} ${p.customer?.name||p.fields?.customer_name||''} ${p.project_name||p.fields?.project_name||''}`.toLowerCase().includes(q));ws.innerHTML=`<div class="sectionHead"><div><h2>Prototypen</h2><p>149-€-Projekte von Anfrage bis Fertigstellung steuern.</p></div></div><div class="panel tableWrap">${rows.length?`<table class="dataTable"><thead><tr><th>Projekt</th><th>Kunde</th><th>Bezeichnung</th><th>Status</th><th>Zahlung</th><th>Datum</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="rowLink" data-open-proto="${esc(p.reference||p.id)}">${esc(p.reference||p.id)}</button></td><td>${esc(p.customer?.name||p.fields?.customer_name||'–')}</td><td>${esc(p.project_name||p.fields?.project_name||'–')}</td><td>${status(p.status,state.prototype_statuses)}</td><td>${pay(p.payment_status||'pending')}</td><td>${dt(p.created_at)}</td><td><button class="miniBtn" data-open-proto="${esc(p.reference||p.id)}">Öffnen</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty"><b>Noch keine Prototypen</b>Übermittelte Prototypenanfragen erscheinen automatisch.</div>'}</div>`}
function openPrototype(id){const p=(state.prototypes||[]).find(x=>(x.reference||x.id)===id);if(!p)return;const f=p.fields||{},c=p.customer||{},edit=can('edit_prototypes');openModal(`<div class="modalHead"><small>PROTOTYP-PROJEKT</small><h2>${esc(p.reference||p.id)}</h2><p>${esc(p.project_name||f.project_name||'Sonderanfertigung')} · ${dt(p.created_at)}</p></div><div class="modalBody"><div class="detailGrid"><div class="detailBox"><h4>Kunde</h4><p><b>${esc(c.name||f.customer_name||'–')}</b><br>${esc(c.email||f.email||'')}<br>${esc(c.phone||f.phone||'')}<br>${esc(f.street||'')}<br>${esc(f.zip||'')} ${esc(f.city||'')}</p></div><div class="detailBox"><h4>Bearbeitung</h4>${edit?`<div class="formGrid"><label>Status<select id="mpStatus">${statusOptions(state.prototype_statuses,p.status)}</select></label><label>Tracking<input id="mpTracking" value="${esc(p.tracking||'')}"></label></div>`:`<p>Status: <b>${esc(state.prototype_statuses?.[p.status]||p.status)}</b><br>Tracking: <b>${esc(p.tracking||'–')}</b></p>`}</div><div class="detailBox full"><h4>Projektangaben</h4><p>${esc(p.summary||f.summary||'Keine Zusammenfassung vorhanden.').replace(/\n/g,'<br>')}</p></div>${(p.files||[]).length?`<div class="detailBox full"><h4>Dateien</h4>${p.files.map(x=>`<div>${esc(x.original||x.stored)} · ${Math.round((x.size||0)/1024)} KB</div>`).join('')}</div>`:''}<div class="detailBox full"><h4>Interne Notiz</h4>${edit?`<textarea id="mpNote" style="width:100%;min-height:85px;border:1px solid #ded5cb;border-radius:8px;padding:9px">${esc(p.internal_note||'')}</textarea>`:`<p>${esc(p.internal_note||'Keine Notiz').replace(/\n/g,'<br>')}</p>`}</div></div>${edit?'<div class="formActions"><button class="btn primary" id="saveProtoBtn">Projekt aktualisieren</button></div>':''}</div>`);if(edit&&$('#saveProtoBtn'))$('#saveProtoBtn').onclick=async()=>{try{await api({action:'prototype_update',id:p.reference||p.id,status:$('#mpStatus').value,tracking:$('#mpTracking').value,internal_note:$('#mpNote').value});toast('Prototyp aktualisiert');closeModal();await load(true)}catch(e){toast(e.message,true)}}}
function repName(id){if(!id)return'–';const r=(state.sales_reps||[]).find(x=>x.id===id);if(r)return r.name;if(String(state.current_user?.sales_rep_id||'')===String(id))return state.current_user?.display_name||'Eigener Kundenberater';return'–'}
function salesChannelLabel(v){return ({online:'Online-Shop',advisor:'Kundenberater',telephone:'Telefonleitung',email:'E-Mail',walk_in:'Vor Ort / Abholung',marketplace:'An- & Verkaufen',other:'Sonstiges',shop:'Online-Shop',field:'Kundenberater',phone:'Telefonleitung'})[v]||v||'Sonstiges'}
function commissionRepName(o){return o?.commission_sales_rep_name||repName(o?.commission_sales_rep_id||o?.sales_rep_id)}
function attributionLabel(o){return o?.commission_attribution_label||({returning_customer:'Wiederkehrender Beraterkunde',direct_advisor:'Direkter Kundenberater-Verkauf',house_rotation:'Hausverteilung ohne Beraterkontakt',admin_override:'Manuell geprüft / korrigiert',legacy_assigned:'Bestehende Beraterzuordnung',legacy_unassigned:'Altauftrag ohne eindeutige Zuordnung'})[o?.commission_attribution]||'Noch nicht zugeordnet'}
function salesOriginTag(o){return `<span class="salesOriginTag origin-${esc(o?.sales_channel||'other')}">${esc(o?.sales_channel_label||salesChannelLabel(o?.sales_channel||o?.source))}</span>`}
function commissionCreditTag(o){const n=commissionRepName(o);return `<span class="commissionCreditTag"><b>${esc(n)}</b><small>${esc(attributionLabel(o))}</small></span>`}
function customerOwnerName(c){return c?.sales_rep_name||repName(c?.sales_rep_id)}
function isMyCustomer(c){return !!c?.sales_rep_id&&String(c.sales_rep_id)===String(state.current_user?.sales_rep_id||'')}
function repOptions(current=''){if(!isAdmin()){const rid=state.current_user?.sales_rep_id||current||'';return rid?`<option value="${esc(rid)}" selected>Eigener Kundenberater · ${esc(state.current_user?.display_name||'')}</option>`:'<option value="">Nicht zugeordnet</option>'}return `<option value="">Nicht zugeordnet</option>`+(state.sales_reps||[]).filter(r=>(r.status==='active'||r.id===current)&&!String(r.employee_no||'').startsWith('ZENTRALE-')).map(r=>`<option value="${esc(r.id)}" ${sel(current,r.id)}>${esc(r.employee_no)} · ${esc(r.name)}</option>`).join('')}
function splitCustomerStreet(value){const raw=String(value||'').trim();if(!raw)return{street:'',house:''};const m=raw.match(/^(.*?)[,\s]+(\d+[a-zA-Z]?(?:\s*[\/-]\s*\d+[a-zA-Z]?)?)$/);return m?{street:m[1].trim(),house:m[2].replace(/\s+/g,'')}:{street:raw,house:''}}
function customerStreetValue(){const street=$('#cuStreetName')?.value.trim()||'',house=$('#cuHouseNo')?.value.trim()||'';return [street,house].filter(Boolean).join(' ').trim()}
function customerAddressValue(){return [customerStreetValue(),$('#cuZip')?.value.trim()||'',($('#cuCitySelect')?.value||$('#cuCityManual')?.value||'').trim()].filter(Boolean).join(', ')}
function googleMapsEmbedUrl(address){return 'https://www.google.com/maps?q='+encodeURIComponent(address)+'&output=embed'}
function googleMapsSearchUrl(address){return 'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(address)}
