const loadStreetPage=async(page=1,term='',token=streetToken)=>{const d=await api({action:'address_streets',zip:zipInput.value.trim(),city:selectedCity(),term,page});if(token!==streetToken)return null;(d.streets||[]).forEach(x=>streetNames.add(String(x.name||x).trim()));renderStreetList();return d};
const loadStreets=async(reset=true)=>{const zip=zipInput.value.trim(),city=selectedCity();if(zip.length!==5||!city||city==='__manual__')return;if(reset){streetNames=new Set();renderStreetList()}const token=++streetToken;streetHint.textContent='Straßen werden geladen …';setStatus('Straßen laden','loading');try{let total=0,capped=false;for(let page=1;page<=8;page++){const d=await loadStreetPage(page,'',token);if(!d||token!==streetToken)return;const n=(d.streets||[]).length;total+=n;if(n<50)break;if(page===8)capped=true}streetHint.textContent=streetNames.size?`${streetNames.size} Straße${streetNames.size===1?'':'n'} geladen${capped?' · bei Bedarf Anfangsbuchstaben tippen':''}`:'Keine Straßenliste gefunden · Eingabe bleibt manuell möglich';setStatus(streetNames.size?'Straßen bereit':'Manuelle Eingabe','good')}catch(e){streetHint.textContent='Straßendienst nicht erreichbar · Straße kann manuell eingetragen werden';setStatus('Manuell möglich','warn')}};
