function hookLengths(id){return ({std:['12 cm','14 cm','18 cm','20 cm','24 cm'],aal:['12 cm','14 cm','18 cm','20 cm','24 cm'],ultra:['20 cm','22 cm','24 cm'],kralle:['18 cm','20 cm','24 cm'],filet:['12 cm','14 cm','18 cm','20 cm','24 cm'],doppel:['12 cm','14 cm','18 cm','20 cm','24 cm']})[id]||[]}
function estimatePrice(p,meta={}){if(!p)return 0;if(p.type!=='hook')return Number(p.base||0);const lp={std:{'12 cm':12.90,'14 cm':14.80,'18 cm':15.80,'20 cm':16.80,'24 cm':18.80},aal:{'12 cm':12.90,'14 cm':14.80,'18 cm':15.80,'20 cm':16.80,'24 cm':18.80},kralle:{'18 cm':18.90,'20 cm':19.90,'24 cm':21.90},filet:{'12 cm':15.90,'14 cm':17.80,'18 cm':18.80,'20 cm':19.80,'24 cm':21.80},doppel:{'12 cm':15.90,'14 cm':17.80,'18 cm':18.80,'20 cm':19.80,'24 cm':21.80},ultra:{'20 cm':19.90,'22 cm':23.90,'24 cm':24.90}};let v=Number(lp[p.id]?.[meta.length]??p.base??0);v+=({VA:0,V2A:3.99,V4A:7.99})[meta.material||'VA']||0;if(meta.tip==='extra')v+=2;return Math.round(v*100)/100}
function recommendForNeeds(n){const rec=[];const add=id=>{if((state.catalog||[]).some(p=>p.id===id&&p.status==='active')&&!rec.includes(id))rec.push(id)};const purpose=n.purpose||'fish',fish=n.fish||'forelle',weight=Number(n.weight||2),form=n.form||'whole',priority=n.priority||'standard';if(purpose==='fish'){if(form==='filet')add('filet');else if(fish==='aal')add('aal');else if(weight>5||priority==='heavy')add('ultra');else if(priority==='secure')add('kralle');else add('std');if(fish==='aal')add('lauge-aal-0');else add('lauge-forelle-0');if(fish==='lachs')add('mehl-erle');else add('mehl-buche')}else if(purpose==='meat'){add('fleisch');add('mehl-buche');add('mehl-eiche')}else if(purpose==='smoke'){activeCatalog().filter(p=>String(p.category).toLowerCase().includes('räuchermehl')).slice(0,4).forEach(p=>add(p.id))}else if(purpose==='brine'){activeCatalog().filter(p=>String(p.category).toLowerCase().includes('räucherlauge')).slice(0,4).forEach(p=>add(p.id))}else{activeCatalog().slice(0,4).forEach(p=>add(p.id))}return rec.slice(0,6)}
