function renderSales(){const c=(state.customers||[]).find(x=>x.id===salesCustomerId)||null;const needs=salesAdvice?.needs||{};const recs=(salesAdvice?.recs||[]).map(id=>(state.catalog||[]).find(p=>p.id===id)).filter(Boolean);ws.innerHTML=`<div class="sectionHead"><div><h2>Produktberatung</h2><p>Kundenbedarf aufnehmen und passende Artikel aus dem Sortiment empfehlen.</p></div><div class="sectionActions">${can('edit_customers')?'<button class="btn" id="salesNewCustomer">+ Kunde</button>':''}${can('create_orders')&&c?'<button class="btn primary" id="salesNewOrder">+ Bestellung für Kunden</button>':''}</div></div>${!isAdmin()?'<div class="moduleNotice"><b>Außendienst:</b> Welche Funktionen verfügbar sind, wird zentral durch die Administration festgelegt.</div>':''}<div class="salesLayout"><section class="panel salesCustomerPanel"><div class="panelTitle"><h3>1. Kunde auswählen</h3><span>Telefon, Name, Firma oder Ort</span></div><div class="panelPad"><input class="bigSearch" id="salesCustomerSearch" placeholder="Kunde suchen …"><div class="customerPickList" id="salesCustomerResults"></div>${c?`<div class="selectedCustomer"><small>AKTUELLER KUNDE</small><h3>${esc(c.name)}</h3><p>${esc(c.street||'')} · ${esc(c.zip||'')} ${esc(c.city||'')}<br>${esc(c.phone||'')} ${c.email?'· '+esc(c.email):''}</p><div><span>Kundenberater: <b>${esc(customerOwnerName(c))}</b></span>${can('edit_customers')?'<button class="miniBtn" id="salesEditCustomer">Kundendaten</button>':''}</div></div>`:''}</div></section><section class="panel salesAdvicePanel"><div class="panelTitle"><h3>2. Bedarf</h3><span>systematisch erfassen</span></div><div class="panelPad"><div class="formGrid"><label>Bereich<select id="advPurpose"><option value="fish" ${sel(needs.purpose||'fish','fish')}>Fisch räuchern</option><option value="meat" ${sel(needs.purpose,'meat')}>Fleisch / Schinken</option><option value="smoke" ${sel(needs.purpose,'smoke')}>Räuchermehl</option><option value="brine" ${sel(needs.purpose,'brine')}>Räucherlauge</option><option value="other" ${sel(needs.purpose,'other')}>Sonstiges</option></select></label><label>Fischart<select id="advFish"><option value="forelle" ${sel(needs.fish||'forelle','forelle')}>Forelle</option><option value="aal" ${sel(needs.fish,'aal')}>Aal</option><option value="lachs" ${sel(needs.fish,'lachs')}>Lachs</option><option value="makrele" ${sel(needs.fish,'makrele')}>Makrele</option><option value="other" ${sel(needs.fish,'other')}>Andere</option></select></label><label>Gewicht pro Stück (kg)<input id="advWeight" type="number" min="0.1" step="0.1" value="${Number(needs.weight||2)}"></label><label>Produktform<select id="advForm"><option value="whole" ${sel(needs.form||'whole','whole')}>Ganzer Fisch / Stück</option><option value="filet" ${sel(needs.form,'filet')}>Filet</option></select></label><label>Priorität<select id="advPriority"><option value="standard" ${sel(needs.priority||'standard','standard')}>Solide Standardlösung</option><option value="secure" ${sel(needs.priority,'secure')}>Besonders sicherer Halt</option><option value="heavy" ${sel(needs.priority,'heavy')}>Schwere Fische / hohe Belastung</option></select></label><label>Materialwunsch<select id="advMaterial"><option value="VA" ${sel(needs.material||'VA','VA')}>VA</option><option value="V2A" ${sel(needs.material,'V2A')}>V2A rostfrei</option><option value="V4A" ${sel(needs.material,'V4A')}>V4A Premium</option></select></label><label>Beratungskanal<select id="advChannel"><option value="phone" ${sel(needs.channel||'phone','phone')}>Telefon</option><option value="field" ${sel(needs.channel,'field')}>Kundenberater vor Ort</option></select></label>${isAdmin()?`<label>Berater<select id="advRep">${repOptions(c?.sales_rep_id||needs.sales_rep_id||'')}</select></label>`:''}<label class="full">Beratungsnotiz<textarea id="advNote" placeholder="Besondere Wünsche, Einsatz, Rückfragen …">${esc(needs.note||'')}</textarea></label></div><div class="formActions"><button class="btn orange" id="runAdvice">Empfehlung ermitteln</button></div></div></section></div>${salesAdvice?`<section class="panel adviceResult"><div class="panelTitle"><h3>3. Empfehlung</h3><span>${recs.length} passende Artikel</span></div><div class="adviceCards">${recs.map(p=>`<article><div class="adviceImage">${p.image?`<img src="../${esc(p.image)}" alt="">`:'◇'}</div><div><small>Art.-Nr. ${esc(p.article_no||'–')}</small><h4>${esc(p.name)}</h4><p>${esc(p.description||p.category||'')}</p><b>ab ${money(p.base)}</b></div></article>`).join('')}</div>${(can('save_consultations')||can('create_orders'))?`<div class="adviceActions">${can('save_consultations')?'<button class="btn" id="saveAdvice">Beratung speichern</button>':''}${can('create_orders')?'<button class="btn primary" id="adviceToOrder">Empfehlung → Bestellung</button>':''}</div>`:''}</section>`:''}${isAdmin()?`<section class="panel recentConsultations"><div class="panelTitle"><h3>Letzte Beratungen</h3><span>${(state.consultations||[]).length} gespeichert</span></div><div class="panelPad">${(state.consultations||[]).slice(0,6).map(x=>{const cu=(state.customers||[]).find(c=>c.id===x.customer_id);return `<div class="consultRow"><b>${esc(x.id)}</b><span>${esc(cu?.name||'ohne Kunde')}</span><small>${dt(x.created_at)}</small></div>`}).join('')||'<div class="empty compact"><b>Noch keine Beratungen</b>Gespeicherte Beratungen erscheinen hier.</div>'}</div></section>`:''}`;renderSalesCustomerResults();$('#salesCustomerSearch').oninput=e=>renderSalesCustomerResults(e.target.value);if($('#salesNewCustomer'))$('#salesNewCustomer').onclick=()=>customerModal(null);if(c){if($('#salesEditCustomer'))$('#salesEditCustomer').onclick=()=>customerModal(c.id);if(can('create_orders')&&$('#salesNewOrder'))$('#salesNewOrder').onclick=()=>manualOrderModal(c.id,[],c.sales_rep_id||'')}$('#runAdvice').onclick=()=>{const n={purpose:$('#advPurpose').value,fish:$('#advFish').value,weight:+$('#advWeight').value,form:$('#advForm').value,priority:$('#advPriority').value,material:$('#advMaterial').value,channel:$('#advChannel').value,sales_rep_id:isAdmin()?$('#advRep').value:(state.current_user?.sales_rep_id||''),note:$('#advNote').value};salesAdvice={needs:n,recs:recommendForNeeds(n)};renderSales()};if(salesAdvice&&(can('save_consultations')||can('create_orders'))){if($('#saveAdvice'))$('#saveAdvice').onclick=async()=>{try{const d=await api({action:'consultation_save',customer_id:c?.id||'',sales_rep_id:isAdmin()?$('#advRep').value:(state.current_user?.sales_rep_id||''),channel:$('#advChannel').value,needs:salesAdvice.needs,recommendations:salesAdvice.recs,notes:$('#advNote').value});salesConsultationId=d.consultation_id;toast('Beratung '+d.consultation_id+' gespeichert');await load(true)}catch(e){toast(e.message,true)}};if($('#adviceToOrder'))$('#adviceToOrder').onclick=async()=>{if(!c)return toast('Bitte zuerst einen Kunden auswählen',true);try{const d=await api({action:'consultation_save',customer_id:c.id,sales_rep_id:isAdmin()?$('#advRep').value:(state.current_user?.sales_rep_id||''),channel:$('#advChannel').value,needs:salesAdvice.needs,recommendations:salesAdvice.recs,notes:$('#advNote').value});salesConsultationId=d.consultation_id;manualOrderModal(c.id,salesAdvice.recs,isAdmin()?$('#advRep').value:(state.current_user?.sales_rep_id||''),d.consultation_id,$('#advChannel').value)}catch(e){toast(e.message,true)}}}}
function manualOrderModal(customerId,presetIds=[],repId='',consultationId='',channel='telephone'){
 const c=(state.customers||[]).find(x=>x.id===customerId);if(!c)return toast('Kunde nicht gefunden',true);
 let cart=presetIds.map(id=>{const p=(state.catalog||[]).find(x=>x.id===id);return p?{id:p.id,qty:1,meta:p.type==='hook'?{length:defaultHookLength(p.id),material:salesAdvice?.needs?.material||'VA',tip:'standard'}:{}}:null}).filter(Boolean);
 const normalized=({field:'advisor',phone:'telephone',shop:'online'})[channel]||channel;
 let opts={rep_id:repId||c.sales_rep_id||(!isAdmin()?(state.current_user?.sales_rep_id||''):''),channel:normalized||'telephone',shipping:'dpd',payment:'Rechnung / Überweisung',paid:false,note:'',consultation_id:consultationId||salesConsultationId||''};
 const draw=()=>{const products=activeCatalog().filter(p=>Number(p.base)>0),sum=cart.reduce((a,x)=>{const p=products.find(z=>z.id===x.id);return a+estimatePrice(p,x.meta)*x.qty},0),owner=customerOwnerName(c),hasOwner=!!c.sales_rep_id;
 openModal(`<div class="modalHead"><small>ORGABOARD VERKAUF · V69</small><h2>Neue Bestellung</h2><p>${esc(c.name)} · Herkunft und Provision werden getrennt dokumentiert.</p></div><div class="modalBody"><div class="orderCustomerStrip"><div><small>KUNDE</small><b>${esc(c.name)}</b><span>${esc(c.street||'')} · ${esc(c.zip||'')} ${esc(c.city||'')}</span></div><button class="miniBtn" id="orderEditCustomer">Kundendaten</button></div>
 <div class="attributionPreview ${hasOwner?'returning':''}"><div><small>KUNDENBEZIEHUNG</small><b>${hasOwner?'Bestehender Kundenberater: '+esc(owner):'Noch kein fester Kundenberater'}</b><span>${hasOwner?'Dieser Kundenberater hat bei Folgekäufen Vorrang und erhält die volle Provision.':'Ohne Beraterkontakt wird die Provisionsgutschrift automatisch abwechselnd Björn Hahne / Jessica Hahne zugeteilt.'}</span></div></div>
 <div class="manualOrderGrid"><section><h3>Artikel hinzufügen</h3><div class="formGrid"><label class="full">Produkt<select id="ordProduct">${products.map(p=>`<option value="${esc(p.id)}">${esc(p.article_no||'–')} · ${esc(p.name)} · ${money(p.base)}</option>`).join('')}</select></label><label>Menge<input id="ordQty" type="number" min="1" max="99" value="1"></label><label>Länge<select id="ordLength"></select></label><label>Material<select id="ordMaterial"><option>VA</option><option>V2A</option><option>V4A</option></select></label><label>Spitze<select id="ordTip"><option value="standard">Standard geschärft</option><option value="extra">Extra scharf</option></select></label></div><button class="btn orange wideBtn" id="addOrderItem">+ Artikel übernehmen</button></section>
 <section><h3>Verkaufszuordnung</h3><div class="formGrid"><label class="full">Verkaufsherkunft<select id="ordChannel"><option value="online" ${sel(opts.channel,'online')}>Online-Shop</option><option value="advisor" ${sel(opts.channel,'advisor')}>Kundenberater</option><option value="telephone" ${sel(opts.channel,'telephone')}>Telefonleitung</option><option value="email" ${sel(opts.channel,'email')}>E-Mail</option><option value="walk_in" ${sel(opts.channel,'walk_in')}>Vor Ort / Abholung</option><option value="other" ${sel(opts.channel,'other')}>Sonstiges</option></select></label><label class="full">Kundenberater / direkter Kontakt<select id="ordRep">${repOptions(opts.rep_id)}</select><small>Bei einem bestehenden Beraterkunden bleibt dessen Kundenberater automatisch provisionsberechtigt.</small></label><label>Übergabe<select id="ordShipping"><option value="dpd" ${sel(opts.shipping,'dpd')}>DPD Versand</option><option value="field_delivery" ${sel(opts.shipping,'field_delivery')}>Übergabe Kundenberater</option><option value="pickup" ${sel(opts.shipping,'pickup')}>Abholung</option></select></label><label>Zahlungsart<select id="ordPayment"><option ${sel(opts.payment,'Rechnung / Überweisung')}>Rechnung / Überweisung</option><option ${sel(opts.payment,'Vorkasse')}>Vorkasse</option><option ${sel(opts.payment,'Bar')}>Bar</option><option ${sel(opts.payment,'Kartenzahlung')}>Kartenzahlung</option></select></label><label class="shopToggle full"><input id="ordPaid" type="checkbox" ${opts.paid?'checked':''}><span><b>Zahlung bereits erfolgt</b><small>Provision wird erst bei bezahltem Auftrag in der Abrechnung wirksam.</small></span></label><label class="full">Interne Auftragsnotiz<textarea id="ordNote">${esc(opts.note)}</textarea></label></div></section></div>
 <div class="orderCart"><div class="panelTitle"><h3>Positionen</h3><span>${cart.reduce((a,x)=>a+x.qty,0)} Stück / Sets</span></div>${cart.length?`<table class="dataTable compactTable"><thead><tr><th>Art.-Nr.</th><th>Artikel</th><th>Variante</th><th>Menge</th><th>Preis ca.</th><th></th></tr></thead><tbody>${cart.map((x,i)=>{const p=products.find(z=>z.id===x.id);return `<tr><td>${esc(p?.article_no||'–')}</td><td><b>${esc(p?.name||x.id)}</b></td><td>${esc(itemMeta(x)||'–')}</td><td>${x.qty}</td><td>${money(estimatePrice(p,x.meta)*x.qty)}</td><td><button class="miniBtn" data-remove-cart="${i}">Entfernen</button></td></tr>`}).join('')}</tbody></table>`:'<div class="empty compact"><b>Noch keine Position</b>Artikel oben auswählen und übernehmen.</div>'}<div class="cartEstimate"><span>Voraussichtlicher Warenwert</span><b>${money(sum)}</b><small>Versand und endgültiger Variantenpreis werden serverseitig berechnet.</small></div></div><div class="formActions"><button class="btn" id="cancelManualOrder">Abbrechen</button><button class="btn primary" id="saveManualOrder" ${cart.length?'':'disabled'}>Bestellung verbindlich erfassen</button></div></div>`);
 const sync=()=>{opts.channel=$('#ordChannel').value;opts.rep_id=$('#ordRep').value;opts.shipping=$('#ordShipping').value;opts.payment=$('#ordPayment').value;opts.paid=$('#ordPaid').checked;opts.note=$('#ordNote').value};
 const updateVariant=()=>{const p=products.find(x=>x.id===$('#ordProduct').value),isHook=p?.type==='hook',lens=hookLengths(p?.id);$('#ordLength').innerHTML=(lens.length?lens:['–']).map(v=>`<option value="${v==='–'?'':v}">${v}</option>`).join('');$('#ordLength').disabled=!isHook;$('#ordMaterial').disabled=!isHook;$('#ordTip').disabled=!isHook};
 $('#ordProduct').onchange=updateVariant;updateVariant();$('#addOrderItem').onclick=()=>{sync();const p=products.find(x=>x.id===$('#ordProduct').value);if(!p)return;const qty=Math.max(1,Math.min(99,+$('#ordQty').value||1)),meta=p.type==='hook'?{length:$('#ordLength').value||defaultHookLength(p.id),material:$('#ordMaterial').value,tip:$('#ordTip').value}:{};cart.push({id:p.id,qty,meta});draw()};$$('[data-remove-cart]').forEach(b=>b.onclick=()=>{sync();cart.splice(+b.dataset.removeCart,1);draw()});$('#cancelManualOrder').onclick=closeModal;$('#orderEditCustomer').onclick=()=>customerModal(c.id);
 $('#saveManualOrder').onclick=async()=>{sync();try{const d=await api({action:'manual_order_create',customer_id:c.id,sales_rep_id:opts.rep_id,consultation_id:opts.consultation_id,channel:opts.channel,shipping_mode:opts.shipping,payment_method:opts.payment,paid:opts.paid,note:opts.note,items:cart});toast('Bestellung '+d.order.order_no+' · Provision: '+(d.attribution?.commission_sales_rep_name||commissionRepName(d.order)));closeModal();await load(true);openOrder(d.order.order_no)}catch(e){toast(e.message,true)}}};
 draw()
}
const TERRITORY_GEOJSON_URL='https://raw.githubusercontent.com/isellsoap/deutschlandGeoJSON/refs/heads/main/2_bundeslaender/4_niedrig.geo.json';
const TERRITORY_COLORS={'01':'#14B8A6','02':'#EF4444','03':'#22C55E','04':'#F97316','05':'#3B82F6','06':'#8B5CF6','07':'#C0265C','08':'#15803D','09':'#0EA5E9','10':'#EAB308','11':'#374151','12':'#B45309','13':'#0F766E','14':'#A21CAF','15':'#65A30D','16':'#EC4899'};
const SALES_ROLE_LABELS={regional_manager:'Regionalmanager',district_manager:'Bezirksmanager',team_leader:'Teamleiter',advisor_active:'Kundenberater Aktiv',advisor_be:'Kundenberater BE'};
const SALES_ROLE_TABS=[['platform','Kundenberater-Plattform'],['territory','Gebiet vergeben'],['regional_manager','Regionalmanager'],['district_manager','Bezirksmanager'],['team_leader','Teamleiter'],['advisor_active','Kundenberater Aktiv'],['advisor_be','Kundenberater BE']];
let salesRepTab='platform';
function salesRoleLabel(v){return SALES_ROLE_LABELS[v]||'Kundenberater Aktiv'}
function publicSalesReps(){return (state.sales_reps||[]).filter(r=>!String(r.employee_no||'').startsWith('ZENTRALE-')&&r.sales_role!=='house')}
function territoryColor(code){return TERRITORY_COLORS[String(code||'').padStart(2,'0')]||'#64748B'}
function territoryOwnerOptions(current=''){return `<option value="">– Weißgebiet / nicht vergeben –</option>${publicSalesReps().filter(r=>r.status==='active'&&r.sales_role!=='advisor_be'&&!(r.sales_role==='advisor_active'&&r.parent_sales_rep_id)).map(r=>`<option value="${esc(r.id)}" ${sel(current,r.id)}>${esc(r.employee_no)} · ${esc(r.name)} · ${esc(salesRoleLabel(r.sales_role))}${r.state_code?' · '+esc(territoryStateName(r.state_code)):''}</option>`).join('')}`}
async function renderTerritoryMiniMap(hostId,selectedCode='',onPick=null){
 const host=typeof hostId==='string'?$(hostId):hostId;if(!host)return;
 host.innerHTML='<div class="territoryMapLoading">Karte wird geladen …</div>';
 try{
  const r=await fetch(TERRITORY_GEOJSON_URL,{cache:'force-cache'});if(!r.ok)throw new Error('Kartendaten nicht verfügbar');
  const geo=await r.json(),features=geo.features||[],all=[];
  const walk=c=>{if(Array.isArray(c)&&typeof c[0]==='number')all.push(c);else if(Array.isArray(c))c.forEach(walk)};features.forEach(f=>walk(f.geometry.coordinates));
  const xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),W=440,H=520,pad=18;
  const pt=p=>[(p[0]-minX)/(maxX-minX)*(W-pad*2)+pad,H-pad-(p[1]-minY)/(maxY-minY)*(H-pad*2)];
  const ringPath=ring=>ring.map((p,i)=>{const [x,y]=pt(p);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`}).join(' ')+' Z';
  const geomPath=g=>g.type==='Polygon'?g.coordinates.map(ringPath).join(' '):g.coordinates.flatMap(poly=>poly.map(ringPath)).join(' ');
  const codeMap={'DE-SH':'01','DE-HH':'02','DE-NI':'03','DE-HB':'04','DE-NW':'05','DE-HE':'06','DE-RP':'07','DE-BW':'08','DE-BY':'09','DE-SL':'10','DE-BE':'11','DE-BB':'12','DE-MV':'13','DE-SN':'14','DE-ST':'15','DE-TH':'16'};
  let paths='';features.forEach(f=>{const code=codeMap[f.properties?.id]||'',t=(state.sales_territories||[]).find(x=>x.state_code===code),active=Boolean(t?.owner_sales_rep_id),selected=code===selectedCode,color=territoryColor(code);paths+=`<path tabindex="0" role="button" data-mini-territory="${code}" class="territoryShape ${active?'fixed':'white'} ${selected?'selected':''}" style="--territory-color:${color}" d="${geomPath(f.geometry)}"><title>${esc(t?.state_name||f.properties?.name||'')} · ${active?'Festgebiet':'Weißgebiet'}${selected?' · ausgewählt':''}</title></path>`});
  host.innerHTML=`<svg viewBox="0 0 ${W} ${H}" aria-label="Deutschlandkarte der Gebietsbücher">${paths}</svg>`;
  $$('[data-mini-territory]',host).forEach(p=>{const pick=()=>{if(typeof onPick==='function')onPick(p.dataset.miniTerritory)};p.onclick=pick;p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick()}}});
 }catch(e){const t=(state.sales_territories||[]).find(x=>x.state_code===selectedCode);host.innerHTML=`<div class="territoryMapFallback"><b>${selectedCode?esc(t?.territory_book_no||'FG-'+selectedCode)+' · '+esc(t?.state_name||territoryStateName(selectedCode)):'Deutschlandkarte'}</b><span>${selectedCode?'Gebiet ist ausgewählt. ':''}Kartendaten konnten nicht geladen werden.</span></div>`}
}

function territoryMatchesSearch(t,term=territorySearchTerm){
 term=String(term||'').trim().toLowerCase();
 if(!term)return true;
 const hay=[t?.state_name||'',t?.territory_book_no||'',t?.owner_name||'',t?.state_code||'',t?.owner_sales_rep_id?'festgebiet':'weißgebiet',t?.member_count||'',t?.customer_count||''].join(' ').toLowerCase();
 return hay.includes(term);
}
function territoryFilteredList(){return (state?.sales_territories||[]).filter(t=>territoryMatchesSearch(t)).sort((a,b)=>String(a.territory_book_no||a.state_code).localeCompare(String(b.territory_book_no||b.state_code),'de'));}
function territorySelectedCard(code){territorySelectedCode=String(code||'').padStart(2,'0');renderTerritories();}

function renderAdvisorPlatformTerritoryMap(){const host=$('#platformTerritoryMap');if(!host)return;renderTerritoryMiniMap(host,'',code=>{territoryBookAdminState=code;territoryBookRowsCode='';setView('territorybook')})}

function territoryDetail(code){const t=(state.sales_territories||[]).find(x=>x.state_code===code);if(!t)return;const members=(state.sales_reps||[]).filter(r=>r.state_code===code),owner=(state.sales_reps||[]).find(r=>r.id===t.owner_sales_rep_id);openModal(`<div class="modalHead"><small>${esc(t.territory_book_no)} · ${t.owner_sales_rep_id?'FESTGEBIET':'WEISSGEBIET'}</small><h2>${esc(t.state_name)}</h2><p>${t.owner_sales_rep_id?'Gebietsschutz aktiv':'Noch kein Festgebietsinhaber zugeordnet'}</p></div><div class="modalBody"><div class="territoryModalGrid"><section><label>Festgebietsinhaber<select id="territoryOwner">${territoryOwnerOptions(t.owner_sales_rep_id||'')}</select></label><div class="formActions"><button class="btn primary" id="saveTerritory">Gebiet speichern</button></div><p class="muted tiny">Pro Bundesland ist genau ein Festgebietsinhaber möglich. Eine Freigabe setzt das Gebiet wieder auf Weißgebiet.</p></section><section class="territoryTeamBox"><h3>Team im Gebiet</h3>${members.length?members.map(r=>`<div class="territoryTeamRow"><div><b>${esc(r.name)}</b><small>${esc(r.employee_no)} · ${esc(salesRoleLabel(r.sales_role))}${t.owner_sales_rep_id===r.id?' · FG-Inhaber':''}</small></div>${r.team?.is_team_leader?'<span class="teamLeaderPill">+3 % TL</span>':''}</div>`).join(''):'<div class="empty">Noch kein Außendienstmitarbeiter im Gebiet.</div>'}<button class="btn" id="addTerritoryMember">+ Mitarbeiter im Gebiet</button></section></div></div>`);$('#saveTerritory').onclick=async()=>{try{const d=await api({action:'territory_assign',state_code:code,sales_rep_id:$('#territoryOwner').value});state.sales_territories=d.territories;state.sales_reps=d.sales_reps;toast($('#territoryOwner').value?'Festgebiet vergeben':'Gebiet als Weißgebiet freigegeben');closeModal();renderTerritories()}catch(e){toast(e.message,true)}};$('#addTerritoryMember').onclick=()=>{const parent=t.owner_sales_rep_id||'';closeModal();salesRepModal(null,code,parent)}}
function renderTerritories(){
 const ts=state.sales_territories||[],fixed=ts.filter(t=>t.owner_sales_rep_id).length,white=16-fixed,leaders=publicSalesReps().filter(r=>r.sales_role==='team_leader').length;
 const filtered=territoryFilteredList();
 if(territorySelectedCode && !filtered.some(t=>t.state_code===territorySelectedCode))territorySelectedCode='';
 const selected=(filtered.find(t=>t.state_code===territorySelectedCode)||filtered[0]||null);
 const countLabel=`${filtered.length.toLocaleString('de-DE')} von ${ts.length.toLocaleString('de-DE')} Bundesländern`;
 ws.innerHTML=`<div class="sectionHead"><div><h2>Festgebiete Deutschland</h2><p>16 Bundesländer als geschützte Vertriebsgebiete mit fester Gebietsfarbe, Gebietsbuch und Vertriebsorganisation.</p></div><button class="btn" id="territoryListToggle">Zur Gebietsliste</button></div>
 <section class="panel territoryIntroBand"><div><small>KLARER WORKFLOW</small><h3>Gebiete schneller finden, prüfen und vergeben</h3><p>Suche zuerst nach Bundesland, FG-Nummer oder Inhaber. Danach siehst du Karte, Gebietsbuch und Status in einer logischeren Reihenfolge.</p></div><div class="territoryQuickSteps"><article><b>1</b><span>Suchen</span><small>nach Bundesland, FG oder Inhaber</small></article><article><b>2</b><span>Prüfen</span><small>Status direkt auf Karte und in der Liste</small></article><article><b>3</b><span>Verwalten</span><small>Gebiet öffnen und sauber zuweisen</small></article></div></section>
 <section class="panel territorySearchPanel"><div class="territoryToolbar"><label class="territorySearchWrap"><span>⌕</span><input id="territorySearch" type="search" placeholder="Bundesland, FG-Nummer, Inhaber, Weißgebiet …" value="${esc(territorySearchTerm)}"></label><div class="territoryToolbarMeta"><b>${countLabel}</b><small>${territorySearchTerm?'Suchfilter aktiv · Karte und Liste werden live gefiltert':'Suche über Karte, Gebietsliste und Gebietsinhaber'}</small></div><button class="btn" id="territorySearchClear" ${territorySearchTerm?'':'disabled'}>Suche löschen</button></div>${selected?`<div class="territoryMapSummary"><b>${esc(selected.territory_book_no)} · ${esc(selected.state_name)}</b><span>${selected.owner_sales_rep_id?`Festgebiet · ${esc(selected.owner_name||'Gebietsinhaber hinterlegt')}`:'Weißgebiet · noch nicht vergeben'}</span><small>${Number(selected.member_count||0).toLocaleString('de-DE')} Mitarbeiter · ${Number(selected.customer_count||0).toLocaleString('de-DE')} Kunden</small></div>`:'<div class="territoryMapSummary empty"><b>Kein Bundesland gefunden</b><span>Bitte Suchbegriff anpassen oder Suche zurücksetzen.</span></div>'}</section>
 <div class="metricGrid territoryMetrics">${metric('Festgebiete',fixed,'von 16 Bundesländern')}${metric('Weißgebiete',white,'noch frei')}${metric('Teamleiter',leaders,'Führung im Festgebiet')}${metric('Kundenberater',publicSalesReps().filter(r=>r.status==='active').length,'aktive Vertriebsmitarbeiter')}</div>
 <div class="territoryLayout"><section class="panel territoryMapPanel"><div class="panelTitle"><h3>Deutschlandkarte</h3><span><i class="legendDot fixed"></i> besetzt · Bundeslandfarbe <i class="legendDot white"></i> Weißgebiet</span></div><div id="territoryMap" class="territoryMap"><div class="territoryMapLoading">Bundesländer werden geladen …</div></div><p class="territoryAttribution">Suche filtert Karte und Gebietsliste gleichzeitig. Klick auf ein Bundesland öffnet direkt die Detailverwaltung.</p></section><section class="panel territorySide"><div class="panelTitle"><h3>Gebietsbücher</h3><span>${countLabel}</span></div><div class="territoryStateList">${filtered.length?filtered.map(t=>`<button type="button" data-territory="${t.state_code}" data-territory-select="${t.state_code}" class="territoryStateCard ${t.owner_sales_rep_id?'fixed':'white'} ${territorySelectedCode===t.state_code?'selected':''}" style="--territory-color:${territoryColor(t.state_code)}"><span class="territoryBook">${esc(t.territory_book_no)}</span><i class="territoryColorChip"></i><div><b>${esc(t.state_name)}</b><small>${t.owner_sales_rep_id?esc(t.owner_name||'Gebietsinhaber'):'Weißgebiet · frei'}</small></div><em>${t.member_count||0}</em></button>`).join(''):`<div class="empty"><b>Kein Treffer</b>Für diese Suche wurde kein Bundesland gefunden.</div>`}</div></section></div><section class="panel territoryRules"><h3>Gebietsschutz & Führungslogik</h3><div class="territoryRuleGrid"><div><b>1 · Weißgebiet</b><span>Unbesetzt bleibt das Bundesland neutral. Die feste Landesfarbe ist reserviert, aber noch nicht aktiv.</span></div><div><b>2 · Festgebiet (FG)</b><span>Mit der Vergabe wird die Bundeslandfarbe aktiviert und der Gebietsschutz dokumentiert.</span></div><div><b>3 · Führung</b><span>Regionalmanager, Bezirksmanager, Teamleiter und Kundenberater werden als getrennte Funktionen geführt.</span></div><div><b>4 · Teamleiterbonus</b><span>Ein Kundenberater mit eigenem aktivem Team wird automatisch Teamleiter; der bestehende +3-Prozentpunkte-Bonus bleibt erhalten.</span></div></div></section>`;
 $$('[data-territory]').forEach(b=>b.onclick=()=>{territorySelectedCode=b.dataset.territory;territoryDetail(b.dataset.territory)});
 $$('[data-territory-select]').forEach(b=>b.addEventListener('mouseenter',()=>{territorySelectedCode=b.dataset.territorySelect;renderGermanyTerritoryMap()}));
 $('#territoryListToggle').onclick=()=>$('.territorySide')?.scrollIntoView({behavior:'smooth',block:'start'});
 const searchInput=$('#territorySearch');
 const restoreTerritorySearchFocus=()=>requestAnimationFrame(()=>{const next=$('#territorySearch');if(!next)return;try{next.focus({preventScroll:true})}catch(_){next.focus()}const pos=next.value.length;try{next.setSelectionRange(pos,pos)}catch(_){}});
 const applyTerritorySearch=()=>{if(territorySearchTimer){clearTimeout(territorySearchTimer);territorySearchTimer=0}const rows=territoryFilteredList();if(territorySearchTerm.trim()&&rows.length===1)territorySelectedCode=rows[0].state_code;else if(territorySelectedCode&&!rows.some(r=>r.state_code===territorySelectedCode))territorySelectedCode='';renderTerritories();restoreTerritorySearchFocus()};
 if(searchInput){searchInput.oninput=()=>{territorySearchTerm=searchInput.value;if(territorySearchTimer)clearTimeout(territorySearchTimer);territorySearchTimer=setTimeout(applyTerritorySearch,300)};searchInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();if(territorySearchTimer){clearTimeout(territorySearchTimer);territorySearchTimer=0}territorySearchTerm=searchInput.value;const rows=territoryFilteredList();if(rows.length===1){territorySelectedCode=rows[0].state_code;territoryDetail(rows[0].state_code)}else if(rows.length>0){territorySelectedCode=rows[0].state_code;renderTerritories();$('.territoryMapPanel')?.scrollIntoView({behavior:'smooth',block:'start'});restoreTerritorySearchFocus()}}}}
 $('#territorySearchClear').onclick=()=>{if(territorySearchTimer){clearTimeout(territorySearchTimer);territorySearchTimer=0}territorySearchTerm='';territorySelectedCode='';renderTerritories();restoreTerritorySearchFocus()};
 renderGermanyTerritoryMap()
}
async function renderGermanyTerritoryMap(){const host=$('#territoryMap');if(!host)return;try{const r=await fetch(TERRITORY_GEOJSON_URL,{cache:'force-cache'});if(!r.ok)throw new Error('Kartendaten nicht verfügbar');const geo=await r.json(),features=geo.features||[];const all=[];const walk=c=>{if(Array.isArray(c)&&typeof c[0]==='number')all.push(c);else if(Array.isArray(c))c.forEach(walk)};features.forEach(f=>walk(f.geometry.coordinates));const xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),W=620,H=760,pad=24;const pt=p=>[(p[0]-minX)/(maxX-minX)*(W-pad*2)+pad,H-pad-(p[1]-minY)/(maxY-minY)*(H-pad*2)];const ringPath=ring=>ring.map((p,i)=>{const [x,y]=pt(p);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`}).join(' ')+' Z';const geomPath=g=>g.type==='Polygon'?g.coordinates.map(ringPath).join(' '):g.coordinates.flatMap(poly=>poly.map(ringPath)).join(' ');const codeMap={'DE-SH':'01','DE-HH':'02','DE-NI':'03','DE-HB':'04','DE-NW':'05','DE-HE':'06','DE-RP':'07','DE-BW':'08','DE-BY':'09','DE-SL':'10','DE-BE':'11','DE-BB':'12','DE-MV':'13','DE-SN':'14','DE-ST':'15','DE-TH':'16'};const visibleCodes=new Set(territoryFilteredList().map(t=>t.state_code));let paths='',labels='';features.forEach(f=>{const code=codeMap[f.properties?.id]||'',t=(state.sales_territories||[]).find(x=>x.state_code===code),active=Boolean(t?.owner_sales_rep_id),color=territoryColor(code),selected=territorySelectedCode===code,dimmed=territorySearchTerm&&!visibleCodes.has(code);const pts=[];const collect=c=>{if(Array.isArray(c)&&typeof c[0]==='number')pts.push(c);else if(Array.isArray(c))c.forEach(collect)};collect(f.geometry.coordinates);const cx=pts.reduce((a,p)=>a+pt(p)[0],0)/Math.max(1,pts.length),cy=pts.reduce((a,p)=>a+pt(p)[1],0)/Math.max(1,pts.length);paths+=`<path tabindex="0" role="button" data-map-territory="${code}" class="territoryShape ${active?'fixed':'white'} ${selected?'selected':''} ${dimmed?'dimmed':''}" style="--territory-color:${color}" d="${geomPath(f.geometry)}"><title>${esc(t?.state_name||f.properties?.name||'')} · ${active?'Festgebiet · '+(t?.owner_name||'besetzt'):'Weißgebiet · frei'}${selected?' · ausgewählt':''}</title></path>`;if(code&&!['02','04','11'].includes(code))labels+=`<text x="${cx.toFixed(0)}" y="${cy.toFixed(0)}" class="territoryMapLabel ${dimmed?'dimmed':''}">${code}</text>`});host.innerHTML=`<svg viewBox="0 0 ${W} ${H}" aria-label="Deutschlandkarte mit 16 Vertriebsgebieten">${paths}${labels}</svg>`;$$('[data-map-territory]',host).forEach(p=>{p.addEventListener('click',()=>{territorySelectedCode=p.dataset.mapTerritory;territoryDetail(p.dataset.mapTerritory)});p.addEventListener('mouseenter',()=>{territorySelectedCode=p.dataset.mapTerritory;renderGermanyTerritoryMap()});p.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();territorySelectedCode=p.dataset.mapTerritory;territoryDetail(p.dataset.mapTerritory)}})})}catch(e){host.innerHTML=`<div class="territoryMapFallback"><b>Deutschlandkarte konnte nicht geladen werden.</b><span>Die 16 Festgebiete bleiben rechts vollständig bedienbar. Ursache: ${esc(e.message)}</span></div>`}}
function territoryStateName(code){return (state.sales_territories||[]).find(t=>t.state_code===code)?.state_name||'–'}
function salesRepRoleBadge(role){const cls={regional_manager:'rm',district_manager:'bm',team_leader:'tl',advisor_active:'ka',advisor_be:'be'}[role]||'ka';return `<span class="salesRoleBadge ${cls}">${esc(salesRoleLabel(role))}</span>`}
function salesRepTabsHtml(){return `<div class="salesRoleTabs">${SALES_ROLE_TABS.map(([k,l])=>`<button type="button" data-sales-tab="${k}" class="${salesRepTab===k?'active':''}">${esc(l)}<em>${k==='territory'?(state.sales_territories||[]).filter(t=>t.owner_sales_rep_id).length:publicSalesReps().filter(r=>r.sales_role===k).length}</em></button>`).join('')}</div>`}
function renderTerritoryAssignmentInsideReps(){const ts=state.sales_territories||[];return `<div class="territoryAssignIntro"><div><b>Festgebiet direkt vergeben</b><span>Die Vergabe hier und im Reiter „Festgebiete Deutschland“ greift auf dieselben Daten zu.</span></div><button class="btn" id="openFullTerritoryMap">Deutschlandkarte öffnen</button></div><div class="territoryAssignGrid">${ts.map(t=>`<article class="territoryAssignCard ${t.owner_sales_rep_id?'occupied':'white'}" style="--territory-color:${territoryColor(t.state_code)}"><div class="territoryAssignHead"><i></i><div><small>${esc(t.territory_book_no)}</small><b>${esc(t.state_name)}</b></div><span>${t.owner_sales_rep_id?'GEBIETSSCHUTZ':'WEISSGEBIET'}</span></div><label>Festgebietsinhaber<select data-inline-territory-owner="${t.state_code}">${territoryOwnerOptions(t.owner_sales_rep_id||'')}</select></label><div class="territoryAssignFoot"><small>${t.member_count||0} Mitarbeiter · ${t.customer_count||0} Kunden</small><button class="miniBtn" data-save-inline-territory="${t.state_code}">Speichern</button></div></article>`).join('')}</div>`}

const TERRITORY_DIR_STATUS={active:'Aktiv',candidate:'Recherche',paused:'Pausiert',archived:'Archiv'};
const TERRITORY_CONTACT_RESULTS={reached:'Erreicht',not_reached:'Nicht erreicht',appointment:'Termin vereinbart',interested:'Interesse',info_sent:'Information gesendet',callback:'Rückruf / Wiedervorlage',no_interest:'Kein Interesse',other:'Sonstiges'};
function territoryDirCategoryLabel(k){return state.territory_directory_categories?.[k]||k||'Sonstiges'}
const TERRITORY_CORE_PACKS=['fishing','meat','hardware','spices','fishery','smoke_bbq','outdoor_trade'];
const TERRITORY_COMPLETE_PACKS=[...TERRITORY_CORE_PACKS,'food','relevant_restaurants'];
const TERRITORY_PACK_LABELS={fishing:'Angelgeschäfte & Angelvereine',meat:'Fleischereien, Metzgereien & Schlachtereien',hardware:'Baumärkte & Gartencenter',spices:'Gewürze, Kräuter & Gewürzmanufakturen',fishery:'Fischhandel & Fischverarbeitung',smoke_bbq:'Räuchern, Smoker, Grill & BBQ',outdoor_trade:'Outdoor, Jagd & relevanter Großhandel',food:'Lebensmittelgeschäfte & Märkte',relevant_restaurants:'Branchennahe Gastronomie',restaurants:'Alle Restaurants'};
function territoryDiscoveryPacks(pack){if(pack==='core')return [...TERRITORY_CORE_PACKS];if(pack==='all')return [...TERRITORY_COMPLETE_PACKS];return [pack]}
function territoryPackLabel(pack){return TERRITORY_PACK_LABELS[pack]||pack}
async function territoryDiscoveryRequest(code,pack,retries=1,onRetry=null){let last=null;for(let attempt=0;attempt<=retries;attempt++){try{return await api({action:'territory_directory_discover',state_code:code,pack})}catch(e){last=e;if(attempt<retries){if(typeof onRetry==='function')onRetry(attempt+1,e);await new Promise(r=>setTimeout(r,1500*(attempt+1)))}}}throw last||new Error('Teilabfrage fehlgeschlagen')}

function advisorPlatformHtml(){const reps=publicSalesReps(),users=state.users||[],ts=state.sales_territories||[],withBook=reps.filter(r=>r.state_code).length,withLogin=reps.filter(r=>r.user_id).length;return `<div class="advisorPlatformHero"><div><small>KUNDENBERATER-PLATTFORM</small><h3>Außendienst komplett steuern</h3><p>Rolle, Führung, Festgebiet, Gebietsbuch, Zugang, Rechte, Kundenstamm, Provision und Kontaktarbeit zentral verwalten.</p></div><div class="advisorPlatformActions"><button class="btn primary" id="platformNewRep">+ Kundenberater</button><button class="btn" id="platformTerritoryBooks">Gebietsbücher verwalten</button><button class="btn" id="platformMap">Deutschlandkarte</button><button class="btn" id="platformCustomers">Kunden</button><button class="btn primary" id="platformAppointments">Terminplaner</button><button class="btn" id="platformCalendar">Vertriebskalender</button><button class="btn" id="platformRights">Rechte-Zentrale</button></div></div><div class="metricGrid">${metric('Kundenberater',reps.length,reps.filter(r=>r.status==='active').length+' aktiv')}${metric('Mit Gebietsbuch',withBook,'von '+reps.length)}${metric('Mit Login',withLogin,'Orgaboard-Zugang')}${metric('Festgebiete',ts.filter(t=>t.owner_sales_rep_id).length,'von 16')}</div><section class="panel tableWrap"><div class="panelTitle"><h3>Kundenberater-Plattform</h3><span>Administrator · Vollsteuerung</span></div>${reps.length?`<table class="dataTable"><thead><tr><th>Mitarbeiter</th><th>Funktion</th><th>Gebietsbuch</th><th>Führung</th><th>Kunden</th><th>Provision</th><th>Zugang</th><th>Aktionen</th></tr></thead><tbody>${reps.map(r=>{const t=ts.find(x=>x.state_code===r.state_code),u=users.find(x=>x.id===r.user_id);return `<tr><td><b>${esc(r.employee_no)} · ${esc(r.name)}</b><br><small>${esc(r.phone||'')} ${r.email?'· '+esc(r.email):''}</small></td><td>${salesRepRoleBadge(r.sales_role)}</td><td>${t?`<b>${esc(t.territory_book_no)}</b><br><span class="territoryMini" style="--territory-color:${territoryColor(r.state_code)}"><i></i>${esc(t.state_name)}</span>`:'<span class="territoryWhitePill">kein Gebiet</span>'}</td><td>${r.parent_name?esc(r.parent_name):'–'}${r.team?.team_size?`<br><small>${r.team.team_size} Teammitglied(er)</small>`:''}</td><td><b>${r.customer_count}</b></td><td><b>${money(r.stats_current?.commission||0)}</b></td><td>${r.user_id?`<span class="status s-paid">Aktiv</span><br><small>${esc(r.username||'')}</small>`:'<span class="status s-pending">Kein Login</span>'}</td><td><div class="rowActions"><button class="miniBtn" data-platform-edit="${esc(r.id)}">Bearbeiten</button>${r.state_code?`<button class="miniBtn" data-platform-book="${esc(r.state_code)}">Gebietsbuch</button>`:''}<button class="miniBtn" data-platform-customers="${esc(r.name)}">Kundenstamm</button><button class="miniBtn" data-platform-stats="${esc(r.id)}">Abrechnung</button><button class="miniBtn" data-platform-rights="${esc(r.user_id||'')}">Rechte</button></div></td></tr>`}).join('')}</tbody></table>`:'<div class="empty"><b>Noch keine Kundenberater</b>Lege den ersten Außendienstmitarbeiter an.</div>'}</section><section class="panel advisorPlatformMapPanel"><div class="panelTitle"><h3>Gebietsbücher als Deutschlandkarte</h3><span>Bundesland anklicken → Gebietsbuch öffnen</span></div><div id="platformTerritoryMap" class="territoryMap advisorPlatformTerritoryMap"><div class="territoryMapLoading">Deutschlandkarte wird geladen …</div></div><div class="territoryMapLegendLine"><span><i class="legendDot fixed"></i> Festgebiet</span><span><i class="legendDot white"></i> Weißgebiet</span></div></section><div class="moduleNotice"><b>Datenschutz & Gebietsschutz:</b> Kundenberater erhalten serverseitig ausschließlich das Gebietsbuch ihres zugeordneten Bundeslandes. Andere Gebietsbücher werden nicht an deren Browser ausgeliefert.</div>`}
function bindAdvisorPlatform(){if($('#platformNewRep'))$('#platformNewRep').onclick=()=>salesRepModal(null,'','','advisor_be');if($('#platformTerritoryBooks'))$('#platformTerritoryBooks').onclick=()=>{territoryBookAdminState='all';territoryBookRowsCode='';setView('territorybook')};if($('#platformMap'))$('#platformMap').onclick=()=>setView('territories');if($('#platformCustomers'))$('#platformCustomers').onclick=()=>{searchTerm='';setView('customers')};if($('#platformAppointments'))$('#platformAppointments').onclick=()=>setView('appointments');if($('#platformCalendar'))$('#platformCalendar').onclick=()=>setView('salescalendar');if($('#platformRights'))$('#platformRights').onclick=()=>setView('rights');$$('[data-platform-edit]').forEach(b=>b.onclick=()=>salesRepModal(b.dataset.platformEdit));$$('[data-platform-book]').forEach(b=>b.onclick=()=>{territoryBookAdminState=b.dataset.platformBook;territoryBookRowsCode='';setView('territorybook')});$$('[data-platform-customers]').forEach(b=>b.onclick=()=>{searchTerm=b.dataset.platformCustomers||'';setView('customers')});$$('[data-platform-stats]').forEach(b=>b.onclick=()=>repStatsModal(b.dataset.platformStats));$$('[data-platform-rights]').forEach(b=>b.onclick=()=>b.dataset.platformRights?rightsModal(b.dataset.platformRights):toast('Noch kein Login verknüpft.',true));renderAdvisorPlatformTerritoryMap()}
function territoryBookScopeCode(){return isAdmin()?(territoryBookAdminState||state.sales_territories?.[0]?.state_code||'01'):(state.territory_book_scope?.state_code||'')}
async function territoryBookLoad(code){if(territoryBookLoading)return;territoryBookLoading=true;try{const d=await api({action:'territory_directory_list',state_code:code});territoryBookRows=d.rows||[];territoryBookRowsCode=d.scope?.state_code||code;state.territory_directory_summary=d.summary||{};if(!isAdmin())state.territory_book_scope=d.scope||state.territory_book_scope}catch(e){toast(e.message,true);territoryBookRows=[];territoryBookRowsCode=code}finally{territoryBookLoading=false;if(current==='territorybook')renderTerritoryBook()}}
function territoryBookFilteredRows(){const q=territoryBookSearch.toLowerCase().trim();return territoryBookRows.filter(r=>{if(territoryBookStatusFilter==='followup'){if(!r.next_follow_up_at)return false}else if(territoryBookStatusFilter!=='all'&&r.status!==territoryBookStatusFilter)return false;if(territoryBookCategoryFilter!=='all'&&r.category!==territoryBookCategoryFilter)return false;return !q||`${r.company} ${r.contact_person||''} ${r.phone||''} ${r.email||''} ${r.street||''} ${r.zip||''} ${r.city||''}`.toLowerCase().includes(q)})}
function territoryPhoneHref(v){return 'tel:'+String(v||'').replace(/[^+\d]/g,'')}
function territoryMailHref(v,company=''){return 'mailto:'+encodeURIComponent(String(v||''))+'?subject='+encodeURIComponent('Räucherhaken24 · Kontakt '+company)}
function territoryMapHref(r){const addr=[r.street,r.zip,r.city].filter(Boolean).join(', ');return addr?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(addr):(r.latitude&&r.longitude?'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(r.latitude+','+r.longitude):'')}
function territoryBookRowHtml(r,admin){const map=territoryMapHref(r),source=r.source==='openstreetmap'?'OSM-Recherche':r.source==='csv'?'CSV-Import':'manuell',phone=(r.phone||r.mobile)?`${r.phone?`<a class="contactDirect phone" href="${territoryPhoneHref(r.phone)}">☎ ${esc(r.phone)}</a>`:''}${r.mobile?`${r.phone?'<br>':''}<a class="contactDirect phone" href="${territoryPhoneHref(r.mobile)}">📱 ${esc(r.mobile)}</a>`:''}`:'<span class="muted">Telefon / Mobil fehlt</span>',mail=r.email?`<a class="contactDirect mail" href="${territoryMailHref(r.email,r.company)}">✉ ${esc(r.email)}</a>`:'<span class="muted">E-Mail fehlt</span>',contact=r.last_contacted_at?`<b>${dt(r.last_contacted_at)}</b><br><small>${esc(TERRITORY_CONTACT_RESULTS[r.last_contact_result]||r.last_contact_result||'')}</small>`:'<span class="status s-pending">Noch nicht kontaktiert</span>',follow=r.next_follow_up_at?`<br><span class="tbFollow">Wiedervorlage ${dt(r.next_follow_up_at)}</span>`:'';return `<tr class="tb-${esc(r.status)}"><td><span class="tbCategory">${esc(r.category_label||territoryDirCategoryLabel(r.category))}</span><br><small>${source}</small></td><td><b>${esc(r.company)}</b><br><small>${esc(TERRITORY_DIR_STATUS[r.status]||r.status)}</small></td><td>${esc(r.street||'–')}<br><b>${esc(r.zip||'')} ${esc(r.city||'')}</b>${map?`<br><a target="_blank" rel="noopener" href="${map}">Maps ↗</a>`:''}</td><td>${esc(r.contact_person||'–')}</td><td>${phone}<br>${mail}</td><td>${contact}${follow}</td><td><div class="rowActions"><button class="miniBtn primaryMini" data-tb-contact="${esc(r.id)}">Kontaktiert / Kalender</button><button class="miniBtn" data-tb-history="${esc(r.id)}">Verlauf</button>${admin?`<button class="miniBtn" data-tb-edit="${esc(r.id)}">Bearbeiten</button>`:''}</div></td></tr>`}
function territoryBookAdminSelectHtml(code){if(!isAdmin())return '';const opts=(state.sales_territories||[]).map(x=>`<option value="${x.state_code}" ${sel(code,x.state_code)}>${esc(x.territory_book_no)} · ${esc(x.state_name)}</option>`).join('');return `<div class="territoryBookAdminSelect"><label>Festgebiet<select id="tbStateSelect">${opts}</select></label><span>Administrator sieht und pflegt alle Gebietsbücher. Kundenberater erhalten serverseitig nur ihr eigenes.</span></div>`}
function territoryBookVisualStats(rows){
 const total=rows.length,withPhone=rows.filter(r=>r.phone||r.mobile).length,withEmail=rows.filter(r=>r.email).length,complete=rows.filter(r=>(r.phone||r.mobile)&&r.email&&r.street&&r.zip&&r.city).length,contacted=rows.filter(r=>r.last_contacted_at).length,followups=rows.filter(r=>r.next_follow_up_at).length,uncontacted=rows.filter(r=>!r.last_contacted_at).length;
 const categoryMap={};rows.forEach(r=>{const key=r.category_label||territoryDirCategoryLabel(r.category);categoryMap[key]=(categoryMap[key]||0)+1});
 const categories=Object.entries(categoryMap).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([label,count])=>({label,count,pct:total?Math.round(count/total*100):0}));
 const cityMap={};rows.forEach(r=>{const key=[r.zip,r.city].filter(Boolean).join(' ').trim()||'Unbekannt';cityMap[key]=(cityMap[key]||0)+1});
 const cities=Object.entries(cityMap).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([label,count])=>({label,count}));
 const upcoming=rows.filter(r=>r.next_follow_up_at).sort((a,b)=>new Date(a.next_follow_up_at)-new Date(b.next_follow_up_at)).slice(0,4);
 return {total,withPhone,withEmail,complete,contacted,followups,uncontacted,categories,cities,upcoming};
}
function territoryBookProgressBar(label,count,total,accent='brown'){const pct=total?Math.max(0,Math.min(100,Math.round(count/total*100))):0;return `<div class="territoryStatBar ${accent}"><div><b>${esc(label)}</b><span>${count} / ${total}</span></div><div class="territoryStatTrack"><i style="width:${pct}%"></i></div></div>`}
function territoryBookCardHtml(r,admin){
 const map=territoryMapHref(r),statusLabel=TERRITORY_DIR_STATUS[r.status]||r.status||'Aktiv',catLabel=r.category_label||territoryDirCategoryLabel(r.category),phoneLabel=r.phone||r.mobile||'',mailLabel=r.email||'',assigned=(state.sales_reps||[]).find(x=>x.id===r.assigned_sales_rep_id),contactState=r.last_contacted_at?`${dt(r.last_contacted_at)} · ${esc(TERRITORY_CONTACT_RESULTS[r.last_contact_result]||r.last_contact_result||'Kontakt dokumentiert')}`:'Noch nicht kontaktiert',follow=r.next_follow_up_at?`<span class="territoryCardFollow">Wiedervorlage ${dt(r.next_follow_up_at)}</span>`:'',source=r.source==='openstreetmap'?'OSM-Recherche':r.source==='csv'?'CSV-Import':'manuell';
 return `<article class="territoryAddressCard status-${esc(r.status)}"><div class="territoryCardTop"><span class="territoryCategoryPill">${esc(catLabel)}</span><span class="territoryStatusPill">${esc(statusLabel)}</span></div><h4>${esc(r.company||'–')}</h4><div class="territoryAddressMeta"><b>${esc(r.street||'Straße fehlt')}</b><span>${esc([r.zip,r.city].filter(Boolean).join(' ')||'Ort fehlt')}</span></div><div class="territoryMiniList"><div><small>Ansprechpartner</small><b>${esc(r.contact_person||'–')}</b></div><div><small>Zuständig</small><b>${assigned?esc(assigned.name):'Gebiet allgemein'}</b></div><div><small>Quelle</small><b>${esc(source)}</b></div></div><div class="territoryContactList">${phoneLabel?`<a class="territoryQuickLink phone" href="${territoryPhoneHref(phoneLabel)}">☎ ${esc(phoneLabel)}</a>`:'<span class="muted">Telefon fehlt</span>'}${mailLabel?`<a class="territoryQuickLink mail" href="${territoryMailHref(mailLabel,r.company)}">✉ ${esc(mailLabel)}</a>`:'<span class="muted">E-Mail fehlt</span>'}${map?`<a class="territoryQuickLink map" target="_blank" rel="noopener" href="${map}">⌖ Google Maps öffnen</a>`:''}</div><div class="territoryCardStatus"><small>Kontaktstatus</small><b>${contactState}</b>${follow}</div><div class="territoryCardActions"><button class="miniBtn primaryMini" data-tb-contact="${esc(r.id)}">Kontaktiert / Kalender</button><button class="miniBtn" data-tb-history="${esc(r.id)}">Verlauf</button>${admin?`<button class="miniBtn" data-tb-edit="${esc(r.id)}">Bearbeiten</button>`:''}</div></article>`
}
function territoryIndustryGuideHtml(rows){
 const listRows=rows||[];const groups={};listRows.forEach(r=>{const label=r.category_label||territoryDirCategoryLabel(r.category)||'Sonstige';const g=groups[label]||(groups[label]={label,count:0,complete:0,withPhone:0,withEmail:0,cities:{},examples:[]});g.count++;if((r.phone||r.mobile)&&r.email&&r.street&&r.zip&&r.city)g.complete++;if(r.phone||r.mobile)g.withPhone++;if(r.email)g.withEmail++;const city=[r.zip,r.city].filter(Boolean).join(' ').trim()||'Unbekannt';g.cities[city]=(g.cities[city]||0)+1;if(r.company&&g.examples.length<3&&!g.examples.includes(r.company))g.examples.push(r.company)});const items=Object.values(groups).sort((a,b)=>b.count-a.count||a.label.localeCompare(b.label)).slice(0,12);
 return `<section class="panel territoryIndustryGuidePanel"><div class="territoryFeaturedHeader"><div><h3>Branchenführer im Gebiet</h3><span>${items.length} Schwerpunktbranchen für dieses Festgebiet</span></div><small>Der Kundenberater sieht direkt, welche Branchen im eigenen Gebiet relevant sind und kann ohne Suchen in die passende Liste springen.</small></div><div class="territoryIndustryGuideGrid">${items.length?items.map(item=>{const topCity=Object.entries(item.cities).sort((a,b)=>b[1]-a[1])[0];const cityLabel=topCity?`${topCity[0]} · ${topCity[1]} Einträge`:'Noch ohne Ortsschwerpunkt';const examples=item.examples.length?item.examples.map(x=>`<span>${esc(x)}</span>`).join(''):'<span>Beispiele folgen nach Datenpflege</span>';return `<article class="territoryIndustryCard"><div class="territoryIndustryHead"><div><h4>${esc(item.label)}</h4><small>${item.count} Adressen im Gebiet</small></div><b>${Math.round(item.count/Math.max(1,listRows.length)*100)}%</b></div><div class="territoryIndustryMeta"><span>Vollständig <b>${item.complete}</b></span><span>Telefon <b>${item.withPhone}</b></span><span>E-Mail <b>${item.withEmail}</b></span></div><div class="territoryIndustryCity">${esc(cityLabel)}</div><div class="territoryIndustryExamples">${examples}</div><div class="territoryIndustryActions"><button class="miniBtn primaryMini" data-tb-quick-category="${esc(item.label)}">Branche öffnen</button></div></article>`}).join(''):`<div class="territoryFeaturedEmpty"><b>Noch keine Branchen vorhanden</b><span>Sobald Adressen im Gebietsbuch liegen, entsteht hier automatisch ein Branchenführer.</span></div>`}</div></section>`
}

function territoryBookGraphicHtml(code,t,rows,sum,admin){
 const territoryRows=territoryBookRows||[],stats=territoryBookVisualStats(territoryRows),territoryName=t.state_name||state.territory_book_scope?.state_name||'',bookNo=t.territory_book_no||('FG-'+code),owner=t.owner_name||'Noch nicht fest vergeben',ownerRole=t.owner_sales_rep_id?'Gebietsverantwortung aktiv':'Weißgebiet / offen',ownerMembers=Number(t.member_count||0),ownerCustomers=Number(t.customer_count||0),featured=(rows.length?rows:territoryRows).slice(0,6),nextActions=stats.upcoming.length?stats.upcoming.map(r=>`<article><b>${esc(r.company)}</b><span>${esc([r.street,r.zip,r.city].filter(Boolean).join(', '))}</span><small>${dt(r.next_follow_up_at)} · ${esc(r.contact_person||'ohne Ansprechpartner')}</small></article>`).join(''):'<div class="territoryFeaturedEmpty"><b>Keine Wiedervorlagen geplant</b><span>Kontakte können direkt aus den Adressen heraus mit Kalender dokumentiert werden.</span></div>',topCities=stats.cities.length?stats.cities.map(c=>`<li><span>${esc(c.label)}</span><b>${c.count}</b></li>`).join(''):'<li><span>Noch keine Ortsdaten</span><b>0</b></li>',topCategories=stats.categories.length?stats.categories.map(c=>territoryBookProgressBar(c.label,c.count,stats.total,'green')).join(''):territoryBookProgressBar('Noch keine Kategorien',0,0,'green'),completeBars=[territoryBookProgressBar('Mit Telefon',stats.withPhone,stats.total,'brown'),territoryBookProgressBar('Mit E-Mail',stats.withEmail,stats.total,'blue'),territoryBookProgressBar('Vollständige Datensätze',stats.complete,stats.total,'green'),territoryBookProgressBar('Bereits kontaktiert',stats.contacted,stats.total,'gold')].join('');
 return `<section class="panel territoryGraphicPanel"><div class="territoryGraphicHero"><div class="territoryGraphicProfile"><small>GEBIETSBUCH · GRAFIKANSICHT</small><h3>${esc(bookNo)} · ${esc(territoryName)}</h3><p>Das Gebietsbuch wird nicht nur als Liste, sondern als echte Arbeitsoberfläche dargestellt: Karte, Kontaktqualität, Schwerpunktbranchen, Wiedervorlagen und direkte Schnellaktionen.</p><div class="territoryGraphicFlow"><article><b>${sum.active||0}</b><span>aktive Geschäfte & Vereine</span></article><article><b>${sum.candidate||0}</b><span>Recherche-Datensätze</span></article><article><b>${stats.contacted}</b><span>bereits kontaktierte Einträge</span></article><article><b>${sum.followups||stats.followups||0}</b><span>offene Wiedervorlagen</span></article></div><div class="territoryGraphicOwner"><div><small>Gebietsverantwortung</small><b>${esc(owner)}</b><span>${esc(ownerRole)}</span></div><div><small>Team / Kunden</small><b>${ownerMembers} Mitarbeiter</b><span>${ownerCustomers} Kunden im Gebiet</span></div><div class="territoryGraphicButtons"><button class="btn primary" id="tbOpenTerritories">Deutschlandkarte</button>${admin?'<button class="btn" id="tbOpenNationalDirectory">Deutschlandweit</button>':''}</div></div></div><div class="territoryBookOverviewMapWrap"><div id="territoryBookMap" class="territoryMap territoryBookOverviewMap"><div class="territoryMapLoading">Gebietskarte wird geladen …</div></div><div class="territoryMapLegendLine"><span><i class="legendDot fixed"></i> Festgebiet</span><span><i class="legendDot white"></i> Weißgebiet</span><span><i class="legendDot" style="background:${territoryColor(code)}"></i> aktuelles Gebiet</span></div></div></div><div class="territoryGraphicInsightGrid"><section class="territoryInsightCard"><div class="panelTitle"><h3>Schwerpunktbranchen</h3><span>nach Anzahl im Gebiet</span></div><div class="territoryStatBars">${topCategories}</div></section><section class="territoryInsightCard"><div class="panelTitle"><h3>Kontaktqualität</h3><span>wie gut das Gebiet bereits pflegbar ist</span></div><div class="territoryStatBars">${completeBars}</div><div class="territoryHealthLine"><div><small>Noch offen</small><b>${stats.uncontacted}</b></div><div><small>Komplett pflegbar</small><b>${stats.complete}</b></div></div></section><section class="territoryInsightCard"><div class="panelTitle"><h3>Orte & Gebietsschwerpunkte</h3><span>wo die meisten Datensätze liegen</span></div><ul class="territoryCityList">${topCities}</ul></section><section class="territoryInsightCard"><div class="panelTitle"><h3>Nächste Wiedervorlagen</h3><span>direkt aus dem Gebietsbuch</span></div><div class="territoryUpcomingList">${nextActions}</div></section></div><div class="territoryFeaturedHeader"><div><h3>Grafische Adresskarten</h3><span>${featured.length} Einträge als schnelle Arbeitskarten</span></div><small>Ideal für Anruf, E-Mail, Maps und Follow-up ohne Tabellenchaos.</small></div><div class="territoryAddressCardGrid">${featured.length?featured.map(r=>territoryBookCardHtml(r,admin)).join(''):`<div class="territoryFeaturedEmpty"><b>Keine Adressen im aktuellen Filter</b><span>Filter anpassen oder neue Datensätze anlegen.</span></div>`}</div></section>`
}


function renderTerritoryBook(){
 if(!can('view_territory_book'))return setView('dashboard');
 const code=territoryBookScopeCode();
 if(!code){ws.innerHTML=`<div class="sectionHead"><div><h2>Mein Gebietsbuch</h2><p>Ihrem Kundenberaterkonto wurde noch kein Festgebiet zugeordnet.</p></div></div><div class="empty"><b>Kein Gebietsbuch</b>Der Administrator muss zuerst unter Kundenberater → Gebiet vergeben ein Bundesland zuordnen.</div>`;return}
 if(territoryBookRowsCode!==code){ws.innerHTML='<div class="loadingState"><div class="spinner"></div><p>Gebietsbuch wird geladen …</p></div>';territoryBookLoad(code);return}
 const t=(state.sales_territories||[]).find(x=>x.state_code===code)||state.territory_directory_summary?.scope||{},rows=territoryBookFilteredRows(),sum=state.territory_directory_summary||{},cats=state.territory_directory_categories||{},admin=isAdmin();
 const adminActions=admin?'<button class="btn" id="tbDiscover">Branchen-Scout</button><button class="btn" id="tbImport">CSV importieren</button><button class="btn primary" id="tbNew">+ Adresse</button>':'';
 const categoryOptions=Object.entries(cats).map(([k,v])=>`<option value="${k}" ${sel(territoryBookCategoryFilter,k)}>${esc(v)}</option>`).join('');
 const table=rows.length?`<table class="dataTable"><thead><tr><th>Branche</th><th>Firma / Verein</th><th>Adresse</th><th>Ansprechpartner</th><th>Telefon / E-Mail</th><th>Kontaktstatus</th><th>Aktionen</th></tr></thead><tbody>${rows.map(r=>territoryBookRowHtml(r,admin)).join('')}</tbody></table>`:`<div class="empty"><b>Keine Adressen in diesem Filter</b>${admin?'Lege eine Adresse an oder starte den Branchen-Scout.':'Der Administrator pflegt die Adressen Ihres Festgebietes.'}</div>`;
 const graphic=territoryBookGraphicHtml(code,t,rows,sum,admin);ws.innerHTML=`<div class="sectionHead"><div><h2>${admin?'Gebietsbuch-Zentrale':'Mein Gebietsbuch'}</h2><p>${esc(t.territory_book_no||'FG-'+code)} · ${esc(t.state_name||state.territory_book_scope?.state_name||'')} · Branchenadressen, Kontaktarbeit und Wiedervorlagen.</p></div><div class="sectionActions">${adminActions}<button class="btn" id="tbPrint">PDF / Drucken</button></div></div>${territoryBookAdminSelectHtml(code)}${territoryBookExecutiveSummaryHtml(code,t,sum)}${graphic}<div class="metricGrid territoryBookMetrics">${metric('Adressen',sum.total||territoryBookRows.length,'im Gebietsbuch')}${metric('Aktiv',sum.active||0,'geprüfte Geschäfte & Vereine')}${metric('Recherche',sum.candidate||0,'noch zu prüfen')}${metric('Wiedervorlagen',sum.followups||0,'geplant')}</div><div class="territoryBookTabs"><button data-tb-status="active" class="${territoryBookStatusFilter==='active'?'active':''}">Aktive Geschäfte & Vereine</button><button data-tb-status="candidate" class="${territoryBookStatusFilter==='candidate'?'active':''}">Recherche</button><button data-tb-status="followup" class="${territoryBookStatusFilter==='followup'?'active':''}">Kalender / Wiedervorlage</button><button data-tb-status="all" class="${territoryBookStatusFilter==='all'?'active':''}">Alle Adressen</button></div><div class="territoryBookToolbar"><input id="tbSearch" type="search" placeholder="Firma, Ansprechpartner, Telefon, PLZ, Ort …" value="${esc(territoryBookSearch)}"><select id="tbCategory"><option value="all">Alle Branchen</option>${categoryOptions}</select><button class="btn" id="tbRefresh">Aktualisieren</button></div><div class="panel tableWrap territoryBookTable">${table}</div><div class="territorySourceNotice"><b>Datenqualität:</b> Automatisch recherchierte öffentliche Einträge werden zunächst als „Recherche“ markiert. Erst nach Prüfung durch den Administrator erscheinen sie als „Aktiv“. Quelle bei OSM-Importen: © OpenStreetMap-Mitwirkende.</div>`;
 bindTerritoryBook(code)
}
function bindTerritoryBook(code){if($('#tbStateSelect'))$('#tbStateSelect').onchange=()=>{territoryBookAdminState=$('#tbStateSelect').value;territoryBookRowsCode='';renderTerritoryBook()};$$('[data-tb-status]').forEach(b=>b.onclick=()=>{territoryBookStatusFilter=b.dataset.tbStatus;renderTerritoryBook()});$('#tbCategory').onchange=()=>{territoryBookCategoryFilter=$('#tbCategory').value;renderTerritoryBook()};$('#tbSearch').oninput=()=>{territoryBookSearch=$('#tbSearch').value;renderTerritoryBook();setTimeout(()=>{$('#tbSearch')?.focus()},0)};$('#tbRefresh').onclick=()=>{territoryBookRowsCode='';renderTerritoryBook()};$('#tbPrint').onclick=()=>window.open('./territory-book-print.php?state_code='+encodeURIComponent(code),'_blank','noopener');if($('#tbNew'))$('#tbNew').onclick=()=>territoryDirectoryModal(null,code);if($('#tbDiscover'))$('#tbDiscover').onclick=()=>territoryDiscoverModal(code);if($('#tbImport'))$('#tbImport').onclick=()=>territoryCsvModal(code);if($('#tbOpenTerritories'))$('#tbOpenTerritories').onclick=()=>setView('territories');if($('#tbOpenNationalDirectory'))$('#tbOpenNationalDirectory').onclick=()=>{territoryBookAdminState='all';territoryBookRowsCode='';setView('territorybook')};const mapHost=$('#territoryBookMap');if(mapHost)renderTerritoryMiniMap(mapHost,code,isAdmin()?(picked=>{territoryBookAdminState=picked;territoryBookRowsCode='';renderTerritoryBook()}):null);$$('[data-tb-contact]').forEach(b=>b.onclick=()=>territoryContactModal(b.dataset.tbContact));$$('[data-tb-history]').forEach(b=>b.onclick=()=>territoryHistoryModal(b.dataset.tbHistory));$$('[data-tb-edit]').forEach(b=>b.onclick=()=>territoryDirectoryModal(b.dataset.tbEdit,code))}
function territoryDirectoryModal(id,code){const r=territoryBookRows.find(x=>x.id===id)||{},cats=state.territory_directory_categories||{},reps=(state.sales_reps||[]).filter(x=>x.status==='active'&&(!x.state_code||x.state_code===code));openModal(`<div class="modalHead"><small>GEBIETSBUCH · ${esc((state.sales_territories||[]).find(x=>x.state_code===code)?.territory_book_no||code)}</small><h2>${id?'Adresse bearbeiten':'Adresse anlegen'}</h2><p>Administrator pflegt vollständige Branchen- und Kontaktdaten.</p></div><div class="modalBody"><div class="formGrid"><label>Branche<select id="tdCat">${Object.entries(cats).map(([k,v])=>`<option value="${k}" ${sel(r.category||'other',k)}>${esc(v)}</option>`).join('')}</select></label><label>Status<select id="tdStatus"><option value="candidate" ${sel(r.status||'active','candidate')}>Recherche · zu prüfen</option><option value="active" ${sel(r.status||'active','active')}>Aktiv / freigegeben</option><option value="paused" ${sel(r.status,'paused')}>Pausiert</option><option value="archived" ${sel(r.status,'archived')}>Archiviert</option></select></label><label class="full">Firma / Verein<input id="tdCompany" value="${esc(r.company||'')}"></label><label>Ansprechpartner<input id="tdContact" value="${esc(r.contact_person||'')}"></label><label>Zuständiger Kundenberater<select id="tdRep"><option value="">Gesamtes Gebiet / nicht einzeln zugewiesen</option>${reps.map(x=>`<option value="${esc(x.id)}" ${sel(r.assigned_sales_rep_id||'',x.id)}>${esc(x.employee_no)} · ${esc(x.name)}</option>`).join('')}</select></label><label>Telefon<input id="tdPhone" value="${esc(r.phone||'')}"></label><label>Mobil / Handy<input id="tdMobile" value="${esc(r.mobile||'')}"></label><label>E-Mail<input id="tdEmail" type="email" value="${esc(r.email||'')}"></label><label>Webseite<input id="tdWebsite" value="${esc(r.website||'')}"></label><label>Straße / Hausnr.<input id="tdStreet" value="${esc(r.street||'')}"></label><label>PLZ<input id="tdZip" value="${esc(r.zip||'')}"></label><label>Ort<input id="tdCity" value="${esc(r.city||'')}"></label><label class="full">Notiz<textarea id="tdNotes">${esc(r.notes||'')}</textarea></label></div><div class="formActions"><button class="btn" id="tdCancel">Abbrechen</button><button class="btn primary" id="tdSave">Speichern</button></div></div>`);$('#tdCancel').onclick=closeModal;$('#tdSave').onclick=async()=>{try{const d=await api({action:'territory_directory_save',id:r.id||'',state_code:code,category:$('#tdCat').value,status:$('#tdStatus').value,company:$('#tdCompany').value,contact_person:$('#tdContact').value,assigned_sales_rep_id:$('#tdRep').value,phone:$('#tdPhone').value,mobile:$('#tdMobile').value,email:$('#tdEmail').value,website:$('#tdWebsite').value,street:$('#tdStreet').value,zip:$('#tdZip').value,city:$('#tdCity').value,notes:$('#tdNotes').value});territoryBookRows=d.rows||[];state.territory_directory_summary=d.summary||{};territoryBookRowsCode=code;toast('Gebietsbuch-Adresse gespeichert');closeModal();renderTerritoryBook()}catch(e){toast(e.message,true)}}}
function localDateTimeValue(d=new Date()){const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,16)}
function territoryContactModal(id){const r=territoryBookRows.find(x=>x.id===id);if(!r)return;openModal(`<div class="modalHead"><small>KONTAKTIERT · KALENDER</small><h2>${esc(r.company)}</h2><p>${esc([r.street,r.zip,r.city].filter(Boolean).join(', '))}</p></div><div class="modalBody"><div class="contactShortcutGrid">${r.phone?`<a class="contactShortcut" href="${territoryPhoneHref(r.phone)}"><b>☎ Direkt anrufen</b><span>${esc(r.phone)}</span></a>`:''}${r.email?`<a class="contactShortcut" href="${territoryMailHref(r.email,r.company)}"><b>✉ E-Mail schreiben</b><span>${esc(r.email)}</span></a>`:''}</div><div class="formGrid"><label>Kontakt am<input id="tcAt" type="datetime-local" value="${localDateTimeValue()}"></label><label>Kontaktart<select id="tcMethod"><option value="phone">Telefon</option><option value="email">E-Mail</option><option value="visit">Vor-Ort-Besuch</option><option value="whatsapp">WhatsApp</option><option value="letter">Brief/Post</option><option value="other">Sonstiges</option></select></label><label>Ergebnis<select id="tcResult">${Object.entries(TERRITORY_CONTACT_RESULTS).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></label><label>Wiedervorlage / Termin<input id="tcFollow" type="datetime-local"></label><label class="full">Gesprächsnotiz<textarea id="tcNotes" placeholder="Gespräch, Interesse, Bedarf, nächster Schritt …"></textarea></label></div><div class="formActions"><button class="btn" id="tcCancel">Abbrechen</button><button class="btn" id="tcSave">Kontakt speichern</button><button class="btn primary" id="tcSaveCal">Speichern + Kalender</button></div></div>`);$('#tcCancel').onclick=closeModal;const save=async(withCal)=>{try{const follow=$('#tcFollow').value,d=await api({action:'territory_directory_contact',id:r.id,contact_at:$('#tcAt').value,method:$('#tcMethod').value,result:$('#tcResult').value,next_follow_up_at:follow,notes:$('#tcNotes').value});territoryBookRows=d.rows||territoryBookRows;state.territory_directory_summary=d.summary||state.territory_directory_summary;if(withCal&&follow)downloadTerritoryIcs(r,follow,$('#tcNotes').value);toast(follow?'Kontakt und Wiedervorlage gespeichert':'Kontakt gespeichert');closeModal();renderTerritoryBook()}catch(e){toast(e.message,true)}};$('#tcSave').onclick=()=>save(false);$('#tcSaveCal').onclick=()=>save(true)}
function downloadTerritoryIcs(r,localValue,note=''){const start=new Date(localValue),end=new Date(start.getTime()+45*60000),fmt=d=>d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z$/,'Z'),escI=v=>String(v||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'),lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Raeucherhaken24//Gebietsbuch V73//DE','BEGIN:VEVENT','UID:'+Date.now()+'@raeucherhaken24.de','DTSTAMP:'+fmt(new Date()),'DTSTART:'+fmt(start),'DTEND:'+fmt(end),'SUMMARY:'+escI('Wiedervorlage: '+r.company),'LOCATION:'+escI([r.street,r.zip,r.city].filter(Boolean).join(', ')),'DESCRIPTION:'+escI(note),'END:VEVENT','END:VCALENDAR'];const blob=new Blob([lines.join('\r\n')],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Gebietsbuch_'+String(r.company||'Termin').replace(/[^a-zA-Z0-9äöüÄÖÜß_-]+/g,'_')+'.ics';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200)}
async function territoryHistoryModal(id){const r=territoryBookRows.find(x=>x.id===id);if(!r)return;try{const d=await api({action:'territory_directory_history',id});openModal(`<div class="modalHead"><small>KONTAKTVERLAUF</small><h2>${esc(r.company)}</h2><p>${d.history?.length||0} dokumentierte Kontakte</p></div><div class="modalBody"><div class="territoryHistory">${(d.history||[]).map(h=>`<article><time>${dt(h.contact_at)}</time><div><b>${esc(h.method_label)} · ${esc(h.result_label)}</b><span>${esc(h.sales_rep_name||h.user_name||'Orgaboard')}</span><p>${esc(h.notes||'Keine Notiz')}</p>${h.next_follow_up_at?`<small>Wiedervorlage: ${dt(h.next_follow_up_at)}</small>`:''}</div></article>`).join('')||'<div class="empty">Noch kein Kontakt dokumentiert.</div>'}</div></div>`)}catch(e){toast(e.message,true)}}
function territoryCsvModal(code){openModal(`<div class="modalHead"><small>GEBIETSBUCH · CSV-IMPORT</small><h2>Adressliste importieren</h2><p>Bis zu 500 Zeilen pro Import. Semikolon-getrennt.</p></div><div class="modalBody"><div class="moduleNotice"><b>Spalten:</b> Kategorie;Firma;Ansprechpartner;Telefon;Mobil;Email;Webseite;Straße;PLZ;Ort;Notiz</div><textarea id="tbCsv" class="csvImportArea" placeholder="butcher;Fleischerei Muster;Max Mustermann;+49...;+49 Mobil...;info@...;https://...;Musterweg 1;24100;Musterstadt;Erstkontakt"></textarea><div class="formActions"><button class="btn" id="tbCsvCancel">Abbrechen</button><button class="btn primary" id="tbCsvRun">Importieren</button></div></div>`);$('#tbCsvCancel').onclick=closeModal;$('#tbCsvRun').onclick=async()=>{const lines=$('#tbCsv').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),rows=lines.map(line=>{const c=line.split(';');return {category:c[0]||'other',company:c[1]||'',contact_person:c[2]||'',phone:c[3]||'',mobile:c[4]||'',email:c[5]||'',website:c[6]||'',street:c[7]||'',zip:c[8]||'',city:c[9]||'',notes:c.slice(10).join(';')}});try{const d=await api({action:'territory_directory_bulk_import',state_code:code,rows});territoryBookRows=d.rows||[];state.territory_directory_summary=d.summary||{};territoryBookRowsCode=code;territoryBookStatusFilter='candidate';toast((d.imported||0)+' Adressen importiert');closeModal();renderTerritoryBook()}catch(e){toast(e.message,true)}}}


