function territoryBookScopeCode(){return isAdmin()?(territoryBookAdminState||'all'):(state.territory_book_scope?.state_code||'')}
async function territoryBookLoad(code){if(territoryBookLoading)return;territoryBookLoading=true;try{const d=await api({action:'territory_directory_search',state_code:code==='all'?'':code,status:territoryBookStatusFilter,category:territoryBookCategoryFilter,contact:territoryDirectoryContactFilter,q:territoryBookSearch,limit:territoryDirectoryPageSize,offset:territoryDirectoryOffset});territoryBookRows=d.rows||[];territoryBookRowsCode=code;territoryDirectoryTotal=Number(d.total||0);state.territory_directory_summary=d.summary||{};state.territory_directory_national_summary=d.national_summary||state.territory_directory_national_summary||{};if(!isAdmin())state.territory_book_scope=d.scope||state.territory_book_scope}catch(e){toast(e.message,true);territoryBookRows=[];territoryBookRowsCode=code;territoryDirectoryTotal=0}finally{territoryBookLoading=false;if(current==='territorybook')renderTerritoryBook()}}
