function renderSettings(){const s=state.settings||{};ws.innerHTML=`<div class="sectionHead"><div><h2>Einstellungen</h2><p>Shopparameter und Admin-Sicherheit verwalten.</p></div></div><div class="settingsGrid"><section class="panel settingsPanel"><h3>Shopparameter</h3><div class="formGrid"><label class="full">Shopname<input id="setName" value="${esc(s.shop_name||'Räucherhaken24')}"></label><label>Versandfrei ab (€)<input id="setThreshold" type="number" step="0.01" value="${Number(s.shipping_threshold??39)}"></label><label>Versandkosten (€)<input id="setShipping" type="number" step="0.01" value="${Number(s.shipping_cost??9.5)}"></label><label>MwSt. (%)<input id="setVat" type="number" step="1" value="${Number(s.vat_rate??19)}"></label></div><div class="formActions"><button class="btn primary" id="saveSettings">Speichern</button></div></section><section class="panel settingsPanel"><h3>Admin-Passwort ändern</h3><div class="formGrid"><label class="full">Aktuelles Passwort<input id="pwCurrent" type="password"></label><label class="full">Neues Passwort<input id="pwNew" type="password" minlength="10"></label></div><div class="formActions"><button class="btn" id="changePassword">Passwort ändern</button></div><p class="muted tiny">Mindestens 10 Zeichen; besser 14+ Zeichen.</p></section></div>`;$('#saveSettings').onclick=async()=>{try{await api({action:'settings_save',shop_name:$('#setName').value,shipping_threshold:+$('#setThreshold').value,shipping_cost:+$('#setShipping').value,vat_rate:+$('#setVat').value});toast('Einstellungen gespeichert');await load(true)}catch(e){toast(e.message,true)}};$('#changePassword').onclick=async()=>{try{await api({action:'password_change',current:$('#pwCurrent').value,new:$('#pwNew').value});toast('Admin-Passwort geändert');$('#pwCurrent').value=$('#pwNew').value=''}catch(e){toast(e.message,true)}}}

