function exportOrders(){const rows=filteredOrders(),lines=[['Bestellnummer','Datum','Kunde','E-Mail','Herkunft','Fester Kundenberater','Provisionsgutschrift an','Zuordnungsgrund','Status','Zahlung','Gesamt'].join(';')];rows.forEach(o=>lines.push([o.order_no||o.id,donly(o.created_at),orderCustomer(o),orderEmail(o),o.sales_channel_label||salesChannelLabel(o.sales_channel||o.source),o.sales_rep_name||repName(o.sales_rep_id),commissionRepName(o),o.commission_note||attributionLabel(o),state.order_statuses[o.status]||o.status,o.payment_status,money(orderTotal(o)).replace(' €','')].map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')));const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='raeucherhaken24-bestellungen-v69-mit-verkaufsherkunft.csv';a.click();URL.revokeObjectURL(a.href)}
function printInvoice(o){const c=o.customer||{},t=o.totals||{},items=o.items||[],w=window.open('','_blank','width=900,height=900');if(!w)return toast('Pop-up wurde blockiert',true);w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Rechnung ${esc(o.order_no||o.id)}</title><style>body{font-family:Arial,sans-serif;color:#222;padding:45px;max-width:800px;margin:auto}header{border-bottom:3px solid #70461f;padding-bottom:18px;margin-bottom:28px}h1{margin:0;color:#5b3a1e}small{color:#777}section{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid #ddd;font-size:13px}th{font-size:11px;color:#666}td:last-child,th:last-child{text-align:right}.tot{width:320px;margin:20px 0 0 auto}.tot div{display:flex;justify-content:space-between;padding:4px}.grand{font-size:17px;font-weight:bold;border-top:2px solid #333;margin-top:6px;padding-top:9px!important}.note{margin-top:35px;font-size:11px;color:#666}@media print{button{display:none}}</style></head><body><header><h1>Räucherhaken24</h1><small>Rechnungs-/Bestellbeleg</small></header><h2>Beleg ${esc(o.order_no||o.id)}</h2><section><div><b>Rechnung an</b><br>${esc(c.name||'')}<br>${esc(c.street||'')}<br>${esc(c.zip||'')} ${esc(c.city||'')}<br>${esc(c.email||'')}</div><div><b>Bestelldatum</b><br>${donly(o.created_at)}<br><br><b>Zahlungsstatus</b><br>${o.payment_status==='paid'?'Bezahlt':'Offen'}</div></section><table><thead><tr><th>Position</th><th>Menge</th><th>Einzel</th><th>Gesamt</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.name||x.id)}${itemMeta(x)?'<br><small>'+esc(itemMeta(x))+'</small>':''}</td><td>${Number(x.qty||1)}</td><td>${money(x.unit_price||0)}</td><td>${money((x.unit_price||0)*(x.qty||1))}</td></tr>`).join('')}</tbody></table><div class="tot"><div><span>Warenwert</span><b>${money(t.subtotal||0)}</b></div><div><span>Versand</span><b>${money(t.shipping||0)}</b></div><div><span>inkl. 19 % MwSt.</span><b>${money(t.vat||0)}</b></div><div class="grand"><span>Gesamt</span><b>${money(t.gross||orderTotal(o))}</b></div></div><p class="note">Dieser Ausdruck wird aus den gespeicherten Bestelldaten erzeugt. Vor produktivem Einsatz als steuerliche Rechnung müssen Pflichtangaben und fortlaufende Rechnungsnummern abschließend eingerichtet werden.</p><button onclick="print()">Drucken</button></body></html>`);w.document.close()}


function periodLabel(p){if(!p)return'aktueller Monat';const [y,m]=p.split('-');return new Date(+y,+m-1,1).toLocaleDateString('de-DE',{month:'long',year:'numeric'})}
function commissionScaleHtml(){return `<div class="commissionScale progressive"><div><b>0–10.000 €</b><span>5 %</span><small>nur auf diesen Umsatzbereich</small></div><div><b>10.000–20.000 €</b><span>7,5 %</span><small>nur auf diesen Umsatzbereich</small></div><div><b>20.000–30.000 €</b><span>10 %</span><small>nur auf diesen Umsatzbereich</small></div><div><b>30.000–50.000 €</b><span>12,5 %</span><small>nur auf diesen Umsatzbereich</small></div><div><b>50.000–75.000 €</b><span>15 %</span><small>nur auf diesen Umsatzbereich</small></div><div><b>ab 75.000 €</b><span>20 %</span><small>nur auf den Mehrumsatz</small></div></div>`}
function salesStatsPanel(st,title='Verkaufsstatistik'){st=st||{};const next=st.next_threshold,eff=Number(st.effective_rate||0),credits=st.credited_orders||[];return `<div class="sectionHead miniSection"><div><h2>${esc(title)}</h2><p>Volle progressive Provision auf alle bezahlten Aufträge, die dir fachlich gutgeschrieben wurden – auch bei späteren Onlinekäufen deiner Kunden.</p></div></div><div class="metricGrid repMetrics">${metric('Nettoumsatz',money(st.net_revenue||0),'voll provisionsfähig')}${metric('Provision',money(st.commission||0),'effektiv '+eff.toLocaleString('de-DE',{maximumFractionDigits:2})+' %')}${metric('Gutgeschriebene Aufträge',st.order_count||0,'im Zeitraum')}${metric('Verkaufte Einheiten',st.item_qty||0,'Stück / Sets')}</div>${next?`<div class="moduleNotice"><b>Nächste Umsatzstufe:</b> Noch ${money(st.gap_to_next||0)} bis ${money(next)}. Der höhere Satz gilt progressiv für den zusätzlichen Umsatzbereich.</div>`:`<div class="moduleNotice goodNotice"><b>Spitzenstufe erreicht:</b> Umsatz oberhalb von 75.000 € wird mit 20 % vergütet.</div>`}${commissionScaleHtml()}<section class="panel commissionLedger"><div class="panelTitle"><h3>Provisionsgutschriften</h3><span>${credits.length} Aufträge</span></div>${credits.length?`<div class="tableWrap"><table class="dataTable"><thead><tr><th>Datum</th><th>Bestellung</th><th>Kunde</th><th>Herkunft</th><th>Gutschrift-Grund</th><th>Nettoumsatz</th><th>Provisionsanteil</th></tr></thead><tbody>${credits.map(x=>`<tr class="${x.sales_channel==='online'?'onlineCreditRow':''}"><td>${donly(x.created_at)}</td><td><b>${esc(x.order_no)}</b></td><td>${esc(x.customer_name||'–')}</td><td><span class="salesOriginTag origin-${esc(x.sales_channel||'other')}">${esc(x.sales_channel_label||salesChannelLabel(x.sales_channel))}</span></td><td><b>${x.sales_channel==='online'?'Online gekauft · Provisionsgutschrift':esc(x.commission_attribution_label||'Provisionsgutschrift')}</b><small class="tableSub">${esc(x.commission_note||'')}</small></td><td class="money">${money(x.net||0)}</td><td class="money commissionMoney">${money(x.commission_credit||0)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><b>Noch keine Provisionsgutschriften</b>Es werden nur bezahlte, nicht stornierte und dir zugeordnete Aufträge berücksichtigt.</div>'}</section><div class="panel tableWrap" style="margin-top:18px">${(st.breakdown||[]).length?`<table class="dataTable"><thead><tr><th>Art.-Nr.</th><th>Produkt</th><th>Menge</th><th>Nettoumsatz</th></tr></thead><tbody>${st.breakdown.map(x=>`<tr><td><b>${esc(x.article_no||'–')}</b></td><td>${esc(x.name)}</td><td>${Number(x.qty||0)}</td><td class="money">${money(x.net||0)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><b>Noch kein provisionsfähiger Umsatz</b>Es werden nur bezahlte und nicht stornierte Aufträge berücksichtigt.</div>'}</div>`}
function earningsTier(net){net=Math.max(0,Number(net)||0);if(net>=75000)return{rate:20,from:75000,to:null,label:'20 % Spitzenstufe'};if(net>=50000)return{rate:15,from:50000,to:75000,label:'15 % Platin'};if(net>=30000)return{rate:12.5,from:30000,to:50000,label:'12,5 % Gold'};if(net>=20000)return{rate:10,from:20000,to:30000,label:'10 % Silber'};if(net>=10000)return{rate:7.5,from:10000,to:20000,label:'7,5 % Bronze'};return{rate:5,from:0,to:10000,label:'5 % Starter'}}
function earningsCommission(net){net=Math.max(0,Number(net)||0);const tiers=[{from:0,to:10000,rate:.05},{from:10000,to:20000,rate:.075},{from:20000,to:30000,rate:.10},{from:30000,to:50000,rate:.125},{from:50000,to:75000,rate:.15},{from:75000,to:Infinity,rate:.20}];let total=0;for(const t of tiers){if(net<=t.from)break;const part=Math.min(net,t.to)-t.from;if(part>0)total+=part*t.rate;}return total}
function revenueForCommission(target){target=Math.max(0,Number(target)||0);if(target<=0)return 0;const tiers=[{from:0,to:10000,rate:.05},{from:10000,to:20000,rate:.075},{from:20000,to:30000,rate:.10},{from:30000,to:50000,rate:.125},{from:50000,to:75000,rate:.15},{from:75000,to:Infinity,rate:.20}];let remaining=target;for(const t of tiers){const cap=t.to===Infinity?Infinity:(t.to-t.from)*t.rate;if(remaining<=cap||cap===Infinity)return t.from+remaining/t.rate;remaining-=cap;}return 0}
function businessDaysRemaining(){const d=new Date(),end=new Date(d.getFullYear(),d.getMonth()+1,0),x=new Date(d.getFullYear(),d.getMonth(),d.getDate());let n=0;for(;x<=end;x.setDate(x.getDate()+1)){const wd=x.getDay();if(wd!==0&&wd!==6)n++}return Math.max(1,n)}
function earningStatsForSelected(){if(!isAdmin())return state.my_sales_stats||{};const reps=state.sales_reps||[];if(!earningsRepId&&reps.length)earningsRepId=reps[0].id;return reps.find(r=>r.id===earningsRepId)?.stats_current||{period:'',net_revenue:0,commission:0,commission_rate:7.5,order_count:0,item_qty:0}}
function earningRepForSelected(){if(!isAdmin())return{name:state.current_user?.display_name||'Außendienst',id:state.current_user?.sales_rep_id||''};const reps=state.sales_reps||[];if(!earningsRepId&&reps.length)earningsRepId=reps[0].id;return reps.find(r=>r.id===earningsRepId)||{name:'Planung ohne Mitarbeiter',id:''}}
function renderEarnings(){if(!can('view_earnings_calculator'))return setView('dashboard');const st=earningStatsForSelected(),rep=earningRepForSelected(),cur=Number(st.net_revenue||0),days=businessDaysRemaining();const repPicker=isAdmin()?`<label class="earnRepPicker">Mitarbeiter<select id="earnRepSelect"><option value="">Planung ohne Mitarbeiter</option>${(state.sales_reps||[]).map(r=>`<option value="${esc(r.id)}" ${sel(earningsRepId,r.id)}>${esc(r.employee_no)} · ${esc(r.name)}</option>`).join('')}</select></label>`:'';ws.innerHTML=`<div class="sectionHead"><div><h2>${isAdmin()?'Verdienst- & Provisionsrechner':'Mein Verdienst- & Provisionsrechner'}</h2><p>Monatsverdienst planen, Provisionsstufen simulieren und Verkaufsziele rückwärts berechnen.</p></div>${repPicker}</div><div class="earningsHero"><div><small>AKTUELLER MONAT · ${esc(periodLabel(st.period))}</small><h3>${esc(rep.name||'Außendienst')}</h3><p>Der Ist-Umsatz kommt automatisch aus bezahlten, nicht stornierten Aufträgen. Eigene Planwerte verändern keine Bestellungen und keine Abrechnung.</p></div><div class="earningsHeroMetric"><span>Aktuell provisionsfähig</span><strong>${money(cur)}</strong><small>${Number(st.commission_rate||7.5).toLocaleString('de-DE')} % · ${money(st.commission||0)} Provision</small></div></div><div class="earningsLayout"><section class="panel panelPad"><div class="panelTitle plain"><h3>1. Monatsplanung</h3><span>Deine Annahmen</span></div><div class="formGrid earnForm"><label>Ist-Nettoumsatz (€)<input id="earnCurrent" type="number" step="0.01" value="${cur.toFixed(2)}" ${isAdmin()?'':'readonly'}></label><label>Geplanter zusätzlicher Nettoumsatz (€)<input id="earnExtra" type="number" min="0" step="100" value="0"></label><label>Grundvergütung / Fixum brutto (€)<input id="earnBase" type="number" min="0" step="50" value="0"></label><label>Zusätzlicher steuerpflichtiger Bonus (€)<input id="earnBonus" type="number" min="0" step="25" value="0"></label><label>Kosten-/Spesen-Erstattung (€)<input id="earnReimburse" type="number" min="0" step="25" value="0"></label><label>Eigene nicht erstattete Kosten (€)<input id="earnOwnCosts" type="number" min="0" step="25" value="0"></label><label>Persönlicher Plan-Abzug (%)<input id="earnDeduct" type="number" min="0" max="80" step="1" value="35"></label><label>Verbleibende Verkaufstage<input id="earnDays" type="number" min="1" max="31" value="${days}"></label><label>Ø Netto-Auftragswert (€)<input id="earnAvgOrder" type="number" min="1" step="10" value="250"></label><label>Ziel-Nettoumsatz (€)<input id="earnTargetRevenue" type="number" min="0" step="500" value="${Math.max(15000,Math.ceil(cur/5000)*5000||15000)}"></label><label>Wunsch-Provision (€)<input id="earnTargetCommission" type="number" min="0" step="100" value="2000"></label><label>Gewünschte Auszahlung ca. (€)<input id="earnTargetPayout" type="number" min="0" step="100" value="3000"></label></div><div class="moduleNotice"><b>Wichtig:</b> „Persönlicher Plan-Abzug“ ist nur deine eigene Planungsannahme für Steuern/Sozialabgaben. Das ist keine Lohnabrechnung und ersetzt keine steuerliche Berechnung.</div></section><section class="panel panelPad"><div class="panelTitle plain"><h3>2. Ergebnis</h3><span>Live berechnet</span></div><div id="earnResult"></div></section></div><section class="panel panelPad earningsScenarios"><div class="panelTitle plain"><h3>3. Umsatz-Szenarien</h3><span>Was bringt welche Stufe?</span></div><div id="earnScenarios"></div></section><section class="panel panelPad earningsExplain"><h3>So liest du den Rechner</h3><div class="securityGrid"><div><b>Nettoumsatz entscheidet</b><span>Die Provisionsstufe richtet sich nach dem bezahlten Nettowarenumsatz ohne Versandkosten im laufenden Kalendermonat.</span></div><div><b>Progressive Staffel</b><span>Jeder Prozentsatz gilt nur für den jeweiligen Umsatzbereich. Eine höhere Stufe erhöht nicht rückwirkend die Provision auf den gesamten Monatsumsatz.</span></div><div><b>Ziel rückwärts rechnen</b><span>Der Rechner zeigt, welchen Nettoumsatz du mindestens brauchst, um eine gewünschte Provision oder eine grobe Wunschauszahlung zu erreichen.</span></div><div><b>Planung ≠ Abrechnung</b><span>Fixum, Bonus, Erstattungen und Plan-Abzug sind frei wählbare Szenariowerte. Verbindlich ist nur die später tatsächlich vereinbarte Vergütung.</span></div></div></section>`;
 if($('#earnRepSelect'))$('#earnRepSelect').onchange=e=>{earningsRepId=e.target.value;renderEarnings()};['earnCurrent','earnExtra','earnBase','earnBonus','earnReimburse','earnOwnCosts','earnDeduct','earnDays','earnAvgOrder','earnTargetRevenue','earnTargetCommission','earnTargetPayout'].forEach(id=>{const el=$('#'+id);if(el)el.oninput=calculateEarnings});calculateEarnings()}
function calculateEarnings(){const val=id=>Number($('#'+id)?.value||0),current=Math.max(0,val('earnCurrent')),extra=Math.max(0,val('earnExtra')),projected=current+extra,base=Math.max(0,val('earnBase')),bonus=Math.max(0,val('earnBonus')),reimburse=Math.max(0,val('earnReimburse')),ownCosts=Math.max(0,val('earnOwnCosts')),deduct=Math.min(80,Math.max(0,val('earnDeduct')))/100,days=Math.max(1,val('earnDays')||1),avg=Math.max(1,val('earnAvgOrder')||1),targetRevenue=Math.max(0,val('earnTargetRevenue')),targetCommission=Math.max(0,val('earnTargetCommission')),targetPayout=Math.max(0,val('earnTargetPayout'));const tier=earningsTier(projected),commission=earningsCommission(projected),currentCommission=earningsCommission(current),taxableGross=base+bonus+commission,estimatedPayout=Math.max(0,taxableGross*(1-deduct)+reimburse-ownCosts),yearGross=taxableGross*12,yearPayout=estimatedPayout*12;const next=[10000,20000,30000,50000,75000].find(x=>projected<x)||null,nextGap=next?next-projected:0,targetGap=Math.max(0,targetRevenue-current),daily=targetGap/days,orders=Math.ceil(targetGap/avg),revForCommission=revenueForCommission(targetCommission);const neededTaxable=deduct>=.999?Infinity:Math.max(0,(targetPayout-reimburse+ownCosts)/(1-deduct)),neededCommission=Math.max(0,neededTaxable-base-bonus),revForPayout=Number.isFinite(neededTaxable)?revenueForCommission(neededCommission):Infinity;const result=$('#earnResult');if(result)result.innerHTML=`<div class="earnMetricGrid"><article><small>Prognose Nettoumsatz</small><strong>${money(projected)}</strong><span>${money(extra)} zusätzlich geplant</span></article><article class="accent"><small>Provisionsstufe</small><strong>${tier.label}</strong><span>${money(commission)} Provision</span></article><article><small>Mehr-Provision ggü. heute</small><strong>${money(Math.max(0,commission-currentCommission))}</strong><span>bei Erreichen der Planung</span></article><article><small>Brutto-Verdienst geplant</small><strong>${money(taxableGross)}</strong><span>Fixum + Bonus + Provision</span></article><article class="green"><small>Auszahlung grob geplant</small><strong>${money(estimatedPayout)}</strong><span>nach ${Math.round(deduct*100)} % Plan-Abzug + Erstattung − Eigenkosten</span></article><article><small>Jahreshochrechnung</small><strong>${money(yearGross)}</strong><span>brutto · Auszahlung ca. ${money(yearPayout)}</span></article></div>${next?`<div class="earnProgress"><div><b>Nächste Stufe: ${money(next)}</b><span>Noch ${money(nextGap)}</span></div><progress max="${next}" value="${Math.min(projected,next)}"></progress></div>`:`<div class="moduleNotice goodNotice"><b>Spitzenstufe erreicht:</b> Umsatz oberhalb von 75.000 € wird mit 20 % vergütet.</div>`}<div class="earnGoalGrid"><div><b>Umsatzziel ${money(targetRevenue)}</b><span>Noch ${money(targetGap)} · ${money(daily)} je Verkaufstag · ca. ${orders} Auftrag/Aufträge bei Ø ${money(avg)}</span></div><div><b>Wunsch-Provision ${money(targetCommission)}</b><span>Mindestens ca. ${money(revForCommission)} provisionsfähiger Nettoumsatz erforderlich.</span></div><div><b>Wunschauszahlung ca. ${money(targetPayout)}</b><span>${Number.isFinite(revForPayout)?`Ca. ${money(revForPayout)} Nettoumsatz nötig – unter deinen eingegebenen Planannahmen.`:'Mit 100 % Plan-Abzug nicht berechenbar.'}</span></div></div>`;const scenarios=$('#earnScenarios');if(scenarios){const targets=[10000,20000,30000,50000,75000,100000];scenarios.innerHTML=`<div class="tableWrap"><table class="dataTable earningsTable"><thead><tr><th>Nettoumsatz</th><th>Stufe</th><th>Provision</th><th>Brutto inkl. Fixum/Bonus</th><th>Auszahlung grob</th><th>Ø Tagesumsatz (${days} Tage)</th></tr></thead><tbody>${targets.map(n=>{const t=earningsTier(n),c=earningsCommission(n),gross=base+bonus+c,pay=Math.max(0,gross*(1-deduct)+reimburse-ownCosts);return `<tr class="${projected>=n?'reached':''}"><td><b>${money(n)}</b></td><td>${t.label}</td><td class="money"><b>${money(c)}</b></td><td class="money">${money(gross)}</td><td class="money">${money(pay)}</td><td class="money">${money(n/days)}</td></tr>`}).join('')}</tbody></table></div>`}}

function renderMyStats(){if(!can('view_own_stats'))return setView('dashboard');ws.innerHTML=salesStatsPanel(state.my_sales_stats||{},'Meine Verkaufs- & Provisionsstatistik')}
function repStatsModal(id){const r=(state.sales_reps||[]).find(x=>x.id===id);if(!r)return;openModal(`<div class="modalHead"><small>KUNDENBERATER · PROVISIONSABRECHNUNG</small><h2>${esc(r.name)}</h2><p>${esc(r.employee_no)} · ${esc(r.territory||'kein Gebiet')}</p></div><div class="modalBody">${salesStatsPanel(r.stats_current||{},'Aktueller Monat')}</div>`)}

