  const re=()=>renderProduction();$('#productionTableView').onclick=()=>{productionViewMode='table';re()};$('#productionBoardView').onclick=()=>{productionViewMode='board';re()};$('#productionSearch').oninput=e=>{productionSearchTerm=e.target.value;re();setTimeout(()=>$('#productionSearch')?.focus(),0)};$('#productionSearchClear').onclick=()=>{productionSearchTerm='';re()};$('#productionPriorityFilter').onchange=e=>{productionPriorityFilter=e.target.value;re()};$('#productionStationFilter').onchange=e=>{productionStationFilter=e.target.value;re()};$('#productionDueFilter').onchange=e=>{productionDueFilter=e.target.value;re()};$('#productionSort').onchange=e=>{productionSortMode=e.target.value;re()};$('#productionPrintList').onclick=()=>printProductionList(rows);$$('[data-production-phase]').forEach(b=>b.onclick=()=>{productionPhaseFilter=b.dataset.productionPhase;productionStepFilter='all';re()});$$('[data-step-filter]').forEach(b=>b.onclick=()=>{const key=b.dataset.stepFilter;productionStepFilter=productionStepFilter===key?'all':key;productionPhaseFilter='all';productionViewMode='table';re()});$$('[data-production-start]').forEach(b=>b.onclick=()=>productionStartWork(b.dataset.productionStart));$$('[data-production-edit]').forEach(b=>b.onclick=()=>productionEditModal(b.dataset.productionEdit));$$('[data-production-next]').forEach(b=>b.onclick=()=>productionNextStep(b.dataset.productionNext));$$('[data-production-print]').forEach(b=>b.onclick=()=>printProductionTicket(b.dataset.productionPrint));
