async function productionStartWork(id){if(!can('edit_production'))return toast('Keine Berechtigung.',true);const o=(state.orders||[]).find(x=>(x.order_no||x.id)===id);if(!o)return;if(o.payment_status!=='paid')return toast('Arbeit kann erst nach bestätigtem Zahlungseingang begonnen werden.',true);try{await api({action:'production_update',id,priority:o.production_priority||'normal',due_at:o.production_due_at||'',station:o.production_station||'Materiallager',step:'material',progress:15,assignee_user_id:o.production_assignee_user_id||(state.current_user?.role==='production'?state.current_user.id:''),note:o.production_note||''});toast('Arbeit begonnen · Kunde sieht jetzt 15 % Fortschritt');await load(true);if(current==='production')renderProduction()}catch(e){toast(e.message,true)}}
function dateTimeLocalValue(v){if(!v)return'';const d=new Date(v);if(Number.isNaN(d.getTime()))return'';const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function productionEditModal(id){if(!can('edit_production'))return toast('Keine Berechtigung zur Produktionssteuerung.',true);const o=(state.orders||[]).find(x=>(x.order_no||x.id)===id);if(!o)return;const progress=prodProgress(o),isProd=state.current_user?.role==='production',assigneeCurrent=o.production_assignee_user_id||(isProd?state.current_user.id:'');openModal(`<div class="modalHead productionModalHead"><small>PRODUKTIONSSTEUERUNG · ${esc(id)}</small><h2>${esc(orderCustomer(o))}</h2><p>${productionItemSummary(o).replace(/<[^>]*>/g,' · ')}</p></div><div class="modalBody"><div class="productionIdentityBar"><div><small>VERANTWORTLICH</small><b>${esc(productionUserName(assigneeCurrent,o.production_assignee))}</b></div><div><small>ZULETZT AUSGEFÜHRT VON</small><b>${esc(productionLastWorker(o))}</b><span>${o.production_last_work_at?dt(o.production_last_work_at):'Noch kein Schritt protokolliert'}</span></div></div><div class="productionEditGrid"><label>Priorität<select id="prodPriority">${Object.entries(productionPriorities).map(([k,v])=>`<option value="${k}" ${sel(o.production_priority||'normal',k)}>${v[0]}</option>`).join('')}</select></label><label>Fertigstellung<input id="prodDue" type="datetime-local" value="${dateTimeLocalValue(o.production_due_at)}"></label><label>Arbeitsplatz / Station<select id="prodStation"><option value="">Noch nicht zugewiesen</option>${productionStations.map(x=>`<option ${sel(o.production_station,x)}>${esc(x)}</option>`).join('')}</select></label><label>Produktionsschritt<select id="prodStep">${productionSteps.map(([k,l])=>`<option value="${k}" ${sel(o.production_step||'planung',k)}>${l}</option>`).join('')}</select></label><label>Produktionsmitarbeiter<select id="prodAssignee" ${isProd?'disabled':''}>${productionAssigneeOptions(assigneeCurrent)}</select></label><label>Fortschritt<input id="prodProgress" type="number" min="0" max="100" step="5" value="${progress}"></label><label class="full">Interne Produktionsnotiz<textarea id="prodNote" placeholder="Material, Besonderheiten, Rückfragen, Qualitätsanforderungen …">${esc(o.production_note||'')}</textarea></label></div><div class="productionStepTimeline">${productionSteps.map(([k,l,p])=>`<button type="button" data-modal-step="${k}" class="${productionSteps.findIndex(x=>x[0]===k)<=productionSteps.findIndex(x=>x[0]===(o.production_step||'planung'))?'done':''}"><i></i><span>${l}</span><small>${p}%</small></button>`).join('')}</div><div class="moduleNotice"><b>Automatischer Ausführungsnachweis:</b> Beim Speichern eines geänderten Arbeitsschritts wird das aktuell eingeloggte Produktionskonto mit Zeitpunkt protokolliert. Administratorische Planung bleibt davon getrennt.</div><div class="formActions"><button class="btn" id="prodOpenOrder">Auftrag öffnen</button><button class="btn" id="prodPrint">⎙ Produktionszettel</button><button class="btn primary" id="prodSave">Produktion speichern</button></div></div>`);$$('[data-modal-step]').forEach(b=>b.onclick=()=>{const m=prodStepMeta(b.dataset.modalStep);$('#prodStep').value=m[0];$('#prodProgress').value=m[2]});$('#prodOpenOrder').onclick=()=>{closeModal();openOrder(id)};$('#prodPrint').onclick=()=>printProductionTicket(id);$('#prodSave').onclick=async()=>{try{await api({action:'production_update',id,priority:$('#prodPriority').value,due_at:$('#prodDue').value,station:$('#prodStation').value,step:$('#prodStep').value,progress:+$('#prodProgress').value,assignee_user_id:isProd?(assigneeCurrent||state.current_user.id):$('#prodAssignee').value,note:$('#prodNote').value});toast('Produktionsdaten + Ausführungsnachweis gespeichert');closeModal();await load(true);if(current==='production')renderProduction()}catch(e){toast(e.message,true)}}}
async function productionNextStep(id){if(!can('edit_production'))return toast('Keine Berechtigung.',true);const o=(state.orders||[]).find(x=>(x.order_no||x.id)===id);if(!o)return;let i=productionSteps.findIndex(x=>x[0]===(o.production_step||'planung'));i=Math.min(productionSteps.length-1,i+1);const next=productionSteps[i];try{await api({action:'production_update',id,priority:o.production_priority||'normal',due_at:o.production_due_at||'',station:o.production_station||'',step:next[0],progress:next[2],assignee_user_id:o.production_assignee_user_id||(state.current_user?.role==='production'?state.current_user.id:''),note:o.production_note||''});toast('Weiter: '+next[1]);await load(true);if(current==='production')renderProduction()}catch(e){toast(e.message,true)}}
function productionPrintHtml(o){const items=(o.items||[]).map(it=>`<tr><td>${esc(it.article_no||it.sku||it.id||'')}</td><td><b>${esc(it.name||it.id||'Artikel')}</b><br><small>${esc(Object.values(it.meta||{}).filter(Boolean).join(' · '))}</small></td><td>${Number(it.qty||1)}</td></tr>`).join('');return `<h1>Produktionszettel</h1><div class="facts"><span><small>Auftrag</small><b>${esc(o.order_no||o.id)}</b></span><span><small>Kunde</small><b>${esc(orderCustomer(o))}</b></span><span><small>Priorität</small><b>${esc(prodPriorityMeta(o.production_priority)[0])}</b></span><span><small>Fertig bis</small><b>${esc(prodDueMeta(o).label)}</b></span><span><small>Arbeitsplatz</small><b>${esc(o.production_station||'–')}</b></span><span><small>Verantwortlich</small><b>${esc(productionUserName(o.production_assignee_user_id,o.production_assignee))}</b></span><span><small>Letzte Ausführung</small><b>${esc(productionLastWorker(o))}</b></span></div><h2>${esc(prodStepMeta(o.production_step)[1])} · ${prodProgress(o)}%</h2><table><thead><tr><th>Art.-Nr.</th><th>Artikel</th><th>Menge</th></tr></thead><tbody>${items}</tbody></table><div class="note"><b>Produktionsnotiz</b><p>${esc(o.production_note||'Keine')}</p></div><div class="checks"><span>□ Material geprüft</span><span>□ Maß / Ausführung geprüft</span><span>□ Qualität geprüft</span><span>□ Verpackung geprüft</span></div>`}
