function renderAdministration(){if(!isAdmin())return setView('dashboard');const users=state.users||[],activity=state.activity||[],mails=state.mail_log||[];ws.innerHTML=`<div class="sectionHead"><div><h2>Administration</h2><p>Benutzer, E-Mail-Zugänge, Rollen und sämtliche protokollierten Änderungen kontrollieren.</p></div><div class="sectionActions"><button class="btn" id="openRightsCenter">Zugriffsrechte</button><button class="btn primary" id="newUser">+ Benutzer anlegen</button></div></div><div class="adminSummary">${metric('Administratoren',users.filter(u=>u.role==='admin'&&u.status==='active').length,'Vollzugriff')}${metric('Produktions-Logins',users.filter(u=>u.role==='production'&&u.status==='active').length,'Fertigung · kein Außendienst')}${metric('Außendienst-Logins',users.filter(u=>u.role==='field_sales'&&u.status==='active').length,'Vertrieb · Provision')}${metric('Protokolleinträge',activity.length,'letzte Aktivitäten')}</div><div class="adminColumns"><section class="panel"><div class="panelTitle"><h3>Benutzer & Zugänge</h3><span>klar getrennte Rollen</span></div><div class="tableWrap"><table class="dataTable"><thead><tr><th>Benutzer</th><th>Rolle</th><th>Zuordnung</th><th>Willkommensmail</th><th>Letzter Login</th><th>Status</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${esc(u.display_name)}</b><br><small>${esc(u.username)} · ${esc(u.email||'')}</small></td><td>${userRoleBadge(u.role)}</td><td>${u.role==='field_sales'?esc(repName(u.sales_rep_id)):u.role==='production'?'<b>Produktionsteam</b>':'–'}</td><td>${u.welcome_sent_at?dt(u.welcome_sent_at):'–'}</td><td>${dt(u.last_login)}</td><td>${u.status==='active'?'Aktiv':'Inaktiv'}</td><td><div class="rowActions"><button class="miniBtn" data-user="${esc(u.id)}">Bearbeiten</button>${u.role!=='admin'?`<button class="miniBtn" data-admin-rights="${esc(u.id)}">Rechte</button><button class="miniBtn" data-resend-welcome="${esc(u.id)}">Mail senden</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panelTitle"><h3>System-E-Mails</h3><span>Versandstatus</span></div><div class="auditList">${mails.slice(0,80).map(m=>`<article><time>${dt(m.created_at)}</time><div><b>${esc(m.recipient)}</b><span>${esc(m.mail_type)} · ${m.status==='sent'?'versendet':'FEHLER'} · ${esc(m.subject)}</span></div></article>`).join('')||'<div class="empty">Noch keine System-E-Mails.</div>'}</div></section><section class="panel adminWide"><div class="panelTitle"><h3>Änderungsprotokoll</h3><span>nachvollziehbar</span></div><div class="auditList">${activity.slice(0,150).map(a=>`<article><time>${dt(a.created_at)}</time><div><b>${esc(a.actor)}</b><span>${esc(a.action_name)} · ${esc(a.entity_type)} ${esc(a.entity_id)}</span></div></article>`).join('')||'<div class="empty">Noch keine Protokolleinträge.</div>'}</div></section></div>`;$('#newUser').onclick=()=>userModal(null);$('#openRightsCenter').onclick=()=>setView('rights');$$('[data-admin-rights]').forEach(b=>b.onclick=()=>rightsModal(b.dataset.adminRights));$$('[data-resend-welcome]').forEach(b=>b.onclick=async()=>{if(!confirm('Begrüßungs- und Einrichtungslink erneut per E-Mail senden?'))return;try{await api({action:'welcome_resend',id:b.dataset.resendWelcome});toast('Begrüßungsmail versendet');await load(true);renderAdministration()}catch(e){toast(e.message,true)}})}
function userModal(id,forcedRole=''){const u=(state.users||[]).find(x=>x.id===id)||{},reps=state.sales_reps||[],initialRole=forcedRole||u.role||'field_sales',perms=Array.isArray(u.permissions)?u.permissions:roleDefaultPerms(initialRole);openModal(`<div class="modalHead"><small>BENUTZER & RECHTE</small><h2>${id?'Benutzer bearbeiten':initialRole==='production'?'Produktionsmitarbeiter anlegen':'Benutzer anlegen'}</h2><p>${initialRole==='production'?'Eigenes Orgaboard-Konto für die Fertigung · keine Außendienst-Zuordnung.':''}</p></div><div class="modalBody"><div class="formGrid"><label>Benutzername<input id="usrName" value="${esc(u.username||'')}" placeholder="vorname.nachname"></label><label>Anzeigename<input id="usrDisplay" value="${esc(u.display_name||'')}"></label><label>E-Mail<input id="usrEmail" type="email" value="${esc(u.email||'')}"></label><label>Rolle<select id="usrRole"><option value="admin" ${sel(initialRole,'admin')}>Administrator · Vollzugriff</option><option value="production" ${sel(initialRole,'production')}>Produktion · Fertigung, kein Außendienst</option><option value="field_sales" ${sel(initialRole,'field_sales')}>Außendienst · Vertrieb & Provision</option></select></label><label class="full" id="usrRepLabel">Außendienst-Zuordnung<select id="usrRep"><option value="">Keine</option>${reps.map(r=>`<option value="${esc(r.id)}" ${sel(u.sales_rep_id||'',r.id)}>${esc(r.employee_no)} · ${esc(r.name)}</option>`).join('')}</select></label><label>Status<select id="usrStatus"><option value="active" ${sel(u.status||'active','active')}>Aktiv</option><option value="inactive" ${sel(u.status,'inactive')}>Inaktiv</option></select></label><label>Neues / temporäres Passwort<input id="usrPassword" type="password" minlength="12" placeholder="${id?'leer = unverändert':'mindestens 12 Zeichen'}"></label></div><div class="roleExplain" id="usrRoleExplain"></div><div class="formActions"><button class="btn" id="usrRights" ${id&&initialRole!=='admin'?'':'disabled'}>Detaillierte Rechte</button><button class="btn primary" id="saveUser">Benutzer speichern</button></div></div>`);const syncRole=()=>{const role=$('#usrRole').value,isField=role==='field_sales';$('#usrRep').disabled=!isField;$('#usrRepLabel').style.opacity=isField?'1':'.45';if(!isField)$('#usrRep').value='';$('#usrRoleExplain').innerHTML=role==='production'?'<b>Produktionsrolle</b><span>Produktion ansehen/bearbeiten, Lager ansehen und Nachrichten nutzen. Keine Kundendatenpflege, keine Zahlungen, keine Provision, kein Außendienst.</span>':role==='field_sales'?'<b>Außendienstrolle</b><span>Vertrieb, Kundendaten und persönliche Statistik. Produktions- und Administrationsrechte sind getrennt.</span>':'<b>Administrator</b><span>Vollzugriff auf alle Bereiche.</span>'};$('#usrRole').onchange=syncRole;syncRole();$('#usrRights').onclick=()=>{closeModal();rightsModal(u.id)};$('#saveUser').onclick=async()=>{try{const role=$('#usrRole').value;const sendPerms=id&&role===initialRole?perms:roleDefaultPerms(role);await api({action:'user_save',id:u.id||'',username:$('#usrName').value,display_name:$('#usrDisplay').value,email:$('#usrEmail').value,role,sales_rep_id:role==='field_sales'?$('#usrRep').value:'',status:$('#usrStatus').value,password:$('#usrPassword').value,permissions:sendPerms});toast(role==='production'?'Produktionsmitarbeiter gespeichert':'Benutzer gespeichert');closeModal();await load(true);if(current==='production_staff')renderProductionStaff();else renderAdministration()}catch(e){toast(e.message,true)}}}


/* V77 · Professionelles Rechnungstool */
function docTypeLabelV77(t){return t==='delivery_note'?'Lieferschein':t==='cancellation'?'Stornorechnung':'Rechnung'}
function docStatusPillV77(d){if(d.status==='issued')return '<span class="status s-paid">Ausgegeben</span>';if(d.status==='cancelled')return '<span class="status s-cancelled">Storniert</span>';return '<span class="status s-payment_pending">Entwurf</span>'}
function docEmailPillV77(d){if(d.email_status==='sent')return '<span class="invoiceMail sent">E-Mail versendet</span>';if(d.email_status==='failed')return '<span class="invoiceMail failed">E-Mail Fehler</span>';return '<span class="invoiceMail">noch nicht versendet</span>'}
function invoiceProfileReadyV77(){return Boolean(state?.invoice_readiness?.ready)}
function invoiceOrderByNoV77(no){return (state.orders||[]).find(o=>(o.order_no||o.id)===no)||null}
function invoiceDocumentRowsV77(){const q=(documentSearchTerm||'').toLowerCase().trim();return (state.documents||[]).filter(d=>{const c=d.payload?.customer||{},hay=`${d.document_no} ${d.order_no} ${docTypeLabelV77(d.document_type)} ${c.name||''} ${c.company||''} ${c.email||''}`.toLowerCase();if(q&&!hay.includes(q))return false;if(documentTypeFilter!=='all'&&d.document_type!==documentTypeFilter)return false;if(documentStatusFilter!=='all'&&d.status!==documentStatusFilter)return false;return true}).sort((a,b)=>new Date(b.created_at||0)-new Date(a.created_at||0))}
