async function emailDocumentsV77(orderNo){if(!confirm('Rechnung und Lieferschein jetzt erneut per E-Mail an den Kunden senden?'))return;try{toast('PDF-Dokumente werden versendet …');await api({action:'document_email',order_no:orderNo});toast('Rechnung und Lieferschein wurden per E-Mail versendet');await load(true);if(current==='documents')renderDocuments()}catch(e){toast(e.message,true)}}
async function documentGenerateMissingV77(){const targets=(state.orders||[]).filter(o=>o.status!=='cancelled'&&(!existingDocument(o.order_no||o.id,'invoice')||!existingDocument(o.order_no||o.id,'delivery_note')));if(!targets.length)return toast('Alle Bestellungen haben bereits Rechnung und Lieferschein.');if(!confirm(targets.length+' Bestellung(en): fehlende Rechnung/Lieferschein erzeugen?'))return;let done=0;for(const o of targets){try{await api({action:'document_bundle_generate',order_no:o.order_no||o.id,issue:false});done++}catch(e){}}toast(done+' Dokumentpaare erzeugt');await load(true);renderDocuments()}
