async function documentHistoryModalV77(id){try{const d=await api({action:'document_history',id});openModal(`<div class="modalHead"><small>DOKUMENTHISTORIE</small><h2>Änderungsverlauf</h2><p>Jede Entwurfsänderung bleibt nachvollziehbar.</p></div><div class="modalBody"><div class="auditList">${(d.versions||[]).map(v=>`<article><time>${dt(v.created_at)}</time><div><b>Version ${Number(v.version_no||1)}</b><span>${esc(v.change_note||'')} · ${esc(v.edited_by_name||'System')}</span></div></article>`).join('')||'<div class="empty">Keine Versionshistorie vorhanden.</div>'}</div></div>`)}catch(e){toast(e.message,true)}}
