function productNewActiveAdmin(p){if(!p?.is_new)return false;if(!p.new_until)return true;const t=new Date(String(p.new_until).slice(0,10)+'T23:59:59');return !Number.isNaN(+t)&&t>=new Date()}
function legacyRenderProductsV83_3(){const q=(productSearchTerm||searchTerm||'').toLowerCase().trim(),baseRows=(state.catalog||[]).filter(p=>!q||`${p.name} ${p.sku||''} ${p.article_no||''} ${p.barcode||''} ${p.category||''} ${p.id}`.toLowerCase().includes(q)),rows=sortProductsForView(baseRows),drafts=baseRows.filter(p=>p.status!=='active'||!p.shop_visible).length,newCount=baseRows.filter(productNewActiveAdmin).length;ws.innerHTML=`<div class="sectionHead"><div><h2>Artikel & Produkte</h2><p>Produkte sicher erstellen, prüfen, veröffentlichen und anschließend im bestehenden Shopdesign verwalten.</p></div><div class="sectionActions"><b class="muted tiny">${rows.length} Artikel</b>${isAdmin()?'<button class="btn" id="openProductAnalysis">↗ Produkt-Analyse</button>':''}${can('edit_products')?'<button class="btn primary productBuilderLaunch" id="newProduct">＋ Produkt-Baukasten</button>':''}</div></div><section class="productBuilderIntro"><div><small>PRODUKT-BAUKASTEN · V86</small><h3>Neuen Artikel Schritt für Schritt veröffentlichen</h3><p>Felder erklären sich per <b>?</b>-Hilfe. Entwurf und Veröffentlichung sind getrennt. Das Shopdesign ist geschützt und wird durch Produktdaten niemals verändert.</p></div><div class="productBuilderIntroStats"><article><b>${drafts}</b><span>Entwürfe / offline</span></article><article><b>${newCount}</b><span>Neu im Sortiment</span></article><article><b>6</b><span>klare Schritte</span></article></div></section>${productSearchToolbar(productSearchTerm)}${productSortToolbar()}<div class="moduleNotice"><b>Designschutz:</b> Der Baukasten schreibt ausschließlich Produktdaten in die Datenbank. Neue Artikel werden über das feste Räucherhaken24-Shoptemplate dargestellt; Navigation, Farben, Kopfbereich und Layout bleiben unverändert.</div>${rows.length?productsTable(rows):'<div class="panel"><div class="empty"><b>Keine Produkte gefunden</b>Suchbegriff oder Barcode prüfen.</div></div>'}`;if($('#newProduct'))$('#newProduct').onclick=()=>productModal(null);if($('#openProductAnalysis'))$('#openProductAnalysis').onclick=()=>setView('product_analysis');bindQuickProductControls();bindPromoQuickControls();bindProductSearch(renderProducts);bindProductSort(renderProducts);$$('[data-analysis-product]').forEach(b=>b.onclick=()=>isAdmin()?setView('product_analysis'):productModal(b.dataset.analysisProduct))}

