 ['prName','prArticle','prShortDescription','prBase','prUnit','prNew','prPopular','prOffer','prNewUntil','prSeoTitle','prSeoDescription','prDescription','prFeatures','prStock'].forEach(x=>$('#'+x)?.addEventListener('input',updatePreview));$('#prNew').onchange=updatePreview;$('#prPopular').onchange=updatePreview;$('#prOffer').onchange=updatePreview;$('#prNewCategory').oninput=updatePreview;
