function openCustomer(id){const c=(state.customers||[]).find(x=>x.id===id);if(!c)return;const st=customerOrderStats(c),addr=[c.street,c.zip,c.city,c.country].filter(Boolean).join(', '),ship=c.shipping||{},tags=c.tags||[];openModal(`<div class="modalHead crmDetailHead"><small>KUNDENAKTE · ${esc(c.id)}</small><h2>${esc(c.name||'Kunde')}</h2><p>${esc(c.company||customerTypeLabel(c.customer_type))}</p></div><div class="modalBody"><div class="crmDetailMetrics">${metric('Umsatz',money(st.gross),'gesamt')}${metric('Bestellungen',st.count,'zugeordnet')}${metric('Zahlungsziel',Number(c.payment_terms_days||7)+' Tage',esc(c.payment_method||'nicht festgelegt'))}${metric('Rabatt',Number(c.discount_percent||0).toLocaleString('de-DE')+' %','kundenspezifisch')}</div><div class="crmDetailGrid"><section class="panel panelPad"><h3>Kontakt</h3><p><b>${esc(c.salutation||'')} ${esc(c.name||'')}</b><br>${esc(c.company||'')}<br>${esc(c.email||'Keine E-Mail')}<br>${esc(c.phone||'')}${c.mobile?'<br>'+esc(c.mobile):''}${c.website?'<br>'+esc(c.website):''}</p><div>${tags.map(t=>`<span class="crmTag">${esc(t)}</span>`).join('')}</div></section><section class="panel panelPad"><h3>Rechnungsadresse</h3><p>${esc(c.street||'–')}<br>${esc(c.zip||'')} ${esc(c.city||'')}<br>${esc(c.country||'Deutschland')}</p>${addr?`<a class="btn" target="_blank" rel="noopener" href="${googleMapsSearchUrl(addr)}">Google Maps ↗</a>`:''}</section><section class="panel panelPad"><h3>Lieferadresse</h3><p>${ship.street?`${esc(ship.name||c.name)}<br>${esc(ship.street)}<br>${esc(ship.zip||'')} ${esc(ship.city||'')}<br>${esc(ship.country||'Deutschland')}`:'Wie Rechnungsadresse'}</p></section><section class="panel panelPad"><h3>Zahlung & Steuer</h3><p>Zahlart: <b>${esc(c.payment_method||'nicht festgelegt')}</b><br>Zahlungsziel: <b>${Number(c.payment_terms_days||7)} Tage</b><br>Rabatt: <b>${Number(c.discount_percent||0).toLocaleString('de-DE')} %</b>${c.vat_id?'<br>USt-IdNr.: <b>'+esc(c.vat_id)+'</b>':''}</p></section><section class="panel panelPad"><h3>Vertrieb</h3><p>Kundenberater: <b>${esc(customerOwnerName(c))}</b><br>Status: <b>${esc(customerStatusLabel(c.status))}</b><br>Quelle: <b>${esc(c.source||'–')}</b><br>Kontakt bevorzugt: <b>${esc(c.preferred_contact||'email')}</b></p></section><section class="panel panelPad"><h3>Datenschutz</h3><p>Newsletter: <b>${esc(c.newsletter_status||'none')}</b><br>${c.contact_verified_at?'Kontakt geprüft: <b>'+dt(c.contact_verified_at)+'</b>':'Kontakt noch nicht geprüft.'}</p></section></div><section class="panel panelPad"><div class="panelTitle"><h3>Bestellhistorie</h3><span>${st.count} Bestellung(en)</span></div>${st.orders.length?st.orders.slice(0,12).map(orderMini).join(''):'<div class="empty">Noch keine Bestellungen.</div>'}</section><section class="panel panelPad"><h3>Interne Notizen</h3><p>${esc(c.notes||'Keine Notiz vorhanden.').replace(/\n/g,'<br>')}</p>${c.payment_note?`<div class="moduleNotice"><b>Zahlung:</b> ${esc(c.payment_note)}</div>`:''}</section><div class="formActions">${can('edit_customers')?'<button class="btn" id="editCustomer">Bearbeiten</button>':''}${can('edit_appointments')?'<button class="btn" id="detailAppointment">Termin</button>':''}<button class="btn orange" id="adviseCustomer">Produktberatung</button>${can('create_orders')?'<button class="btn primary" id="orderCustomerBtn">+ Bestellung</button>':''}</div></div>`);if($('#editCustomer'))$('#editCustomer').onclick=()=>{closeModal();customerModal(id)};$('#adviseCustomer').onclick=()=>{salesCustomerId=id;closeModal();setView('sales')};if($('#orderCustomerBtn'))$('#orderCustomerBtn').onclick=()=>{closeModal();manualOrderModal(id,[],c.sales_rep_id||'')};if($('#detailAppointment'))$('#detailAppointment').onclick=()=>{closeModal();document.querySelector(`[data-customer-appointment="${CSS.escape(id)}"]`)?.click()}}
function paymentIntegration(id){return (state.payment_integrations||[]).find(x=>x.provider===id)||{provider:id,environment:'sandbox',enabled:false,checkout_enabled:false,configured:false,status:'not_configured',credentials:{},last_message:'Noch nicht eingerichtet'}}
function paymentStatusBadge(p){const cl=p.status==='ready'||p.status==='connected'?'good':p.status==='configured'?'watch':p.status==='incomplete'?'critical':'neutral';const l=p.status==='ready'?'Bereit':p.status==='configured'?'Konfiguriert':p.status==='incomplete'?'Unvollständig':'Nicht eingerichtet';return `<span class="warehouseTag ${cl}">${l}</span>`}
function renderPayments(){if(!isAdmin())return setView('dashboard');const catalog=state.payment_provider_catalog||{},ids=Object.keys(catalog),rows=ids.map(id=>paymentIntegration(id)),ready=rows.filter(p=>p.status==='ready').length,enabled=rows.filter(p=>p.enabled).length,checkout=rows.filter(p=>p.checkout_enabled).length;ws.innerHTML=`<div class="sectionHead"><div><h2>Zahlungsarten & Schnittstellen</h2><p>Zentrale Einrichtung für PayPal, Klarna, Amazon Pay, Sparkasse/S-Payment, Karten, Wallets und klassische Zahlungsarten.</p></div><div class="sectionActions"><button class="btn" id="paymentHelpAll">Einrichtungs-Hilfe</button></div></div><div class="paymentHero">${metric('Anbieter',ids.length,'vorbereitet')}${metric('Konfiguriert',rows.filter(p=>p.configured).length,'Zugangsdaten vorhanden')}${metric('Bereit geprüft',ready,'Konfiguration vollständig')}${metric('Aktiv',enabled,'intern aktiviert')}${metric('Checkout-Freigabe',checkout,'vorgemerkt')}</div><div class="paymentWarning"><b>Keine Scheinaktivierung:</b><span>Ein grüner Status bestätigt die Vollständigkeit der gespeicherten Konfiguration. Für echte Zahlungen muss der jeweilige Anbieter zusätzlich im Sandbox-Checkout inklusive Rückleitung, Webhook, Capture und Erstattung End-to-End getestet werden.</span></div><div class="paymentProviderGrid">${ids.map(id=>{const m=catalog[id],p=paymentIntegration(id);return `<article class="paymentProviderCard ${p.enabled?'enabled':''}"><div class="paymentProviderTop"><div class="paymentLogo">${esc((m.label||id).slice(0,2).toUpperCase())}</div><div><small>${esc(m.group||'Payment')}</small><h3>${esc(m.label||id)}</h3></div>${paymentStatusBadge(p)}</div><p>${esc(m.description||'')}</p><div class="paymentMeta"><span>Umgebung <b>${p.environment==='production'?'Produktion':'Sandbox'}</b></span><span>Aktiv <b>${p.enabled?'Ja':'Nein'}</b></span><span>Checkout <b>${p.checkout_enabled?'vorgemerkt':'Nein'}</b></span></div><small class="paymentMessage">${esc(p.last_message||'Noch nicht eingerichtet')}</small><div class="formActions"><button class="miniBtn" data-pay-help="${esc(id)}">Hilfe</button><button class="miniBtn" data-pay-test="${esc(id)}">Prüfen</button><button class="btn primary" data-pay-config="${esc(id)}">Einrichten</button></div></article>`}).join('')}</div><div class="paymentArchitecture"><section><b>Empfohlene Grundabdeckung für Deutschland</b><span>PayPal + Karten/Wallets + Klarna/Rechnung + Vorkasse/SEPA. Sparkasse E-Payment kann Wero und weitere Zahlarten bündeln.</span></section><section><b>Wallets</b><span>Apple Pay und Google Pay professionell über einen unterstützten Zahlungsprozessor wie PayPal oder Stripe anbinden, statt Kartendaten selbst zu verarbeiten.</span></section><section><b>Sicherheit</b><span>Secrets bleiben verschlüsselt auf dem Server. Im Browser werden nur „gespeichert“-Marker angezeigt, niemals der Klartext.</span></section></div>`;$$('[data-pay-config]').forEach(b=>b.onclick=()=>paymentConfigModal(b.dataset.payConfig));$$('[data-pay-help]').forEach(b=>b.onclick=()=>paymentHelpModal(b.dataset.payHelp));$$('[data-pay-test]').forEach(b=>b.onclick=()=>paymentTest(b.dataset.payTest));$('#paymentHelpAll').onclick=()=>paymentHelpModal('overview')}
function paymentConfigModal(id){const catalog=state.payment_provider_catalog||{},m=catalog[id],p=paymentIntegration(id);if(!m)return;const stored=k=>p.credentials?.[k]?'gespeichert – leer lassen zum Beibehalten':'';openModal(`<div class="modalHead paymentModalHead"><small>PAYMENT CENTER · ${esc(m.group||'')}</small><h2>${esc(m.label)}</h2><p>${esc(m.description||'')}</p></div><div class="modalBody"><div class="paymentSetupGuide"><b>Einrichtung</b><span>${esc(m.help||'Zugangsdaten des Zahlungsanbieters eintragen und zunächst im Testmodus prüfen.')}</span></div><div class="formGrid"><label>Umgebung<select id="payEnv"><option value="sandbox" ${sel(p.environment||'sandbox','sandbox')}>Sandbox / Test</option><option value="production" ${sel(p.environment,'production')}>Produktion / Live</option></select></label><label>Status<input value="${esc(p.status||'not_configured')}" disabled></label>${(m.fields||[]).map(([key,label,type])=>`<label class="${key==='private_key'?'full':''}">${esc(label)}${key==='private_key'?`<textarea id="pay-${esc(key)}" placeholder="${esc(stored(key))}"></textarea>`:`<input id="pay-${esc(key)}" type="${type==='password'?'password':'text'}" placeholder="${esc(stored(key))}">`}</label>`).join('')}</div><div class="paymentSwitches"><label><input id="payEnabled" type="checkbox" ${p.enabled?'checked':''}><span><b>Anbieter intern aktivieren</b><small>Zeigt an, dass dieser Anbieter organisatorisch genutzt werden soll.</small></span></label><label><input id="payCheckout" type="checkbox" ${p.checkout_enabled?'checked':''}><span><b>Checkout-Freigabe vormerken</b><small>Erst nach erfolgreichem Sandbox-End-to-End-Test auf Live stellen.</small></span></label></div><div class="moduleNotice"><b>Sicherheit:</b> Zugangsdaten werden verschlüsselt gespeichert. Leere Felder überschreiben bereits gespeicherte Secrets nicht.</div><div class="formActions"><button class="btn" id="payHelpHere">Schritt-für-Schritt Hilfe</button><button class="btn" id="payCancel">Abbrechen</button><button class="btn primary" id="paySave">Speichern</button></div></div>`);$('#payCancel').onclick=closeModal;$('#payHelpHere').onclick=()=>paymentHelpModal(id,true);$('#paySave').onclick=async()=>{const credentials={};(m.fields||[]).forEach(([key])=>credentials[key]=$('#pay-'+CSS.escape(key)).value);try{const d=await api({action:'payment_integration_save',provider:id,environment:$('#payEnv').value,enabled:$('#payEnabled').checked,checkout_enabled:$('#payCheckout').checked,credentials});state.payment_integrations=d.integrations||state.payment_integrations;toast('Zahlungsschnittstelle gespeichert');closeModal();renderPayments()}catch(e){toast(e.message,true)}}}
function paymentHelpModal(id,back=false){const catalog=state.payment_provider_catalog||{};if(id==='overview'){openModal(`<div class="modalHead"><small>PAYMENT-HILFECENTER</small><h2>So richtest du Zahlungen professionell ein</h2></div><div class="modalBody"><div class="helpSteps"><article><b>1 · Vertrag / Händlerkonto</b><span>Beim gewünschten Anbieter ein Händlerkonto bzw. Payment-Paket freischalten.</span></article><article><b>2 · Sandbox-Zugang</b><span>Test-Zugangsdaten im Orgaboard hinterlegen. Niemals direkt mit Live-Schlüsseln beginnen.</span></article><article><b>3 · Rückleitung & Webhook</b><span>Zahlungsstatus muss serverseitig bestätigt werden; Browser-Rückleitungen allein reichen nicht.</span></article><article><b>4 · Testkauf</b><span>Erfolgreiche Zahlung, Abbruch, Erstattung und Doppelaufruf testen.</span></article><article><b>5 · Produktion</b><span>Erst danach Live-Zugangsdaten hinterlegen und Checkout freigeben.</span></article></div><div class="moduleNotice"><b>Empfehlung:</b> Kreditkartendaten niemals selbst speichern. Nutze zertifizierte Zahlungsanbieter und deren gehostete/SDK-basierte Zahlkomponenten.</div></div>`);return}const m=catalog[id];if(!m)return;openModal(`<div class="modalHead"><small>HILFE · ${esc(m.group||'PAYMENT')}</small><h2>${esc(m.label)}</h2></div><div class="modalBody"><div class="paymentHelpHero"><b>${esc(m.description||'')}</b><span>${esc(m.help||'')}</span></div><div class="helpSteps"><article><b>1 · Zugang beschaffen</b><span>Händlerkonto/Paket beim Anbieter freischalten und Testzugang erzeugen.</span></article><article><b>2 · Daten eintragen</b><span>Die im Einrichtungsformular verlangten Kennungen bzw. Secrets aus dem Anbieterportal übernehmen.</span></article><article><b>3 · Konfiguration prüfen</b><span>Im Payment Center „Prüfen“ ausführen. Fehlende Pflichtfelder werden konkret genannt.</span></article><article><b>4 · Sandbox-End-to-End</b><span>Vor Livebetrieb echte Testbestellung inklusive Webhook, Statuswechsel und Erstattung durchführen.</span></article></div><div class="formActions"><button class="btn primary" id="payHelpConfigure">Einrichtung öffnen</button></div></div>`);$('#payHelpConfigure').onclick=()=>paymentConfigModal(id)}
async function paymentTest(id){try{const d=await api({action:'payment_integration_test',provider:id});state.payment_integrations=d.integrations||state.payment_integrations;toast(d.message||'Konfiguration geprüft');if(current==='payments')renderPayments()}catch(e){toast(e.message,true);await load(true);if(current==='payments')renderPayments()}}

// --- V91 FINANZEN & BUCHHALTUNG -------------------------------------------------
const fToday=()=>new Date().toISOString().slice(0,10), fMonth=()=>new Date().toISOString().slice(0,7);
const fNum=v=>Number(v||0), fDate=v=>v?new Date(String(v).slice(0,10)+'T00:00:00').toLocaleDateString('de-DE'):'–';
const fStatus=(s)=>({open:'Offen',paid:'Bezahlt',partial:'Teilbezahlt',unassigned:'Nicht zugeordnet',matched:'Zugeordnet',cancelled:'Storniert',closed:'Abgeschlossen'}[s]||s||'–');
const fSearchRows=rows=>{const q=financeSearch.trim().toLowerCase();return q?rows.filter(r=>JSON.stringify(r).toLowerCase().includes(q)):rows};
function fMetric(label,value,sub='',tone=''){return `<article class="fMetric ${tone}"><small>${esc(label)}</small><b>${typeof value==='number'?money(value):esc(value)}</b><span>${esc(sub)}</span></article>`}
async function financeLoad(force=false){if(financeState&&!force)return financeState;ws.innerHTML='<div class="financeLoading"><b>Finanzdaten werden geladen …</b><span>Buchhaltung, Banking und Auswertungen werden abgeglichen.</span></div>';let r;try{r=await fetch('./finance-api.php?release=91.1',{credentials:'same-origin',cache:'no-store',headers:{'Accept':'application/json'}})}catch(e){throw new Error('Finanz-API ist vom Browser nicht erreichbar. Verbindung/Server prüfen.')}const raw=await r.text();let d={};try{d=JSON.parse(raw)}catch(e){}if(!r.ok||!d.ok){if(d.error)throw new Error(d.error);if(r.status===404)throw new Error('finance-api.php wurde auf dem Server nicht gefunden. V91.1-Dateien vollständig hochladen.');throw new Error(`Finanz-API antwortet fehlerhaft (HTTP ${r.status}). V91.1-Systemdiagnose öffnen.`)}financeState=d.finance;return financeState}
async function financePost(payload){const r=await fetch('./finance-api.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf||document.querySelector('.appFrame')?.dataset.csrf||''},body:JSON.stringify(payload)});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.error||'Finanzaktion fehlgeschlagen.');financeState=d.finance;return d}
function financeRefresh(){financeState=null;return renderFinance()}
function fOption(rows,val='id',label='name',selected=''){return rows.map(x=>`<option value="${esc(x[val]??'')}" ${sel(x[val],selected)}>${esc(typeof label==='function'?label(x):x[label]??'')}</option>`).join('')}
function financeTabs(){const tabs=[['cockpit','Cockpit'],['receipts','Belege'],['banking','Banking'],['cash','Kasse'],['opos','OPOS & Mahnwesen'],['suppliers','Lieferanten'],['assets','Anlagen & Konten'],['planning','Planung'],['tax','Steuern & DATEV'],['closing','Abschluss']];return `<div class="financeTabs">${tabs.map(([id,l])=>`<button class="${financeTab===id?'active':''}" data-ftab="${id}">${l}</button>`).join('')}</div>`}
function financeHeader(f){return `<div class="financeTop"><div><div class="financeEyebrow">FINANZ-CONTROL-CENTER · V91.1</div><h2>Finanzen & Buchhaltung</h2><p>Belege, Zahlungsverkehr, offene Posten, Kasse, Planung und Steuerberater-Export in einem Arbeitsbereich.</p></div><div class="financeTopActions"><button class="btn" id="financeRefresh">↻ Aktualisieren</button>${can('edit_finance')?'<button class="btn primary" id="financeQuickExpense">+ Eingangsbeleg</button>':''}</div></div><div class="financeGuard"><b>Änderungsschutz aktiv</b><span>Abgeschlossene Perioden werden gesperrt. Stornos, Wiederöffnungen und Finanzänderungen landen im Audit-Protokoll.</span><em>${esc(f.config?.framework||'SKR03')} · ${esc(f.config?.accounting_method||'EÜR')} · USt ${esc(f.config?.vat_mode||'Soll')}</em></div>`}
function renderFinance(){financeLoad().then(f=>{if(current!=='finance')return;const renderers={cockpit:fRenderCockpit,receipts:fRenderReceipts,banking:fRenderBanking,cash:fRenderCash,opos:fRenderOpos,suppliers:fRenderSuppliers,assets:fRenderAssets,planning:fRenderPlanning,tax:fRenderTax,closing:fRenderClosing};ws.innerHTML=financeHeader(f)+financeTabs()+`<div class="financeWorkspace">${(renderers[financeTab]||fRenderCockpit)(f)}</div>`;fBindCommon(f)}).catch(e=>{ws.innerHTML=`<div class="empty financeError"><b>Finanzmodul konnte nicht geöffnet werden.</b>${esc(e.message)}<div class="sectionActions"><button class="btn primary" id="financeRetry">Erneut versuchen</button><a class="btn" href="diagnose.php?v=91.1" target="_blank" rel="noopener">Systemdiagnose</a></div></div>`;$('#financeRetry')?.addEventListener('click',financeRefresh)})}
function fBindCommon(f){$$('[data-ftab]').forEach(b=>b.onclick=()=>{financeTab=b.dataset.ftab;renderFinance()});$('#financeRefresh')?.addEventListener('click',financeRefresh);$('#financeQuickExpense')?.addEventListener('click',()=>fExpenseModal());const search=$('#financeSearch');if(search)search.oninput=e=>{financeSearch=e.target.value;renderFinance()};$$('[data-fexpense]').forEach(b=>b.onclick=()=>fExpenseModal((f.expenses||[]).find(x=>x.id===b.dataset.fexpense)));$$('[data-fsupplier]').forEach(b=>b.onclick=()=>fSupplierModal((f.suppliers||[]).find(x=>x.id===b.dataset.fsupplier)));$$('[data-fasset]').forEach(b=>b.onclick=()=>fAssetModal((f.assets||[]).find(x=>x.id===b.dataset.fasset)));$$('[data-ftx]').forEach(b=>b.onclick=()=>fTransactionModal((f.transactions||[]).find(x=>x.id===b.dataset.ftx)));$$('[data-fbank]').forEach(b=>b.onclick=()=>fBankAccountModal((f.bank_accounts||[]).find(x=>x.id===b.dataset.fbank)));$$('[data-frecurring]').forEach(b=>b.onclick=()=>fRecurringModal((f.recurring||[]).find(x=>x.id===b.dataset.frecurring)));$$('[data-fbudget]').forEach(b=>b.onclick=()=>fBudgetModal((f.budgets||[]).find(x=>x.id===b.dataset.fbudget)));$$('[data-fdun]').forEach(b=>b.onclick=()=>fDunningModal((f.open_receivables||[]).find(x=>x.order_no===b.dataset.fdun)));$$('[data-fperiod]').forEach(b=>b.onclick=()=>fPeriodModal(b.dataset.fperiod,(f.closings||[]).find(x=>x.period===b.dataset.fperiod)));$('#fNewSupplier')?.addEventListener('click',()=>fSupplierModal());$('#fNewExpense')?.addEventListener('click',()=>fExpenseModal());$('#fNewTx')?.addEventListener('click',()=>fTransactionModal());$('#fNewCash')?.addEventListener('click',()=>fCashModal());$('#fNewAsset')?.addEventListener('click',()=>fAssetModal());$('#fNewAccount')?.addEventListener('click',()=>fAccountModal());$('#fNewCC')?.addEventListener('click',()=>fCostCenterModal());$('#fNewRecurring')?.addEventListener('click',()=>fRecurringModal());$('#fNewBudget')?.addEventListener('click',()=>fBudgetModal());$('#fBankAccount')?.addEventListener('click',()=>fBankAccountModal());$('#fBankImport')?.addEventListener('click',()=>fBankImportModal());$('#fAutoMatch')?.addEventListener('click',async()=>{if(!confirm('Offene Zahlungseingänge automatisch mit eindeutigen Forderungen abgleichen?'))return;try{const d=await financePost({action:'auto_match'});toast(`${d.matched||0} Zahlung(en) zugeordnet`);renderFinance()}catch(e){toast(e.message,true)}});$('#fSettings')?.addEventListener('click',()=>fSettingsModal());$('#fClosePeriod')?.addEventListener('click',()=>fPeriodModal(fMonth()));}
function fSearchBar(ph='Suchen …'){return `<div class="financeSearch"><input id="financeSearch" type="search" value="${esc(financeSearch)}" placeholder="${esc(ph)}"><span>⌕</span></div>`}
function fRenderCockpit(f){const s=f.summary||{},liq=f.liquidity||[],min=fNum(f.config?.liquidity_min);const low=liq.some(x=>fNum(x.balance)<min);return `<div class="financeMetrics">${fMetric('Umsatz Monat',s.revenue_month,'bezahlt')}${fMetric('Kosten Monat',s.expense_month,'erfasste Eingangsbelege','cost')}${fMetric('Gewinn Monat',s.profit_month,'vor Ertragsteuern',s.profit_month<0?'danger':'good')}${fMetric('Liquidität',s.liquidity,'Bank + Kasse',s.liquidity<min?'danger':'good')}${fMetric('Offene Forderungen',s.open_receivables,`${s.overdue_receivables||0} überfällig`,s.overdue_receivables?'warn':'')}${fMetric('Offene Verbindlichkeiten',s.open_payables,`${s.overdue_payables||0} überfällig`,s.overdue_payables?'warn':'')}${fMetric('USt-Zahllast Monat',s.vat_due_month,'Plausibilitätswert')}${fMetric('Bankbestand',s.bank_balance,`${(f.bank_accounts||[]).length} Konto/Konten`)}</div><div class="financeGrid2"><section class="fPanel"><div class="fPanelHead"><div><small>13-WOCHEN-VORSCHAU</small><h3>Liquiditätsradar</h3></div><span class="fChip ${low?'danger':'good'}">${low?'Schwelle unterschritten':'im Zielkorridor'}</span></div><div class="liquidityBars">${liq.map(x=>{const max=Math.max(...liq.map(y=>Math.abs(fNum(y.balance))),1);const h=Math.max(7,Math.min(100,Math.abs(fNum(x.balance))/max*100));return `<div class="liqCol"><b>${money(x.balance)}</b><div class="liqBar ${x.balance<min?'danger':''}" style="height:${h}%"></div><small>${esc(x.label)}</small></div>`}).join('')}</div></section><section class="fPanel"><div class="fPanelHead"><div><small>ARBEITSLISTE</small><h3>Was jetzt Aufmerksamkeit braucht</h3></div></div><div class="fTaskList"><button data-ftab="opos"><b>${s.overdue_receivables||0}</b><span>überfällige Kundenforderungen</span><em>Öffnen →</em></button><button data-ftab="receipts"><b>${(f.expenses||[]).filter(x=>x.payment_status!=='paid'&&x.record_status==='active').length}</b><span>offene Lieferantenbelege</span><em>Öffnen →</em></button><button data-ftab="banking"><b>${(f.transactions||[]).filter(x=>x.status==='unassigned').length}</b><span>Bankumsätze nicht zugeordnet</span><em>Öffnen →</em></button><button data-ftab="closing"><b>${(f.closings||[]).filter(x=>x.status==='closed').length}</b><span>protokollierte Monatsabschlüsse</span><em>Öffnen →</em></button></div></section></div><div class="financeGrid2"><section class="fPanel"><div class="fPanelHead"><div><small>ZAHLUNGSMITTEL</small><h3>Konten & Kasse</h3></div></div><div class="accountCards">${(f.bank_accounts||[]).map(a=>`<article><small>${esc(a.bank_name||a.account_type||'Bank')}</small><b>${esc(a.name)}</b><strong>${money(a.balance)}</strong><span>${esc(a.iban||'IBAN nicht hinterlegt')}</span></article>`).join('')}<article><small>BARGELD</small><b>Kasse</b><strong>${money(s.cash_balance)}</strong><span>fortgeschriebener Bestand</span></article></div></section><section class="fPanel"><div class="fPanelHead"><div><small>STEUER-RADAR</small><h3>Umsatzsteuer Monat</h3></div></div><div class="vatStack"><div><span>Umsatzsteuer</span><b>${money(s.vat_output_month)}</b></div><div><span>Vorsteuer</span><b>− ${money(s.vat_input_month)}</b></div><div class="total"><span>Voraussichtliche Zahllast</span><b>${money(s.vat_due_month)}</b></div></div><p class="financeFineprint">Plausibilitätsauswertung aus den im Orgaboard erfassten Daten. Keine automatische Steueranmeldung.</p></section></div>`}
function fRenderReceipts(f){const rows=fSearchRows(f.expenses||[]);return `<div class="fSectionHead"><div><h3>Belegcenter & Eingangsrechnungen</h3><p>Lieferantenbelege erfassen, kontieren, Belegdatei hinterlegen und Zahlung überwachen.</p></div>${can('edit_finance')?'<button class="btn primary" id="fNewExpense">+ Beleg erfassen</button>':''}</div>${fSearchBar('Lieferant, Belegnummer, Kategorie, Projekt …')}<div class="fPanel tableWrap"><table class="dataTable financeTable"><thead><tr><th>Beleg</th><th>Lieferant</th><th>Datum / Fällig</th><th>Kontierung</th><th>Brutto</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(e=>`<tr class="${e.record_status==='cancelled'?'fCancelled':''}"><td><b>${esc(e.voucher_no)}</b><small>${esc(e.invoice_no||'ohne Rechnungsnr.')}</small>${e.receipt_available?'<span class="fDoc">Beleg ✓</span>':''}</td><td>${esc(e.supplier_name||'–')}</td><td>${fDate(e.invoice_date)}<small>fällig ${fDate(e.due_date)}</small></td><td>${esc(e.account_code||'–')} · ${esc(e.category||'ohne Kategorie')}<small>${esc(e.cost_center_code||'')} ${esc(e.project||'')}</small></td><td class="money">${money(e.gross_amount)}</td><td><span class="fChip ${e.payment_status==='paid'?'good':(e.due_date&&e.due_date<fToday()?'danger':'warn')}">${esc(e.record_status==='cancelled'?'Storniert':fStatus(e.payment_status))}</span></td><td><button class="miniBtn" data-fexpense="${esc(e.id)}">Öffnen</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty"><b>Keine Belege vorhanden</b>Erfasse den ersten Eingangsbeleg.</div></td></tr>'}</tbody></table></div>`}
function fRenderBanking(f){const rows=fSearchRows(f.transactions||[]);return `<div class="fSectionHead"><div><h3>Banking & Zahlungsabgleich</h3><p>Kontoumsätze importieren, manuell erfassen und automatisch mit Bestellungen abgleichen.</p></div><div class="sectionActions">${can('edit_finance')?'<button class="btn" id="fBankAccount">Bankkonto</button><button class="btn" id="fBankImport">CSV importieren</button><button class="btn" id="fAutoMatch">Auto-Zuordnung</button><button class="btn primary" id="fNewTx">+ Umsatz</button>':''}</div></div><div class="accountCards financeBankCards">${(f.bank_accounts||[]).map(a=>`<article><small>${esc(a.bank_name||'ZAHLUNGSKONTO')}</small><b>${esc(a.name)}</b><strong>${money(a.balance)}</strong><span>${esc(a.iban||'keine IBAN')}</span>${can('edit_finance')?`<button class="miniBtn" data-fbank="${esc(a.id)}">Bearbeiten</button>`:''}</article>`).join('')}</div>${fSearchBar('Betrag, Gegenpartei, IBAN, Verwendungszweck, Bestellung …')}<div class="fPanel tableWrap"><table class="dataTable financeTable"><thead><tr><th>Datum</th><th>Gegenpartei / Zweck</th><th>Konto</th><th>Betrag</th><th>Zuordnung</th><th></th></tr></thead><tbody>${rows.map(t=>`<tr><td>${fDate(t.booking_date)}<small>${esc(t.source||'')}</small></td><td><b>${esc(t.counterparty||'–')}</b><small>${esc(t.purpose||t.reference||'')}</small></td><td>${esc(t.bank_account_name||'–')}</td><td class="money ${t.amount>=0?'fPlus':'fMinus'}">${money(t.amount)}</td><td><span class="fChip ${t.status==='matched'?'good':'warn'}">${esc(fStatus(t.status))}</span>${t.order_no?`<small>${esc(t.order_no)}</small>`:''}</td><td><button class="miniBtn" data-ftx="${esc(t.id)}">Öffnen</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><b>Keine Kontoumsätze</b>CSV importieren oder Umsatz manuell erfassen.</div></td></tr>'}</tbody></table></div>`}
function fRenderCash(f){let bal=fNum(f.config?.cash_opening_balance);const rows=(f.cash_entries||[]).slice().sort((a,b)=>String(a.entry_date).localeCompare(String(b.entry_date)));rows.forEach(x=>bal+=['income','deposit'].includes(x.entry_type)?fNum(x.amount):-fNum(x.amount));const display=fSearchRows((f.cash_entries||[]));return `<div class="fSectionHead"><div><h3>Kassenbuch</h3><p>Fortlaufende, nicht still überschreibbare Bargeldbewegungen mit Belegnummer und Kontierung.</p></div>${can('edit_finance')?'<button class="btn primary" id="fNewCash">+ Kassenbewegung</button>':''}</div><div class="financeMetrics compact">${fMetric('Aktueller Kassenbestand',bal,'Anfangsbestand + Bewegungen')}${fMetric('Buchungen',display.length,'angezeigte Einträge')}</div>${fSearchBar('Buchungstext, Belegnummer, Konto …')}<div class="fPanel tableWrap"><table class="dataTable financeTable"><thead><tr><th>Nr.</th><th>Datum</th><th>Art</th><th>Buchungstext</th><th>Beleg</th><th>Betrag</th></tr></thead><tbody>${display.map(c=>`<tr><td><b>${esc(c.entry_no)}</b></td><td>${fDate(c.entry_date)}</td><td>${esc(({income:'Einnahme',expense:'Ausgabe',deposit:'Einlage',withdrawal:'Entnahme'}[c.entry_type]||c.entry_type))}</td><td>${esc(c.description)}<small>${esc(c.account_code||'')} ${esc(c.cost_center_code||'')}</small></td><td>${esc(c.receipt_no||'–')}</td><td class="money ${['income','deposit'].includes(c.entry_type)?'fPlus':'fMinus'}">${['income','deposit'].includes(c.entry_type)?'+ ':'− '}${money(c.amount)}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty"><b>Noch keine Kassenbewegung</b></div></td></tr>'}</tbody></table></div>`}
function fRenderOpos(f){const rec=fSearchRows(f.open_receivables||[]),pay=(f.expenses||[]).filter(e=>e.record_status==='active'&&e.payment_status!=='paid');return `<div class="fSectionHead"><div><h3>Offene Posten & Mahnwesen</h3><p>Kundenforderungen und Lieferantenverbindlichkeiten mit Fälligkeiten auf einen Blick.</p></div></div>${fSearchBar('Kunde, Bestellung, Rechnung …')}<div class="financeGrid2"><section class="fPanel"><div class="fPanelHead"><div><small>DEBITOREN</small><h3>Offene Forderungen</h3></div><b>${money(rec.reduce((a,x)=>a+fNum(x.gross)+fNum(x.dunning_fees),0))}</b></div><div class="fList">${rec.map(r=>`<button data-fdun="${esc(r.order_no)}"><span><b>${esc(r.customer_name||'Kunde')}</b><small>${esc(r.document_no||r.order_no)} · fällig ${fDate(r.due_date)}</small></span><strong>${money(fNum(r.gross)+fNum(r.dunning_fees))}</strong><em class="fChip ${r.is_overdue?'danger':'warn'}">${r.is_overdue?`${r.days_overdue} Tage überfällig`:'offen'}</em></button>`).join('')||'<div class="empty"><b>Keine offenen Forderungen</b></div>'}</div></section><section class="fPanel"><div class="fPanelHead"><div><small>KREDITOREN</small><h3>Offene Verbindlichkeiten</h3></div><b>${money(pay.reduce((a,x)=>a+fNum(x.gross_amount),0))}</b></div><div class="fList">${pay.map(e=>`<button data-fexpense="${esc(e.id)}"><span><b>${esc(e.supplier_name||'Lieferant')}</b><small>${esc(e.voucher_no)} · fällig ${fDate(e.due_date)}</small></span><strong>${money(e.gross_amount)}</strong><em class="fChip ${e.due_date&&e.due_date<fToday()?'danger':'warn'}">${e.due_date&&e.due_date<fToday()?'überfällig':'offen'}</em></button>`).join('')||'<div class="empty"><b>Keine offenen Verbindlichkeiten</b></div>'}</div></section></div>`}
function fRenderSuppliers(f){const rows=fSearchRows(f.suppliers||[]);return `<div class="fSectionHead"><div><h3>Lieferanten & Kreditorenstamm</h3><p>Zahlungsziele, Bankdaten und Kontaktdaten zentral verwalten.</p></div>${can('edit_finance')?'<button class="btn primary" id="fNewSupplier">+ Lieferant</button>':''}</div>${fSearchBar('Lieferant, Kontakt, IBAN, Ort …')}<div class="fCardGrid">${rows.map(s=>`<button class="supplierCard" data-fsupplier="${esc(s.id)}"><span class="fSupplierNo">${esc(s.supplier_no)}</span><b>${esc(s.name)}</b><small>${esc(s.contact_name||'kein Ansprechpartner')} · ${esc(s.city||'')}</small><em>${s.payment_terms_days||14} Tage Zahlungsziel</em><i class="fChip ${s.active?'good':'neutral'}">${s.active?'Aktiv':'Inaktiv'}</i></button>`).join('')||'<div class="empty"><b>Keine Lieferanten angelegt</b></div>'}</div>`}
function fRenderAssets(f){const fw=f.config?.framework||'SKR03',acc=(f.accounts||[]).filter(a=>a.framework===fw||a.framework==='EIGEN');return `<div class="fSectionHead"><div><h3>Anlagen, Konten & Kostenstellen</h3><p>Anlagevermögen, linearer Abschreibungsverlauf und Buchhaltungsstammdaten.</p></div><div class="sectionActions">${can('edit_finance')?'<button class="btn" id="fNewCC">+ Kostenstelle</button><button class="btn" id="fNewAccount">+ Konto</button><button class="btn primary" id="fNewAsset">+ Anlagegut</button>':''}</div></div><div class="financeGrid2"><section class="fPanel"><div class="fPanelHead"><div><small>ANLAGENVERZEICHNIS</small><h3>${(f.assets||[]).length} Anlagegüter</h3></div><b>${money((f.assets||[]).reduce((a,x)=>a+fNum(x.book_value),0))} Buchwert</b></div><div class="fList">${(f.assets||[]).map(a=>`<button data-fasset="${esc(a.id)}"><span><b>${esc(a.asset_no)} · ${esc(a.name)}</b><small>${fDate(a.acquisition_date)} · ${a.useful_life_months} Monate · ${esc(a.cost_center_code||'')}</small></span><strong>${money(a.book_value)}</strong><em>${money(a.monthly_depreciation)}/Monat</em></button>`).join('')||'<div class="empty"><b>Noch keine Anlagen</b></div>'}</div></section><section class="fPanel"><div class="fPanelHead"><div><small>${esc(fw)}</small><h3>Kontenrahmen</h3></div><b>${acc.length} Konten</b></div><div class="fMiniTable">${acc.map(a=>`<div><b>${esc(a.code)}</b><span>${esc(a.name)}</span><em>${esc(a.account_type)} · ${a.tax_rate}%</em></div>`).join('')}</div></section></div><section class="fPanel"><div class="fPanelHead"><div><small>KOSTENRECHNUNG</small><h3>Kostenstellen</h3></div></div><div class="costCenterGrid">${(f.cost_centers||[]).map(c=>`<article><b>${esc(c.code)}</b><span>${esc(c.name)}</span><small>${esc(c.description||'')}</small></article>`).join('')}</div></section>`}
function fRenderPlanning(f){const recurring=f.recurring||[],bud=f.budgets||[];return `<div class="fSectionHead"><div><h3>Budget, Verträge & wiederkehrende Kosten</h3><p>Planbare Ein- und Auszahlungen für Liquiditätsvorschau und Kostenkontrolle.</p></div><div class="sectionActions">${can('edit_finance')?'<button class="btn" id="fNewRecurring">+ Dauerposten</button><button class="btn primary" id="fNewBudget">+ Budget</button>':''}</div></div><div class="financeGrid2"><section class="fPanel"><div class="fPanelHead"><div><small>WIEDERKEHRENDE POSTEN</small><h3>Fixkosten & Dauereinnahmen</h3></div></div><div class="fList">${recurring.map(r=>`<div class="fStaticRow"><span><b>${esc(r.title)}</b><small>${esc(r.interval_type)} · nächste Fälligkeit ${fDate(r.next_due_date)}</small></span><strong class="${r.direction==='income'?'fPlus':'fMinus'}">${r.direction==='income'?'+':'−'} ${money(r.amount)}</strong>${can('edit_finance')?`<button class="miniBtn" data-frecurring="${esc(r.id)}">Bearbeiten</button>`:''}</div>`).join('')||'<div class="empty"><b>Keine Dauerposten</b></div>'}</div></section><section class="fPanel"><div class="fPanelHead"><div><small>BUDGETIERUNG</small><h3>Monatsbudgets</h3></div></div><div class="fList">${bud.map(b=>`<div class="fStaticRow"><span><b>${esc(b.period)} · ${esc(b.category||'Gesamt')}</b><small>${esc(b.cost_center_code||'unternehmensweit')} · ${esc(b.notes||'')}</small></span><strong>${money(b.amount)}</strong>${can('edit_finance')?`<button class="miniBtn" data-fbudget="${esc(b.id)}">Bearbeiten</button>`:''}</div>`).join('')||'<div class="empty"><b>Keine Budgets</b></div>'}</div></section></div>`}
function fExportLink(type,label,extra=''){return `<a class="fExportCard" href="./finance-export.php?type=${encodeURIComponent(type)}${extra}" target="_blank" rel="noopener"><b>${esc(label)}</b><span>CSV herunterladen</span><em>Export →</em></a>`}
function fRenderTax(f){const s=f.summary||{},conf=f.config||{};return `<div class="fSectionHead"><div><h3>Steuern, DATEV & Steuerberater</h3><p>Vorbereitende Auswertungen und standardisierte Exporte – ohne vorgetäuschte ELSTER-Liveübertragung.</p></div>${isAdmin()?'<button class="btn" id="fSettings">Buchhaltung einrichten</button>':''}</div><div class="financeMetrics compact">${fMetric('Umsatzsteuer',s.vat_output_month,'Monat')}${fMetric('Vorsteuer',s.vat_input_month,'Monat')}${fMetric('Zahllast',s.vat_due_month,'vorläufig')}</div><div class="fExportGrid">${fExportLink('vat','USt-Plausibilitätsauswertung')}${fExportLink('euer','EÜR-Arbeitsauswertung')}${fExportLink('datev','DATEV Buchungsstapel')}${fExportLink('open-items','OPOS-Liste')}${fExportLink('expenses','Eingangsbelege')}${fExportLink('assets','Anlagenverzeichnis')}</div><div class="financeGrid2"><section class="fPanel"><div class="fPanelHead"><div><small>DATEV</small><h3>Schnittstellenvorbereitung</h3></div><span class="fChip ${conf.datev_consultant_no&&conf.datev_client_no?'good':'warn'}">${conf.datev_consultant_no&&conf.datev_client_no?'konfiguriert':'Stammdaten fehlen'}</span></div><p>Kontenrahmen <b>${esc(conf.framework)}</b>, Kontenlänge <b>${esc(conf.datev_account_length)}</b>, Berater-Nr. <b>${esc(conf.datev_consultant_no||'nicht hinterlegt')}</b>, Mandant <b>${esc(conf.datev_client_no||'nicht hinterlegt')}</b>.</p></section><section class="fPanel"><div class="fPanelHead"><div><small>ELSTER / E-RECHNUNG</small><h3>Produktionsgrenze klar markiert</h3></div></div><p>Das Orgaboard bereitet Steuerdaten vor. Eine echte ELSTER-Übermittlung benötigt ERiC-Integration und Zertifikats-/Herstellerprozess. Live-Funktion wird daher nicht simuliert.</p><p class="financeFineprint">E-Rechnungsbelege (PDF/XML) können im Belegcenter revisionsorientiert abgelegt werden; strukturierte Rechnungsformate werden unverändert gespeichert.</p></section></div>`}
function fRenderClosing(f){const period=fMonth(),closing=(f.closings||[]).find(x=>x.period===period),closeLabel=closing?.status==='closed'?'Periode verwalten':'Monat abschließen',closeBtn=can('edit_finance')?`<button class="btn primary" id="fClosePeriod">${closeLabel}</button>`:'';return `<div class="fSectionHead"><div><h3>Reports & Monatsabschluss</h3><p>Exportieren, prüfen und die Buchungsperiode anschließend gegen nachträgliche Änderungen sperren.</p></div>${closeBtn}</div><div class="fExportGrid">${fExportLink('transactions','Bankumsätze')}${fExportLink('cashbook','Kassenbuch')}${fExportLink('open-items','Offene Posten')}${fExportLink('expenses','Eingangsbelege')}${fExportLink('assets','Anlagen')}${fExportLink('euer','EÜR')}</div><section class="fPanel"><div class="fPanelHead"><div><small>PERIODENSPERRE</small><h3>Abschlussjournal</h3></div><span class="fChip ${closing?.status==='closed'?'good':'warn'}">${closing?.status==='closed'?'Aktueller Monat geschlossen':'Aktueller Monat offen'}</span></div><div class="closingList">${(f.closings||[]).map(c=>`<button data-fperiod="${esc(c.period)}"><b>${esc(c.period)}</b><span>${esc(fStatus(c.status))}</span><small>${esc(c.note||'ohne Notiz')}</small><em>${c.closed_at?`geschlossen ${fDate(c.closed_at)}`:'–'}</em></button>`).join('')||'<div class="empty"><b>Noch kein Monatsabschluss</b>Nach der fachlichen Prüfung kann eine Periode gesperrt werden.</div>'}</div></section><div class="moduleNotice"><b>Abschluss-Check:</b> Bankumsätze zugeordnet · offene Belege geprüft · Kasse abgestimmt · OPOS geprüft · Steuerexport erzeugt · Sicherung/Steuerberaterübergabe durchgeführt.</div>`}
function fFormValue(id){return $('#'+id)?.value??''} function fChecked(id){return Boolean($('#'+id)?.checked)}
function fExpenseModal(e={}){const f=financeState||{};openModal(`<div class="modalHead"><small>BELEGCENTER</small><h2>${e.id?'Eingangsbeleg bearbeiten':'Eingangsbeleg erfassen'}</h2><p>${e.voucher_no?esc(e.voucher_no):'Belegnummer wird automatisch vergeben.'}</p></div><div class="modalBody"><div class="formGrid"><label class="full">Lieferant<select id="feSupplier"><option value="">– auswählen –</option>${fOption(f.suppliers||[],'id','name',e.supplier_id||'')}</select></label><label>Rechnungsnummer<input id="feInvoiceNo" value="${esc(e.invoice_no||'')}"></label><label>Rechnungsdatum<input id="feDate" type="date" value="${esc(e.invoice_date||fToday())}"></label><label>Fällig am<input id="feDue" type="date" value="${esc(e.due_date||'')}"></label><label>Brutto €<input id="feGross" inputmode="decimal" value="${esc(e.gross_amount||'')}"></label><label>USt. %<select id="feTax"><option ${sel(e.tax_rate,19)}>19</option><option ${sel(e.tax_rate,7)}>7</option><option ${sel(e.tax_rate,0)}>0</option></select></label><label>Konto<select id="feAccount"><option value="">– Konto –</option>${fOption((f.accounts||[]).filter(a=>a.framework===(f.config?.framework||'SKR03')||a.framework==='EIGEN'),'code',x=>`${x.code} · ${x.name}`,e.account_code||'')}</select></label><label>Kategorie<input id="feCategory" value="${esc(e.category||'')}"></label><label>Kostenstelle<select id="feCC"><option value="">– keine –</option>${fOption(f.cost_centers||[],'id',x=>`${x.code} · ${x.name}`,e.cost_center_id||'')}</select></label><label>Projekt<input id="feProject" value="${esc(e.project||'')}"></label><label>Zahlstatus<select id="feStatus"><option value="open" ${sel(e.payment_status,'open')}>Offen</option><option value="partial" ${sel(e.payment_status,'partial')}>Teilbezahlt</option><option value="paid" ${sel(e.payment_status,'paid')}>Bezahlt</option></select></label><label>Zahlart<input id="feMethod" value="${esc(e.payment_method||'Bank')}"></label><label class="full">Notiz<textarea id="feNotes">${esc(e.notes||'')}</textarea></label><label class="full">Belegdatei (PDF, XML, JPG/PNG/WEBP · max. 15 MB)<input id="feFile" type="file" accept=".pdf,.xml,.jpg,.jpeg,.png,.webp"></label></div><div class="formActions">${e.id&&e.receipt_available?`<a class="btn" href="./finance-receipt.php?id=${encodeURIComponent(e.id)}" target="_blank">Beleg öffnen</a>`:''}${e.id&&e.record_status!=='cancelled'?'<button class="btn danger" id="feCancel">Stornieren</button>':''}<button class="btn" id="feClose">Abbrechen</button><button class="btn primary" id="feSave">Speichern</button></div></div>`);$('#feClose').onclick=closeModal;$('#feSave').onclick=async()=>{try{const d=await financePost({action:'expense_save',id:e.id||'',supplier_id:fFormValue('feSupplier'),invoice_no:fFormValue('feInvoiceNo'),invoice_date:fFormValue('feDate'),due_date:fFormValue('feDue'),gross_amount:fFormValue('feGross'),tax_rate:fFormValue('feTax'),account_code:fFormValue('feAccount'),category:fFormValue('feCategory'),cost_center_id:fFormValue('feCC'),project:fFormValue('feProject'),payment_status:fFormValue('feStatus'),payment_method:fFormValue('feMethod'),notes:fFormValue('feNotes')});const id=d.expense_id||e.id;const file=$('#feFile')?.files?.[0];if(file&&id){const fd=new FormData();fd.append('expense_id',id);fd.append('receipt',file);const rr=await fetch('./finance-receipt.php',{method:'POST',headers:{'X-CSRF-Token':cfg.csrf||document.querySelector('.appFrame')?.dataset.csrf||''},body:fd,credentials:'same-origin'});const rd=await rr.json();if(!rr.ok||!rd.ok)throw new Error(rd.error||'Belegdatei konnte nicht gespeichert werden.');financeState=rd.finance||financeState}toast('Eingangsbeleg gespeichert');closeModal();renderFinance()}catch(err){toast(err.message,true)}};$('#feCancel')?.addEventListener('click',async()=>{const reason=prompt('Stornogrund (wird protokolliert):','');if(!reason)return;try{await financePost({action:'expense_cancel',id:e.id,reason});toast('Beleg storniert');closeModal();renderFinance()}catch(err){toast(err.message,true)}})}
function fSupplierModal(s={}){openModal(`<div class="modalHead"><small>KREDITORENSTAMM</small><h2>${s.id?'Lieferant bearbeiten':'Lieferant anlegen'}</h2></div><div class="modalBody"><div class="formGrid"><label>Lieferantennummer<input id="fsNo" value="${esc(s.supplier_no||'')}"></label><label>Name / Firma<input id="fsName" value="${esc(s.name||'')}"></label><label>Ansprechpartner<input id="fsContact" value="${esc(s.contact_name||'')}"></label><label>E-Mail<input id="fsEmail" type="email" value="${esc(s.email||'')}"></label><label>Telefon<input id="fsPhone" value="${esc(s.phone||'')}"></label><label>Zahlungsziel Tage<input id="fsTerms" type="number" min="0" value="${esc(s.payment_terms_days??14)}"></label><label class="full">Straße<input id="fsStreet" value="${esc(s.street||'')}"></label><label>PLZ<input id="fsZip" value="${esc(s.zip||'')}"></label><label>Ort<input id="fsCity" value="${esc(s.city||'')}"></label><label>IBAN<input id="fsIban" value="${esc(s.iban||'')}"></label><label>BIC<input id="fsBic" value="${esc(s.bic||'')}"></label><label>USt-IdNr.<input id="fsVat" value="${esc(s.vat_id||'')}"></label><label>Steuernummer<input id="fsTax" value="${esc(s.tax_no||'')}"></label><label class="full">Notizen<textarea id="fsNotes">${esc(s.notes||'')}</textarea></label><label class="checkLabel"><input id="fsActive" type="checkbox" ${s.active!==false?'checked':''}> Aktiv</label></div><div class="formActions"><button class="btn" id="fsClose">Abbrechen</button><button class="btn primary" id="fsSave">Speichern</button></div></div>`);$('#fsClose').onclick=closeModal;$('#fsSave').onclick=async()=>{try{await financePost({action:'supplier_save',id:s.id||'',supplier_no:fFormValue('fsNo'),name:fFormValue('fsName'),contact_name:fFormValue('fsContact'),email:fFormValue('fsEmail'),phone:fFormValue('fsPhone'),payment_terms_days:fFormValue('fsTerms'),street:fFormValue('fsStreet'),zip:fFormValue('fsZip'),city:fFormValue('fsCity'),iban:fFormValue('fsIban'),bic:fFormValue('fsBic'),vat_id:fFormValue('fsVat'),tax_no:fFormValue('fsTax'),notes:fFormValue('fsNotes'),active:fChecked('fsActive')});toast('Lieferant gespeichert');closeModal();renderFinance()}catch(err){toast(err.message,true)}}}
function fBankAccountModal(a={}){openModal(`<div class="modalHead"><small>BANKING</small><h2>Bankkonto ${a.id?'bearbeiten':'anlegen'}</h2></div><div class="modalBody"><div class="formGrid"><label>Name<input id="fbName" value="${esc(a.name||'Geschäftskonto')}"></label><label>Bank<input id="fbBank" value="${esc(a.bank_name||'')}"></label><label class="full">IBAN<input id="fbIban" value="${esc(a.iban||'')}"></label><label>BIC<input id="fbBic" value="${esc(a.bic||'')}"></label><label>Anfangssaldo<input id="fbOpening" inputmode="decimal" value="${esc(a.opening_balance??0)}"></label></div><div class="formActions"><button class="btn" id="fbClose">Abbrechen</button><button class="btn primary" id="fbSave">Speichern</button></div></div>`);$('#fbClose').onclick=closeModal;$('#fbSave').onclick=async()=>{try{await financePost({action:'bank_account_save',id:a.id||'',name:fFormValue('fbName'),bank_name:fFormValue('fbBank'),iban:fFormValue('fbIban'),bic:fFormValue('fbBic'),opening_balance:fFormValue('fbOpening'),active:true});toast('Bankkonto gespeichert');closeModal();renderFinance()}catch(err){toast(err.message,true)}}}
function fTransactionModal(t={}){const f=financeState||{},open=(f.open_receivables||[]);openModal(`<div class="modalHead"><small>BANKUMSATZ</small><h2>${t.id?'Kontoumsatz prüfen':'Kontoumsatz erfassen'}</h2></div><div class="modalBody"><div class="formGrid"><label>Bankkonto<select id="ftBank"><option value="">– auswählen –</option>${fOption(f.bank_accounts||[],'id','name',t.bank_account_id||'')}</select></label><label>Buchungsdatum<input id="ftDate" type="date" value="${esc(t.booking_date||fToday())}"></label><label>Betrag €<input id="ftAmount" inputmode="decimal" value="${esc(t.amount??'')}"></label><label>Gegenpartei<input id="ftCounter" value="${esc(t.counterparty||'')}"></label><label class="full">Verwendungszweck<textarea id="ftPurpose">${esc(t.purpose||'')}</textarea></label><label>Konto / Kategorie<input id="ftLedger" value="${esc(t.ledger_account||'')}"></label><label>USt %<input id="ftTax" inputmode="decimal" value="${esc(t.tax_rate??0)}"></label><label>Kostenstelle<select id="ftCC"><option value="">– keine –</option>${fOption(f.cost_centers||[],'id',x=>`${x.code} · ${x.name}`,t.cost_center_id||'')}</select></label><label>Projekt<input id="ftProject" value="${esc(t.project||'')}"></label>${t.id&&t.amount>0&&t.status!=='matched'?`<label class="full">Mit offener Forderung abgleichen<select id="ftOrder"><option value="">– Bestellung auswählen –</option>${fOption(open,'order_no',x=>`${x.order_no} · ${x.customer_name} · ${money(x.gross)}`,t.order_no||'')}</select></label>`:''}</div><div class="formActions">${t.id&&t.amount>0&&t.status!=='matched'?'<button class="btn" id="ftMatch">Zahlung zuordnen</button>':''}<button class="btn" id="ftClose">Abbrechen</button><button class="btn primary" id="ftSave">Speichern</button></div></div>`);$('#ftClose').onclick=closeModal;$('#ftSave').onclick=async()=>{try{await financePost({action:'transaction_save',id:t.id||'',bank_account_id:fFormValue('ftBank'),booking_date:fFormValue('ftDate'),amount:fFormValue('ftAmount'),counterparty:fFormValue('ftCounter'),purpose:fFormValue('ftPurpose'),ledger_account:fFormValue('ftLedger'),tax_rate:fFormValue('ftTax'),cost_center_id:fFormValue('ftCC'),project:fFormValue('ftProject'),status:t.status||'unassigned',order_no:t.order_no||'',document_id:t.document_id||'',source:t.source||'manual'});toast('Kontoumsatz gespeichert');closeModal();renderFinance()}catch(err){toast(err.message,true)}};$('#ftMatch')?.addEventListener('click',async()=>{const order=fFormValue('ftOrder');if(!order)return toast('Offene Forderung auswählen.',true);try{await financePost({action:'transaction_match',id:t.id,order_no:order,force:false});toast('Zahlung erfolgreich zugeordnet');closeModal();renderFinance()}catch(err){if(/passt nicht exakt/i.test(err.message)&&confirm(err.message+' Trotzdem manuell zuordnen?')){try{await financePost({action:'transaction_match',id:t.id,order_no:order,force:true});toast('Zahlung manuell zugeordnet');closeModal();renderFinance()}catch(e2){toast(e2.message,true)}}else toast(err.message,true)}})}
function fCsvParse(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)return[];const semi=(lines[0].match(/;/g)||[]).length, comma=(lines[0].match(/,/g)||[]).length,sep=semi>=comma?';':',';const parse=l=>{let out=[],v='',q=false;for(let i=0;i<l.length;i++){const c=l[i];if(c==='"'){if(q&&l[i+1]==='"'){v+='"';i++}else q=!q}else if(c===sep&&!q){out.push(v.trim());v=''}else v+=c}out.push(v.trim());return out};const head=parse(lines[0]).map(x=>x.toLowerCase().replace(/[^a-z0-9äöüß]/g,''));const ix=(...names)=>head.findIndex(h=>names.some(n=>h.includes(n)));const di=ix('buchungstag','buchungsdatum','datum'),vi=ix('valuta','wertstellung'),ai=ix('betrag','umsatz'),ci=ix('zahlungspflichtiger','zahlungsempfänger','beguenstigter','name','gegenpartei'),ii=ix('iban'),pi=ix('verwendungszweck','buchungstext','zweck'),ri=ix('referenz','kundenreferenz');const normDate=v=>{v=String(v||'').trim();let m=v.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{2,4})$/);if(m){let y=m[3];if(y.length===2)y='20'+y;return `${y}-${m[2].padStart(2,'0')}-${m[1].padStart(2,'0')}`}return v.slice(0,10)};const normMoney=v=>{v=String(v||'').replace(/\s/g,'').replace(/€/g,'');if(v.includes(',')&&v.includes('.'))v=v.lastIndexOf(',')>v.lastIndexOf('.')?v.replace(/\./g,'').replace(',','.'):v.replace(/,/g,'');else if(v.includes(','))v=v.replace(',','.');return Number(v)||0};return lines.slice(1).map((l,n)=>{const r=parse(l);return {booking_date:normDate(r[di]),value_date:vi>=0?normDate(r[vi]):'',amount:normMoney(r[ai]),counterparty:ci>=0?r[ci]:'',iban:ii>=0?r[ii]:'',purpose:pi>=0?r[pi]:'',reference:ri>=0?r[ri]:'',external_ref:''}}).filter(r=>r.booking_date&&Math.abs(r.amount)>.001)}
function fBankImportModal(){const f=financeState||{};openModal(`<div class="modalHead"><small>CSV-BANKIMPORT</small><h2>Kontoumsätze importieren</h2><p>Erkennt typische deutsche Spaltenbezeichnungen für Datum, Betrag, Gegenpartei, IBAN und Verwendungszweck.</p></div><div class="modalBody"><div class="formGrid"><label class="full">Bankkonto<select id="fiBank"><option value="">– auswählen –</option>${fOption(f.bank_accounts||[],'id','name','')}</select></label><label class="full">CSV-Datei<input id="fiFile" type="file" accept=".csv,text/csv"></label></div><div class="moduleNotice"><b>Duplikatschutz:</b> Importierte Buchungen erhalten einen technischen Fingerabdruck. Bereits vorhandene Zeilen werden beim erneuten Import übersprungen.</div><div class="formActions"><button class="btn" id="fiClose">Abbrechen</button><button class="btn primary" id="fiRun">Importieren</button></div></div>`);$('#fiClose').onclick=closeModal;$('#fiRun').onclick=async()=>{const file=$('#fiFile')?.files?.[0],bank=fFormValue('fiBank');if(!file||!bank)return toast('Bankkonto und CSV-Datei auswählen.',true);try{const rows=fCsvParse(await file.text());if(!rows.length)throw new Error('Keine verwertbaren Buchungen in der CSV erkannt.');const d=await financePost({action:'bank_import',bank_account_id:bank,rows});toast(`${d.imported||0} importiert · ${d.skipped||0} übersprungen`);closeModal();renderFinance()}catch(err){toast(err.message,true)}}}
function fCashModal(){const f=financeState||{};openModal(`<div class="modalHead"><small>KASSENBUCH</small><h2>Kassenbewegung erfassen</h2><p>Einträge sind append-only; Korrekturen erfolgen nachvollziehbar über Gegenbuchungen.</p></div><div class="modalBody"><div class="formGrid"><label>Datum<input id="fcDate" type="date" value="${fToday()}"></label><label>Art<select id="fcType"><option value="income">Einnahme</option><option value="expense" selected>Ausgabe</option><option value="deposit">Privateinlage / Einlage</option><option value="withdrawal">Entnahme</option></select></label><label>Betrag €<input id="fcAmount" inputmode="decimal"></label><label>USt %<select id="fcTax"><option>19</option><option>7</option><option selected>0</option></select></label><label class="full">Buchungstext<input id="fcDesc"></label><label>Belegnummer<input id="fcReceipt"></label><label>Konto<input id="fcAccount"></label><label>Kostenstelle<select id="fcCC"><option value="">– keine –</option>${fOption(f.cost_centers||[],'id',x=>`${x.code} · ${x.name}`,'')}</select></label></div><div class="formActions"><button class="btn" id="fcClose">Abbrechen</button><button class="btn primary" id="fcSave">Buchen</button></div></div>`);$('#fcClose').onclick=closeModal;$('#fcSave').onclick=async()=>{try{await financePost({action:'cash_save',entry_date:fFormValue('fcDate'),entry_type:fFormValue('fcType'),amount:fFormValue('fcAmount'),tax_rate:fFormValue('fcTax'),description:fFormValue('fcDesc'),receipt_no:fFormValue('fcReceipt'),account_code:fFormValue('fcAccount'),cost_center_id:fFormValue('fcCC')});toast('Kassenbewegung gebucht');closeModal();renderFinance()}catch(err){toast(err.message,true)}}}
function fDunningModal(r){if(!r)return;openModal(`<div class="modalHead"><small>FORDERUNGSMANAGEMENT</small><h2>${esc(r.customer_name||'Kunde')}</h2><p>${esc(r.document_no||r.order_no)} · ${money(r.gross)}</p></div><div class="modalBody"><div class="financeMetrics compact">${fMetric('Fällig',fDate(r.due_date),`${r.days_overdue||0} Tage überfällig`)}${fMetric('Offen',fNum(r.gross)+fNum(r.dunning_fees),'inkl. Gebühren')}</div><div class="formGrid"><label>Mahnstufe<select id="fdLevel"><option value="0" ${sel(r.dunning_level,0)}>0 · Keine</option><option value="1" ${sel(r.dunning_level,1)}>1 · Zahlungserinnerung</option><option value="2" ${sel(r.dunning_level,2)}>2 · Mahnung</option><option value="3" ${sel(r.dunning_level,3)}>3 · Letzte Mahnung</option></select></label><label>Nächste Frist<input id="fdDue" type="date" value="${esc(r.due_date||'')}"></label><label>Mahngebühren €<input id="fdFees" inputmode="decimal" value="${esc(r.dunning_fees??0)}"></label><label>Verzugszins %<input id="fdInterest" inputmode="decimal" value="${esc(r.interest_rate??0)}"></label><label class="full">Notiz<textarea id="fdNotes">${esc(r.dunning_notes||'')}</textarea></label><label class="checkLabel"><input id="fdBlocked" type="checkbox" ${r.dunning_blocked?'checked':''}> Mahnlauf sperren</label></div><div class="formActions"><button class="btn" id="fdClose">Abbrechen</button><button class="btn" id="fdPrint">Mahnung drucken / PDF</button><button class="btn" id="fdMail">Per E-Mail</button><button class="btn primary" id="fdSave">Speichern</button></div></div>`);$('#fdClose').onclick=closeModal;$('#fdPrint').onclick=()=>window.open('./finance-dunning.php?order_no='+encodeURIComponent(r.order_no),'_blank','noopener');$('#fdMail').onclick=async()=>{if(!confirm('Aktuelle Mahnung als PDF an die hinterlegte Kunden-E-Mail senden?'))return;try{await financePost({action:'dunning_update',order_no:r.order_no,dunning_level:fFormValue('fdLevel'),next_due_date:fFormValue('fdDue'),fees:fFormValue('fdFees'),interest_rate:fFormValue('fdInterest'),blocked:fChecked('fdBlocked'),notes:fFormValue('fdNotes')});await financePost({action:'dunning_email',order_no:r.order_no});toast('Mahnstatus gespeichert und Mahnung per E-Mail versendet');closeModal();renderFinance()}catch(err){toast(err.message,true)}};$('#fdSave').onclick=async()=>{try{await financePost({action:'dunning_update',order_no:r.order_no,dunning_level:fFormValue('fdLevel'),next_due_date:fFormValue('fdDue'),fees:fFormValue('fdFees'),interest_rate:fFormValue('fdInterest'),blocked:fChecked('fdBlocked'),notes:fFormValue('fdNotes')});toast('Mahnstatus gespeichert');closeModal();renderFinance()}catch(err){toast(err.message,true)}}}
function fAssetModal(a={}){const f=financeState||{};openModal(`<div class="modalHead"><small>ANLAGENBUCHHALTUNG</small><h2>${a.id?'Anlagegut bearbeiten':'Anlagegut anlegen'}</h2></div><div class="modalBody"><div class="formGrid"><label class="full">Bezeichnung<input id="faName" value="${esc(a.name||'')}"></label><label>Kategorie<input id="faCategory" value="${esc(a.category||'')}"></label><label>Anschaffungsdatum<input id="faDate" type="date" value="${esc(a.acquisition_date||fToday())}"></label><label>Anschaffungswert €<input id="faPrice" inputmode="decimal" value="${esc(a.purchase_price??'')}"></label><label>Nutzungsdauer Monate<input id="faLife" type="number" min="1" value="${esc(a.useful_life_months??36)}"></label><label>Restwert €<input id="faResidual" inputmode="decimal" value="${esc(a.residual_value??0)}"></label><label>Konto<input id="faAccount" value="${esc(a.account_code||'')}"></label><label>Kostenstelle<select id="faCC"><option value="">– keine –</option>${fOption(f.cost_centers||[],'id',x=>`${x.code} · ${x.name}`,a.cost_center_id||'')}</select></label><label class="full">Notizen<textarea id="faNotes">${esc(a.notes||'')}</textarea></label></div><div class="formActions"><button class="btn" id="faClose">Abbrechen</button><button class="btn primary" id="faSave">Speichern</button></div></div>`);$('#faClose').onclick=closeModal;$('#faSave').onclick=async()=>{try{await financePost({action:'asset_save',id:a.id||'',name:fFormValue('faName'),category:fFormValue('faCategory'),acquisition_date:fFormValue('faDate'),purchase_price:fFormValue('faPrice'),useful_life_months:fFormValue('faLife'),residual_value:fFormValue('faResidual'),account_code:fFormValue('faAccount'),cost_center_id:fFormValue('faCC'),notes:fFormValue('faNotes'),active:true});toast('Anlagegut gespeichert');closeModal();renderFinance()}catch(err){toast(err.message,true)}}}
function fCostCenterModal(){openModal(`<div class="modalHead"><small>KOSTENRECHNUNG</small><h2>Kostenstelle anlegen</h2></div><div class="modalBody"><div class="formGrid"><label>Code<input id="fccCode"></label><label>Name<input id="fccName"></label><label class="full">Beschreibung<textarea id="fccDesc"></textarea></label></div><div class="formActions"><button class="btn" id="fccClose">Abbrechen</button><button class="btn primary" id="fccSave">Speichern</button></div></div>`);$('#fccClose').onclick=closeModal;$('#fccSave').onclick=async()=>{try{await financePost({action:'cost_center_save',code:fFormValue('fccCode'),name:fFormValue('fccName'),description:fFormValue('fccDesc'),active:true});toast('Kostenstelle gespeichert');closeModal();renderFinance()}catch(e){toast(e.message,true)}}}
function fAccountModal(){const f=financeState||{};openModal(`<div class="modalHead"><small>KONTENRAHMEN</small><h2>Buchungskonto anlegen</h2></div><div class="modalBody"><div class="formGrid"><label>Kontenrahmen<select id="facFw"><option ${sel(f.config?.framework,'SKR03')}>SKR03</option><option ${sel(f.config?.framework,'SKR04')}>SKR04</option><option>EIGEN</option></select></label><label>Kontonummer<input id="facCode"></label><label class="full">Bezeichnung<input id="facName"></label><label>Typ<select id="facType"><option value="expense">Aufwand</option><option value="revenue">Erlös</option><option value="asset">Aktiva</option><option value="liability">Passiva</option><option value="tax">Steuer</option></select></label><label>USt %<input id="facTax" value="19"></label></div><div class="formActions"><button class="btn" id="facClose">Abbrechen</button><button class="btn primary" id="facSave">Speichern</button></div></div>`);$('#facClose').onclick=closeModal;$('#facSave').onclick=async()=>{try{await financePost({action:'account_save',framework:fFormValue('facFw'),code:fFormValue('facCode'),name:fFormValue('facName'),account_type:fFormValue('facType'),tax_rate:fFormValue('facTax'),active:true});toast('Konto gespeichert');closeModal();renderFinance()}catch(e){toast(e.message,true)}}}
function fRecurringModal(r={}){const f=financeState||{};openModal(`<div class="modalHead"><small>PLANUNG</small><h2>Dauerposten ${r.id?'bearbeiten':'anlegen'}</h2></div><div class="modalBody"><div class="formGrid"><label class="full">Bezeichnung<input id="frTitle" value="${esc(r.title||'')}"></label><label>Richtung<select id="frDir"><option value="expense" ${sel(r.direction||'expense','expense')}>Ausgabe</option><option value="income" ${sel(r.direction,'income')}>Einnahme</option></select></label><label>Betrag €<input id="frAmount" inputmode="decimal" value="${esc(r.amount??'')}"></label><label>Intervall<select id="frInterval"><option value="monthly" ${sel(r.interval_type||'monthly','monthly')}>Monatlich</option><option value="quarterly" ${sel(r.interval_type,'quarterly')}>Quartalsweise</option><option value="yearly" ${sel(r.interval_type,'yearly')}>Jährlich</option></select></label><label>Nächste Fälligkeit<input id="frDue" type="date" value="${esc(r.next_due_date||fToday())}"></label><label>Lieferant<select id="frSupplier"><option value="">– keiner –</option>${fOption(f.suppliers||[],'id','name',r.supplier_id||'')}</select></label><label>Kategorie<input id="frCategory" value="${esc(r.category||'')}"></label><label>Konto<input id="frAccount" value="${esc(r.account_code||'')}"></label><label>Kostenstelle<select id="frCC"><option value="">– keine –</option>${fOption(f.cost_centers||[],'id',x=>`${x.code} · ${x.name}`,r.cost_center_id||'')}</select></label><label>USt %<input id="frTax" value="${esc(r.tax_rate??19)}"></label><label class="checkLabel"><input id="frActive" type="checkbox" ${r.active===false?'':'checked'}> Aktiv</label></div><div class="formActions"><button class="btn" id="frClose">Abbrechen</button><button class="btn primary" id="frSave">Speichern</button></div></div>`);$('#frClose').onclick=closeModal;$('#frSave').onclick=async()=>{try{await financePost({action:'recurring_save',id:r.id||'',title:fFormValue('frTitle'),direction:fFormValue('frDir'),amount:fFormValue('frAmount'),tax_rate:fFormValue('frTax'),interval_type:fFormValue('frInterval'),next_due_date:fFormValue('frDue'),supplier_id:fFormValue('frSupplier'),category:fFormValue('frCategory'),account_code:fFormValue('frAccount'),cost_center_id:fFormValue('frCC'),active:fChecked('frActive')});toast('Dauerposten gespeichert');closeModal();renderFinance()}catch(e){toast(e.message,true)}}}
function fBudgetModal(b={}){const f=financeState||{};openModal(`<div class="modalHead"><small>BUDGET</small><h2>Monatsbudget ${b.id?'bearbeiten':'anlegen'}</h2></div><div class="modalBody"><div class="formGrid"><label>Periode<input id="fbuPeriod" type="month" value="${esc(b.period||fMonth())}"></label><label>Betrag €<input id="fbuAmount" inputmode="decimal" value="${esc(b.amount??'')}"></label><label>Kostenstelle<select id="fbuCC"><option value="">Unternehmensweit</option>${fOption(f.cost_centers||[],'id',x=>`${x.code} · ${x.name}`,b.cost_center_id||'')}</select></label><label>Kategorie<input id="fbuCategory" value="${esc(b.category||'')}"></label><label class="full">Notiz<textarea id="fbuNotes">${esc(b.notes||'')}</textarea></label></div><div class="formActions"><button class="btn" id="fbuClose">Abbrechen</button><button class="btn primary" id="fbuSave">Speichern</button></div></div>`);$('#fbuClose').onclick=closeModal;$('#fbuSave').onclick=async()=>{try{await financePost({action:'budget_save',id:b.id||'',period:fFormValue('fbuPeriod'),amount:fFormValue('fbuAmount'),cost_center_id:fFormValue('fbuCC'),category:fFormValue('fbuCategory'),notes:fFormValue('fbuNotes')});toast('Budget gespeichert');closeModal();renderFinance()}catch(e){toast(e.message,true)}}}
function fSettingsModal(){const c=financeState?.config||{};openModal(`<div class="modalHead"><small>FINANZ-STAMMDATEN</small><h2>Buchhaltung einrichten</h2></div><div class="modalBody"><div class="formGrid"><label>Kontenrahmen<select id="fstFw"><option ${sel(c.framework,'SKR03')}>SKR03</option><option ${sel(c.framework,'SKR04')}>SKR04</option><option ${sel(c.framework,'EIGEN')}>EIGEN</option></select></label><label>Gewinnermittlung<select id="fstMethod"><option ${sel(c.accounting_method,'EÜR')}>EÜR</option><option ${sel(c.accounting_method,'Bilanz')}>Bilanz</option></select></label><label>USt-Versteuerung<select id="fstVat"><option ${sel(c.vat_mode,'Soll')}>Soll</option><option ${sel(c.vat_mode,'Ist')}>Ist</option></select></label><label>Standard-Zahlungsziel<input id="fstDays" type="number" value="${esc(c.default_payment_days??14)}"></label><label>Kassen-Anfangsbestand<input id="fstCash" inputmode="decimal" value="${esc(c.cash_opening_balance??0)}"></label><label>Liquiditätswarnung €<input id="fstLiq" inputmode="decimal" value="${esc(c.liquidity_min??3000)}"></label><label>DATEV Beraternummer<input id="fstConsultant" value="${esc(c.datev_consultant_no||'')}"></label><label>DATEV Mandantennummer<input id="fstClient" value="${esc(c.datev_client_no||'')}"></label><label>DATEV Kontenlänge<input id="fstLen" type="number" min="4" max="8" value="${esc(c.datev_account_length??4)}"></label><label>DATEV Diktatkürzel<input id="fstDict" value="${esc(c.datev_dictation_code||'BH')}"></label></div><div class="moduleNotice"><b>Wichtig:</b> Diese Werte konfigurieren die interne Buchhaltung und Exporte. Steuerliche Einordnung im Zweifel mit Steuerberatung abstimmen.</div><div class="formActions"><button class="btn" id="fstClose">Abbrechen</button><button class="btn primary" id="fstSave">Speichern</button></div></div>`);$('#fstClose').onclick=closeModal;$('#fstSave').onclick=async()=>{try{await financePost({action:'settings_save',finance_framework:fFormValue('fstFw'),finance_accounting_method:fFormValue('fstMethod'),finance_vat_mode:fFormValue('fstVat'),finance_default_payment_days:fFormValue('fstDays'),finance_cash_opening_balance:fFormValue('fstCash'),finance_datev_consultant_no:fFormValue('fstConsultant'),finance_datev_client_no:fFormValue('fstClient'),finance_datev_account_length:fFormValue('fstLen'),finance_datev_dictation_code:fFormValue('fstDict'),finance_alert_liquidity_min:fFormValue('fstLiq')});toast('Buchhaltungseinstellungen gespeichert');closeModal();renderFinance()}catch(e){toast(e.message,true)}}}
function fPeriodModal(period,closing=null){const closed=closing?.status==='closed';openModal(`<div class="modalHead"><small>MONATSABSCHLUSS</small><h2>Periode ${esc(period)}</h2><p>${closed?'Diese Periode ist gegen nachträgliche Finanzbuchungen gesperrt.':'Nach dem Abschluss werden Finanzbuchungen dieser Periode blockiert.'}</p></div><div class="modalBody"><div class="moduleNotice"><b>Vorher prüfen:</b> Bankabgleich, OPOS, Lieferantenbelege, Kassenbestand, Steuer-Auswertung und Belegvollständigkeit.</div><label class="full">${closed?'Grund für Wiederöffnung':'Abschlussnotiz'}<textarea id="fpNote">${esc(closing?.note||'')}</textarea></label><div class="formActions"><button class="btn" id="fpClose">Abbrechen</button>${closed&&isAdmin()?'<button class="btn danger" id="fpReopen">Protokolliert wieder öffnen</button>':(!closed&&can('edit_finance')?'<button class="btn primary" id="fpLock">Periode abschließen</button>':'')}</div></div>`);$('#fpClose').onclick=closeModal;$('#fpLock')?.addEventListener('click',async()=>{if(!confirm(`Periode ${period} wirklich abschließen und sperren?`))return;try{await financePost({action:'period_close',period,note:fFormValue('fpNote')});toast('Periode abgeschlossen');closeModal();renderFinance()}catch(e){toast(e.message,true)}});$('#fpReopen')?.addEventListener('click',async()=>{const reason=fFormValue('fpNote');if(reason.trim().length<5)return toast('Nachvollziehbaren Grund eintragen.',true);if(!confirm(`Periode ${period} wieder öffnen? Dies wird protokolliert.`))return;try{await financePost({action:'period_reopen',period,reason});toast('Periode wieder geöffnet');closeModal();renderFinance()}catch(e){toast(e.message,true)}})}
