// delegated actions
document.addEventListener('click',e=>{const o=e.target.closest('[data-open-order]');if(o)return can('view_orders')?openOrder(o.dataset.openOrder):(can('edit_production')?productionEditModal(o.dataset.openOrder):toast('Nur Produktionsansicht freigegeben.',true));const p=e.target.closest('[data-open-proto]');if(p)return openPrototype(p.dataset.openProto);const c=e.target.closest('[data-open-customer]');if(c)return openCustomer(c.dataset.openCustomer);const d=e.target.closest('[data-open-dealer]');if(d)return dealerModal(d.dataset.openDealer);const dv=e.target.closest('[data-dealer-visit]');if(dv)return dealerVisitModal(dv.dataset.dealerVisit);const pr=e.target.closest('[data-open-product]');if(pr)return productModal(pr.dataset.openProduct);const s=e.target.closest('[data-save-stock]');if(s)return saveStock(s.dataset.saveStock);const i=e.target.closest('[data-print-invoice]');if(i){const order=(state.orders||[]).find(x=>(x.order_no||x.id)===i.dataset.printInvoice);if(order)return printInvoice(order)}const doc=e.target.closest('[data-doc-order]');if(doc)return openDocumentForOrder(doc.dataset.docOrder,doc.dataset.docType);const th=e.target.closest('[data-thread]');if(th)return openMessageThread(th.dataset.thread);const us=e.target.closest('[data-user]');if(us)return userModal(us.dataset.user);const ct=e.target.closest('[data-content]');if(ct)return contentModal(ct.dataset.content);const ca=e.target.closest('[data-customer-appointment]');if(ca&&can('edit_appointments')){const customerId=ca.dataset.customerAppointment,cu=(state.customers||[]).find(x=>x.id===customerId);appointmentSelectedDate=new Date().toISOString().slice(0,10);appointmentPeriod=appointmentSelectedDate.slice(0,7);appointmentRepId=isAdmin()?(cu?.sales_rep_id||''):(state.current_user?.sales_rep_id||'');appointmentData=null;return (async()=>{await appointmentLoad(appointmentPeriod,appointmentRepId);setView('appointments');appointmentModal(null,customerId)})()}const no=e.target.closest('[data-new-order]');if(no&&can('create_orders'))return manualOrderModal(no.dataset.newOrder,[],(state.customers||[]).find(c=>c.id===no.dataset.newOrder)?.sales_rep_id||'');const pc=e.target.closest('[data-pick-customer]');if(pc){salesCustomerId=pc.dataset.pickCustomer;salesAdvice=null;return renderSales()}const er=e.target.closest('[data-edit-rep]');if(er&&isAdmin())return salesRepModal(er.dataset.editRep)});
$$('.navItem').forEach(b=>b.onclick=()=>{setView(b.dataset.view);$('#sideNav').classList.remove('open')});$$('[data-mobile-view]').forEach(b=>b.onclick=()=>setView(b.dataset.mobileView));$$('[data-quick-view]').forEach(b=>b.onclick=()=>setView(b.dataset.quickView));const moreBtn=$('[data-mobile-more]');if(moreBtn)moreBtn.onclick=()=>$('#sideNav').classList.toggle('open');$('#mobileMenu').onclick=()=>$('#sideNav').classList.toggle('open');$('#refreshBtn').onclick=()=>load();$('#modalClose').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()};$('#globalSearch').oninput=e=>{const value=e.target.value.trim();if(['products','productbuilder','nature_spices','product_analysis'].includes(current)){productSearchTerm=value;clearTimeout(productSearchTimer);productSearchTimer=setTimeout(()=>{if(current!=='products')setView('products',true);else renderProducts()},260);return}searchTerm=value;if(!searchTerm)return render();if(current==='dashboard')setView('orders',true);else render()};$('#globalSearch').onkeydown=e=>{if(e.key==='Enter'&&['products','productbuilder','nature_spices','product_analysis'].includes(current)){e.preventDefault();clearTimeout(productSearchTimer);productSearchTerm=e.target.value.trim();if(current!=='products')setView('products',true);else renderProducts()}};
